-- SOP ฉบับที่ลูกค้าใช้อยู่จริง ดึงสดจากหน้าเว็บของเขาเมื่อ 27 กันยายน 2569
-- (33 กรณี · 649 ขั้นตอน · 34 เอกสารแนบ · 24 รายงาน · คำบรรยายผัง 33 ผัง)
--
-- เทียบกับฉบับที่เรานำเข้าเมื่อ 19 กันยายน พบว่า
--   • เขาจัดเรียงเลขกรณีใหม่ทั้งชุด และให้รหัสแสดงผลรายหมวด (PO-1, FA-5 …)
--   • เพิ่มกรณีที่ 33 และเขียนข้อความหลายกรณีใหม่ (เช่น "(ผู้รับผิดชอบ: X)" → "[X]")
--   • คำบรรยายขั้นตอนของผังกระบวนการ 33 ผัง ของเราว่างทั้งหมด ของเขามีครบ — เติมให้ครบ
--
-- ฉบับเดิมเก็บเข้าประวัติเวอร์ชันก่อนเขียนทับ กู้คืนได้จากหน้า SOP
-- เพิ่ม/แก้ข้อมูลเท่านั้น ไม่แตะโครงตาราง
-- ═══════════════════════════════════════════════════════════════════════════

insert into sop_versions (data, note)
select jsonb_build_object(
  'meta', (select to_jsonb(mt) from sop_meta mt where mt.id = true),
  'scenarios', coalesce((select jsonb_agg(to_jsonb(s) order by s.module, s.sort_order, s.no) from sop_scenarios s), '[]'::jsonb),
  'steps', coalesce((select jsonb_agg(to_jsonb(st) order by st.scenario_no, st.step_order) from sop_scenario_steps st), '[]'::jsonb),
  'tags', coalesce((select jsonb_agg(to_jsonb(t) order by t.scenario_no, t.module) from sop_scenario_modules t), '[]'::jsonb),
  'reports', coalesce((select jsonb_agg(to_jsonb(r) order by r.id) from sop_reports r), '[]'::jsonb),
  'flows', coalesce((select jsonb_agg(to_jsonb(f) order by f.module, f.id) from sop_flows f), '[]'::jsonb),
  'modules', coalesce((select jsonb_agg(to_jsonb(md) order by md.sort_order, md.code) from sop_modules md), '[]'::jsonb),
  'attachments', coalesce((select jsonb_agg(to_jsonb(a) order by a.scenario_no, a.sort) from sop_scenario_attachments a), '[]'::jsonb)
), 'ฉบับก่อนนำเข้าฉบับ 27 กันยายน 2569 (32 กรณี)';

create temp table _sop_live2 on commit drop as select $sop${"meta":{"title":"Standard Operating Procedure","subtitle":"ระเบียบปฏิบัติมาตรฐาน · กลุ่มวิจิตรภัณฑ์ก่อสร้าง","manual":"Mango ERP Manual 14.3.68","version":"v1.0 (Revised)","effective":"เมษายน 2569","scope":"บุคลากรทุกคนของบริษัทและบริษัทในเครือ ครอบคลุมงานทั้งในและนอกระบบ Mango ERP","purpose":"เอกสารฉบับนี้เป็นระเบียบปฏิบัติมาตรฐาน (Standard Operating Procedure – SOP) ของกลุ่มวิจิตรภัณฑ์ก่อสร้าง ครอบคลุมกระบวนการทำงานขององค์กรโดยรวม ทั้งขั้นตอนการปฏิบัติงานในระบบ Mango ERP และขั้นตอนการปฏิบัติงานนอกระบบ เช่น การจัดทำและจัดเก็บเอกสาร การสอบทานและการอนุมัติ และการประสานงานระหว่างหน่วยงาน ทั้งนี้ ในส่วนที่เกี่ยวข้องกับระบบ ERP จัดทำขึ้นโดยอ้างอิง Mango ERP Manual 14.3.68 และกรณีปัญหาที่เกิดขึ้นจริงในการปฏิบัติงาน ครอบคลุมทุกโมดูลของระบบ ได้แก่ PO (จัดซื้อ), IC (คลังสินค้า), AP (เจ้าหนี้/จ่าย), AR (ลูกหนี้/รับ), FA (ทรัพย์สิน), PM (โครงการ), BD (งบประมาณ), OF (เบิกจ่าย), GL (บัญชีแยกประเภท) และ SE (ตั้งค่าระบบ)\n\n1. วัตถุประสงค์\n\n• กำหนดมาตรฐานการปฏิบัติงานให้เป็นไปในแนวทางเดียวกันทั้งองค์กร\n\n• ลดความผิดพลาดและความซ้ำซ้อนในการบันทึกข้อมูลและการจัดทำเอกสาร\n\n• เสริมสร้างระบบการควบคุมภายในและการตรวจสอบย้อนกลับ (Audit Trail) ที่มีประสิทธิภาพ\n\n• รักษาความถูกต้อง ครบถ้วน และเชื่อถือได้ของข้อมูลทางบัญชีและการเงิน\n\n• รองรับการปรับเปลี่ยนองค์กรสู่ระบบดิจิทัล (Digital Transformation) อย่างเป็นระบบ\n\n• ใช้เป็นเอกสารอ้างอิงในการปฏิบัติงาน การสอบทาน และการฝึกอบรมบุคลากร\n\n2. ขอบเขตการบังคับใช้\n\n• บังคับใช้กับพนักงานและบุคคลภายนอกทุกรายที่ปฏิบัติงานให้แก่บริษัทและบริษัทในเครือ ครอบคลุมทุกหน่วยงานและทุกโครงการ\n\n• ครอบคลุมทั้งขั้นตอนที่ดำเนินการในระบบ Mango ERP และขั้นตอนที่ดำเนินการนอกระบบ ERP\n\n• ถือเป็นนโยบายของบริษัทที่มีผลผูกพันและบังคับใช้ทันทีนับแต่วันที่มีผลตามที่ระบุไว้ในหน้าข้อมูลเอกสาร\n\n• ใช้บังคับแทนแนวปฏิบัติหรือข้อตกลงใด ๆ ที่ขัดหรือแย้งกับเอกสารฉบับนี้ที่มีอยู่ก่อนหน้า\n\n3. การถือปฏิบัติและการทบทวน\n\n• ผู้ปฏิบัติงานทุกราย: ศึกษา ทำความเข้าใจ และปฏิบัติตามระเบียบที่กำหนดไว้ในเอกสารฉบับนี้อย่างเคร่งครัด\n\n• ผู้บังคับบัญชาตามสายงาน: กำกับดูแลให้ผู้ใต้บังคับบัญชาปฏิบัติตามโดยครบถ้วน\n\n• การไม่ปฏิบัติตามระเบียบนี้ อันเป็นเหตุให้ข้อมูลคลาดเคลื่อน เกิดความเสียหาย หรือกระทบต่อการควบคุมภายใน บริษัทจะพิจารณาดำเนินการตามระเบียบข้อบังคับเกี่ยวกับการทำงานและกฎหมายที่เกี่ยวข้องต่อไป\n\n• การแก้ไข เพิ่มเติม หรือยกเลิกข้อความส่วนหนึ่งส่วนใดของเอกสารฉบับนี้ จะมีผลสมบูรณ์ต่อเมื่อได้รับอนุมัติจากผู้มีอำนาจอนุมัติตามที่ระบุไว้ในหน้าข้อมูลเอกสารแล้วเท่านั้น\n\n• หากพบข้อขัดแย้งระหว่างระเบียบฉบับนี้กับการปฏิบัติงานจริงหรือกับคู่มือระบบ ให้ผู้ปฏิบัติงานแจ้งฝ่ายระบบหรือฝ่ายบัญชีโดยทันทีเพื่อดำเนินการทบทวนและปรับปรุงต่อไป","notes":["เอกสารนี้ครอบคลุมกระบวนการทำงานทั้งในและนอกระบบ ERP · ในส่วนที่เกี่ยวข้องกับระบบ ERP จัดทำขึ้นตาม Mango ERP Manual 14.3.68 โดยอ้างอิงกรณีปัญหาจริงที่เกิดขึ้น","SOP นี้ให้ถือเป็นนโยบายบริษัทที่มีผลบังคับใช้ทันทีหลังได้รับการอนุมัติจากผู้บริหาร","หากพบข้อขัดแย้งระหว่าง SOP นี้กับการปฏิบัติจริง ให้แจ้งแผนกระบบ/บัญชีทันทีเพื่อทบทวนและปรับปรุง","สัญลักษณ์  [✓] = ยืนยันสอดคล้องกับ ERP Manual 14.3.68  |  [!] = จุดที่ต้องปรับปรุงหรือกำหนดเพิ่มเติม"]},"scenarios":[{"no":1,"module":"PO","display_no":"PO-1","sort_order":1,"title_th":"กรณีต้องลดยอดหรือปิด PO ที่ไม่ได้ส่งมอบ","title_en":"Reduce or Close an Undelivered PO","problem":"ใช้เมื่อสินค้าที่สั่งไว้จะไม่ได้รับการส่งมอบ จึงต้องลดยอดหรือปิดใบสั่งซื้อ (PO) ไม่ให้มียอดค้างสะสมในระบบ แนวทางขึ้นกับสถานะการชำระเงิน: ยังไม่ตั้งหนี้ (ข้อ 1) · ตั้งหนี้แล้วแต่ยังไม่จ่าย (ข้อ 2) · จ่ายเงินแล้ว (ข้อ 3) หากได้รับสินค้าแล้วแต่ราคาไม่ตรงกับ PO ให้ดูที่ PO-2","ref":"ERP Manual 14.3.68 – บทที่ 4 (PO)","note":"สรุปผลลัพธ์ จัดซื้อต้องไม่มีใบสั่งซื้อคงค้างสะสม (Stale PO) ยอดงบประมาณและข้อมูลการจัดซื้อเฉลี่ยสะท้อนความเป็นจริง ไม่ส่งผลกระทบต่อความเร็วการประมวลผลรายงานของระบบ และ ยอดตั้งหนี้และยอดจ่ายจริงของฝ่ายบัญชีต้องสอดคล้องกับสินค้าที่รับเข้ามา และมีเอกสารทางภาษีควบคุมการลดหนี้ (Credit Note) ที่ถูกต้องตรวจสอบย้อนหลังได้ทุกรายการ","date_added":"1 เมษายน 2569","steps":[{"style":"num","text":"กรณีที่ 1: ยังไม่มีการตั้งหนี้ใดๆ ในระบบ (ยังไม่มีเอกสาร APV)"},{"style":"sub","text":"[แผนกจัดซื้อ/พัสดุ] ตรวจสอบประวัติการรับสินค้า (PO Receive) ของ PO ใบนั้นๆ ว่ามีการรับของไปแล้วจริงจำนวนเท่าใด มียอดค้างส่งจริงเท่าใด และทำการกดยืนยันสถานะร่วมกับแผนกวิศวกรรมหน้างานและร้านค้าคู่ค้าเพื่อเริ่มกระบวนการลดยอด"},{"style":"sub","text":"[แผนกจัดซื้อ] ดำเนินการลดยอดใบสั่งซื้อ (PO Decrement) เฉพาะรายการสินค้าที่ค้างส่งใน PO ใบดังกล่าว ➔ ระบุจำนวนที่ต้องการลดยอดลงในช่อง QTY Decrement ➔ ระบุเหตุผลรายละเอียดเพิ่มเติมในช่องหมายเหตุ ➔ บันทึกรายการเพื่อปิดสถานะ PO"},{"style":"sub","text":"[แผนกบัญชี] ไม่ต้องทำรายการปรับปรุงใดๆ ในส่วนนี้ ให้ดำเนินการตรวจสอบและบันทึกตั้งหนี้ (APV) และทำจ่ายเงินเฉพาะยอดสินค้าที่มีการรับเข้ามาจริงแล้วเท่านั้น"},{"style":"num","text":"กรณีที่แผนกบัญชีตั้งหนี้ไป 100% และทำใบเตรียมจ่าย (Pre-Payment/APP) ไปแล้ว แต่ยังไม่ได้จ่ายเงิน"},{"style":"sub","text":"[ผู้มีอำนาจอนุมัติ] ดำเนินการยกเลิกการอนุมัติใบเตรียมจ่าย โดยเข้าไปที่ Module AP ➔ ดำเนินการ ➔ หมวดอนุมัติจ่าย ➔ เลือกเมนู ยกเลิกการอนุมัติจ่าย ➔ ระบุเหตุผลในการยกเลิกและกดปุ่มยืนยัน ➔ ส่งผลให้ชุดเตรียมจ่าย (APP) ถูกยกเลิก และเอกสารตั้งหนี้ (APV) จะถูกปลดล็อกกลับมาสู่สถานะแก้ไขได้"},{"style":"sub","text":"[แผนกบัญชี] เข้าไปที่เอกสาร APV ➔ กดปุ่ม Cancel Submit หรือลบเอกสาร APV นั้นออก เพื่อให้ระบบคืนยอด PO"},{"style":"sub","text":"[แผนกจัดซื้อ] ดำเนินการลดยอดค้างส่งตามขั้นตอนใน กรณีที่ 1 (PO Decrement) เพื่อปิดรายการที่ไม่ได้ส่งมอบให้ถูกต้อง"},{"style":"num","text":"กรณีที่แผนกบัญชีตั้งหนี้ไป 100% และแผนกการเงินทำจ่ายเงินเรียบร้อยแล้ว"},{"style":"sub","text":"[แผนกบัญชี] ดำเนินการสร้างใบลดหนี้ในระบบเพื่อปรับปรุงยอด โดยเข้าไปที่ Module AP ➔ เลือกเมนู บันทึกการลดหนี้ (Credit Note) ➔ กดเลือก ลดหนี้จาก APV ➔ ค้นหาและเลือกรายการตั้งหนี้ (APV) ใบเดิมที่ทำการจ่ายเงินเกิน ➔ ระบุยอดเงินส่วนต่างที่ต้องการลดหนี้ในช่อง Amount ➔ ตรวจสอบความถูกต้องทางบัญชีเพิ่มเติมในแท็บ General Ledger, Material หรือ Tax ให้เรียบร้อยแล้วกดบันทึก (ระบบจะสร้างแบบฟอร์มใบสำคัญลดหนี้ให้โดยอัตโนมัติ)"},{"style":"sub","text":"[แผนกการเงิน/บัญชี] ติดต่อประสานงานกับร้านค้าคู่ค้าเพื่อติดตามเรียกคืนเงินส่วนต่างที่จ่ายเกินจริงกลับเข้าบัญชีบริษัท"},{"style":"sub","text":"[แผนกจัดซื้อ] ดำเนินการลดยอดใบสั่งซื้อค้างส่งตามขั้นตอนใน กรณีที่ 1 (PO Decrement) เพื่อล้างยอดและปิดสถานะ PO ในระบบให้เรียบร้อยเป็นขั้นตอนสุดท้าย"}],"extra":["AP"],"attachments":[{"label":"SOP-01 · PO Decrement","url":"https://drive.google.com/file/d/1xPP1G4drq-DZENWeSIVYR85WkcN42V9l/view"}]},{"no":2,"module":"PO","display_no":"PO-2","sort_order":2,"title_th":"กรณีราคาไม่ตรงกับ PO ต้องแก้ไขราคา","title_en":"Correct a Price That Does Not Match the PO","problem":"ใช้เมื่อราคาสินค้าที่ได้รับหรือที่ระบุในใบกำกับภาษีไม่ตรงกับราคาใน PO เช่น ร้านค้าแจ้งปรับราคาภายหลัง หรือส่งใบกำกับภาษีตามมาทีหลัง PO ยังคงอยู่และแก้ไขให้ถูกต้อง แนวทางขึ้นกับสถานะการรับของและการชำระเงิน: ยังไม่รับของครบ (ข้อ 1) · รับของแล้วยังไม่จ่าย (ข้อ 2) · จ่ายแล้ว (ข้อ 3-4) หากไม่ได้รับสินค้าตามที่สั่ง ให้ดูที่ PO-1","ref":"ERP Manual 14.3.68 – บทที่ 4 (PO)","note":"กรณี 3 และ 4 เกิดเฉพาะการซื้อแบบชำระเงินหลังส่งมอบกับสินค้าที่ราคาผันผวน เช่น หิน / ทราย สำหรับการชำระเงินก่อนส่งมอบกับร้านค้าที่ไม่ยืนราคา PO-3 กำหนดห้ามเปิด PO คลุมไว้แล้ว","date_added":"1 เมษายน 2569","steps":[{"style":"num","text":"ในกรณีที่ยังไม่มีการรับของหรือยังรับของไม่เต็มจำนวน PO ต้นที่เปิดไว้ ให้ทำการ Revise PO เดิมทันทีเพื่อให้ไม่เกิดการคลาดเคลื่อนในจำนวนของที่รับ (PO Receive / IC Receive)"},{"style":"sub","text":"ให้ไปที่ PO Module ➔ เลือกรายการใบสั่งซื้อที่ต้องการเปลี่ยน และกด Revise"},{"style":"sub","text":"เข้าไปที่รายการสินค้าที่ต้องการและกดแก้ไขราคาตามราคาปัจจุบัน ส่งอนุมัติใหม่"},{"style":"sub","text":"เมื่อได้รับการอนุมัติเรียบร้อย จึงค่อยทำการรับของใหม่ในราคาและปริมาณที่ถูกต้อง"},{"style":"num","text":"ในกรณีที่มีการรับของไปแล้ว แต่ยังไม่ได้ทำการจ่ายเงิน ให้ทำการถอยการรับของทันที โดยดำเนินการตามขั้นตอนดังต่อไปนี้"},{"style":"sub","text":"ไปที่ PO Module ➔ รับ/คืนสินค้าตามใบสั่งซื้อ (PO Receive and Return) และคลิกที่แทบคืนสินค้า (Return)"},{"style":"sub","text":"เลือกรายการใบสั่งซื้อที่ต้องการทำการคืน และระบุจำนวนที่มีการรับของในราคาที่ไม่ถูกต้องในช่อง Return QTY"},{"style":"sub","text":"กด Save เพื่อบันทึกการคืนของและดำเนินการต่อตามข้อที่ 1"},{"style":"num","text":"กรณีรับของไปแล้ว และจ่ายเงินเต็มจำนวนแล้ว ต่อมามีการปรับราคา \"เพิ่มขึ้น\" ให้บันทึกการเพิ่มหนี้ (Debit Note) เพื่อทำจ่ายส่วนต่างและปรับปรุงมูลค่าในสต็อก (IC Cost) ให้ถูกต้อง"},{"style":"sub","text":"3.1 [แผนกบัญชี] เข้าไปที่ Module AP ➔ บันทึกรายการ ➔ บันทึกการเพิ่มหนี้ (Debit Note) ➔ ค้นหาและดึงรายการตั้งเจ้าหนี้ (APV) ชุดเดิมที่เคยจ่ายเงินไปแล้วขึ้นมา"},{"style":"sub","text":"3.2 บันทึกระบุยอดเงินส่วนต่างราคาที่เพิ่มขึ้นลงในระบบ (ระบุ Cost Code โครงงานเดิม) เพื่อเพิ่มหนี้ให้ร้านค้า ➔ ส่งต่อให้แผนกการเงินเขียนเช็ค/โอนเงินจ่ายชำระส่วนต่างเพิ่มตามปกติ (วิธีนี้จะปรับปรุงต้นทุนโครงการให้ถูกต้องทางบัญชี โดยไม่รบกวนสต๊อก)"},{"style":"sub","text":"3.3 [แอดมินประจำโครงการ] เข้าไปที่ Module IC ➔ Transaction ➔ Adjust Cost ➔ บันทึกปรับเพิ่มราคาทุนสินค้า (IC Cost UP) เพื่อให้ราคาทุนต่อหน่วยของสินค้าเดิมในคลังมีมูลค่าสูงขึ้นถูกต้องตรงตามยอดใบเพิ่มหนี้จริง"},{"style":"num","text":"กรณีรับของไปแล้ว และจ่ายเงินเต็มจำนวนแล้ว ต่อมามีการปรับราคา \"ลดลง\" ให้ทำใบลดหนี้ (Credit Note) จากยอดเดิม แล้วเลือกดำเนินการตามข้อ 4ก หรือ 4ข ตามที่ตกลงกับร้านค้า"},{"style":"sub","text":"4.1 การจัดทำใบลดหนี้ (ทั้งสองแนวทาง)"},{"style":"sub2","text":"[แผนกบัญชี] เข้าไปที่ Module AP ➔ บันทึกรายการ ➔ บันทึกการลดหนี้ ➔ เลือก ลดหนี้จาก APV"},{"style":"sub2","text":"ค้นหาและดึงรายการตั้งเจ้าหนี้ (APV) ของยอดเดิมที่เคยจ่ายเงินเกินไปขึ้นมา"},{"style":"sub2","text":"ระบุยอดเงินส่วนต่างที่ต้องการปรับลดลง ตรวจสอบความถูกต้องและกด Save (ระบบจะบันทึกสร้างใบลดหนี้ CN เพื่อรอใช้หักล้าง)"},{"style":"sub","text":"4ก. กรณีขอรับเงินคืน (ไม่รับสินค้าเพิ่ม)"},{"style":"sub2","text":"[แผนกจัดซื้อ/การเงิน] ให้ร้านค้าโอนเงินส่วนต่างคืนเข้าบัญชีบริษัท หรือเก็บใบลดหนี้ (CN) ไว้หักกลบกับการสั่งซื้อครั้งถัดไปของร้านค้ารายเดียวกัน"},{"style":"sub2","text":"[แผนกบัญชี] เมื่อได้รับเงินคืนหรือหักกลบแล้ว ให้บันทึกล้างยอดใบลดหนี้ (CN) ในระบบให้ครบถ้วน"},{"style":"sub","text":"4ข. กรณีรับสินค้าเพิ่มแทนการรับเงินคืน"},{"style":"sub2","text":"[แผนกจัดซื้อ] เข้าไปที่ Module PO ➔ จัดทำใบสั่งซื้อ ➔ สำเนาเอกสาร (Copy) จาก PO ใบเดิม ➔ แก้ไขจำนวน (QTY) เป็นปริมาณที่รับเพิ่ม และราคาต่อหน่วย (Unit Price) เป็นราคาใหม่ ➔ ส่งอนุมัติ PO"},{"style":"sub2","text":"[แอดมินประจำโครงการ] เมื่อ PO อนุมัติแล้ว ให้เข้าที่ Module IC เพื่อรับสินค้าเข้าคลังตามปริมาณจริง"},{"style":"sub2","text":"[แผนกบัญชี] ดึงเอกสารรับของจาก PO ใบใหม่มาบันทึกตั้งหนี้ (AP Voucher) ตามปกติ"},{"style":"sub2","text":"[แผนกการเงิน] ในขั้นตอนการจ่ายเงินสำหรับ PO ใบใหม่ ให้ดึงใบลดหนี้ (CN) จากข้อ 4.1 มาหักกลบลบหนี้ (Offset) กับยอดตั้งหนี้ใบใหม่ทันที ➔ ชำระเงินเพิ่มเฉพาะส่วนต่างสุทธิที่เหลือ"},{"style":"sub","text":"4.2 การปรับปรุงต้นทุนคลังสินค้า (ทั้งสองแนวทาง)"},{"style":"sub2","text":"[แอดมินประจำโครงการ] เข้าไปที่ Module IC ➔ Transaction ➔ Adjust Cost ➔ เลือกวัสดุลอตเดิมที่รับไปในราคาแพง ➔ บันทึกปรับลดราคาทุน (IC Cost DOWN) ให้มูลค่าสต๊อกและต้นทุนโครงการตรงตามจริง"}],"extra":["IC","AP","GL","AR"],"attachments":[{"label":"SOP-03 · PO Invoice Price Mismatch","url":"https://drive.google.com/file/d/1ZyacfOPbC4rOoAmx9x2TFsIy7Fyy7o83/view"}]},{"no":3,"module":"PO","display_no":"PO-3","sort_order":3,"title_th":"กรณีเปิด PO ประกอบการทำตั๋วอาวัลกับธนาคาร","title_en":"PO for Bank Aval","problem":"ใช้เมื่อธนาคารกำหนดให้มี PO ประกอบการทำตั๋วสัญญาใช้เงินอาวัล ครอบคลุมการเปิด PO ให้ธนาคาร (ข้อ 1) · การควบคุมการปล่อยตั๋ว (ข้อ 2) · การจัดการส่วนต่างราคา (ข้อ 3)","ref":"ERP Manual 14.3.68 – บทที่ 4 (PO)","note":null,"date_added":"1 เมษายน 2569","steps":[{"style":"num","text":"การควบคุมการเปิดใบสั่งซื้อเพื่อประกอบการทำตั๋วสัญญาใช้เงินอาวัล (Aval Supporting PO)"},{"style":"sub","text":"กรณีเปิด PO คลุมเพื่อส่งทำตั๋วอาวัลเท่านั้น (ยังไม่มีการสั่งของจริงหน้างาน):"},{"style":"sub2","text":"[แผนกจัดซื้อ] บันทึกเปิด PO ในระบบและสั่งพิมพ์ (Print) เอกสารใบสั่งซื้อออกมาเพื่อใช้เซ็นอนุมัตินอกระบบและส่งให้ธนาคารเป็นหลักฐานการทำตั๋วอาวัล (Aval) เท่านั้น"},{"style":"sub2","text":"[แผนกจัดซื้อ] เมื่อส่งเอกสารให้ธนาคารแล้ว ให้ดึง PO ใบนี้ออกจากระบบ (Cancel/Void) ทันที และห้ามส่งให้แผนกบัญชีตั้งหนี้"},{"style":"sub2","text":"[แผนกจัดซื้อ] เมื่อสั่งซื้อและส่งมอบของจริง ให้เปิด PO ใบที่สองตามราคาและปริมาณจริง — ใบที่สองคือ PO ใบจริงที่ใช้ตั้งหนี้ และราคาบนตั๋วอาวัลต้องตรงกับใบนี้"},{"style":"sub","text":"กรณีเปิด PO คลุมเพื่อสั่งซื้อจริง และร้านค้ายินยอม \"ยืนราคา\" (Price Lock) [แผนกบัญชี] ดำเนินการตั้งหนี้ (APV) ตามเงื่อนไขการชำระเงินดังต่อไปนี้:"},{"style":"sub2","text":"กรณีชำระเงินหลังส่งสินค้า (Post-payment): ให้ตั้งหนี้ (APV) อ้างอิงตามยอดในใบรับของ (PO Receive) จริงเท่านั้น"},{"style":"sub2","text":"กรณีชำระเงินก่อนส่งสินค้า (Pre-payment): ให้ตั้งหนี้ (APV) ตามใบแจ้งหนี้ (Invoice) และลงบันทึกบัญชีเป็น \"เงินจ่ายล่วงหน้าค่าสินค้า\" (Down/Advance Payment)"},{"style":"sub","text":"กรณีชำระเงินก่อนส่งสินค้า และร้านค้า \"ไม่ยืนราคา\":"},{"style":"sub2","text":"[แผนกจัดซื้อ] ห้ามเปิด PO คลุม แต่ให้เปิดใบสั่งซื้อ (PO) แยกตามใบขอซื้อ (PR) ทีละฉบับ (เฉพาะการชำระเงินก่อนส่งมอบ)"},{"style":"sub2","text":"[แผนกจัดซื้อ] ต้องกำหนดเงื่อนไขในระบบเป็น เงินดาวน์ 100% เสมอ และพิมพ์ระบุในหมายเหตุ (Comment) บน PO ให้ชัดเจนเพื่อให้แผนกบัญชีทราบว่าต้องตั้งหนี้แบบเต็มจำนวน (Full) หรือบางส่วน (Partial)"},{"style":"num","text":"ขั้นตอนการควบคุมและปล่อยตั๋วอาวัล (Payment Control)"},{"style":"sub","text":"[แผนกการเงิน] ห้ามทำการปล่อยจ่ายตั๋วออกไปให้แก่ร้านค้าเว้นแต่จะได้รับการยืนยันการเปิด PO ใบจริง (ใบที่สอง) หรือ WO ในระบบอย่างครบถ้วน และมีใบสำคัญจ่าย (Payment Voucher - PV) ในระบบเพื่อใช้ตรวจสอบเทียบยอดส่วนต่างของราคาสินค้าจริงกับยอดเงินบนหน้าตั๋วอาวัลเรียบร้อยแล้วเท่านั้น"},{"style":"num","text":"ส่วนต่างระหว่างยอดหน้าตั๋วอาวัลกับ PO ใบจริง"},{"style":"sub","text":"[แผนกจัดซื้อ/การเงิน] ต้องจัดการส่วนต่างให้เสร็จก่อนปล่อยตั๋วตามข้อ 2 วิธีแก้ไขราคาให้ดำเนินการตาม PO-2"},{"style":"sub","text":"กรณีราคาลดลงและจ่ายเงินตามตั๋วไปแล้ว ต้องเรียกเงินส่วนต่างคืนจากร้านค้าก่อนปล่อยตั๋วงวดถัดไป"}],"extra":["AP","GL","AR"],"attachments":[{"label":"SOP-02 · Blanket PO","url":"https://drive.google.com/file/d/1zhRk6JcxxAhFKoKuvylmgK_etJXGKVsr/view"}]},{"no":4,"module":"OF","display_no":"OF-1","sort_order":1,"title_th":"กรณีการเลือกประเภทรายการใน Module OF","title_en":"OF Type Selection","problem":"เดิมบริษัทไม่ได้ใช้ OF อย่างเต็มรูปแบบและทำรายการทุกประเภทที่ไม่ใช่ PO/WO ใน OF หมวด Other ทั้งหมด ทำให้ค่าใช้จ่ายต่าง ๆ ไม่ได้ถูกแยกประเภทตามชนิดเอกสารโดยเฉพาะยอดเงินสดย่อย/เคลียร์เงินสดย่อย และยอดเงินทดลอง/เครดิตเงินทดลอง (Petty Cash / Advance / Other) ทำให้ข้อมูลไม่เอื้อต่อการวิเคราะห์ตามรูปแบบอันควร","ref":"ERP Manual 14.3.68 – บทที่ 3 (OF)","note":"ให้ยึดถือว่าเอกสาร OF ที่ถูกสร้างและผ่านการกดอนุมัติในระบบ ERP เป็นเอกสารอนุมัติทางการเพียงรูปแบบเดียวของบริษัท และให้ใส่ข้อมูลให้ถูกต้องครบถ้วน ห้ามผู้จัดทำใช้ใบปะหน้ากระดาษ / Memo เพื่อเป็นหลักฐานในการทำจ่ายแทนใบ OF ยกเว้นในกรณีฉุกเฉิน","date_added":"1 เมษายน 2569","steps":[{"style":"num","text":"ขั้นตอนการบันทึกใบเบิกเงินในหมวด OF ที่ถูกต้อง ผู้จัดทำเอกสารจะต้องเข้าไปที่โมดูล OF ➔ ดำเนินการ ➔ ใบเบิกเงินสดย่อยและใบเบิกจ่ายที่ไม่มี PO/WO ทำการเลือก \"ประเภทเอกสาร\" (Document Type) ให้ถูกต้องตามลักษณะรายการดังต่อไปนี้:"},{"style":"num","text":"ประเภท Petty Cash (เบิกเงินสดย่อย) ใช้สำหรับ: ค่าใช้จ่ายเงินสดย่อยที่จ่ายไปแล้ว และต้องการตั้งเรื่องเบิกเพื่อชดเชยคืนวงเงินสดย่อย"},{"style":"sub","text":"ที่ช่องประเภทเอกสาร ให้เลือก Petty Cash ระบุชื่อผู้ถือเงินสดย่อยในช่อง \"จ่ายให้กับ\" และเลือก โครงการ ให้ถูกต้อง"},{"style":"sub","text":"เพิ่มรายการค่าใช้จ่าย (Expense Code) และตรวจสอบให้ครบถ้วนก่อนกด Save และส่งอนุมัติ"},{"style":"num","text":"ประเภท Advance (เบิกเงินทดรองจ่าย) ใช้สำหรับ: เงินทดรองจ่ายที่บริษัทจำเป็นต้องสำรองจ่ายเงินก้อนออกไปก่อน และผู้รับเงินจะต้องนำใบเสร็จมาเคลียร์ยอดในภายหลัง"},{"style":"sub","text":"ที่ช่องประเภทเอกสาร ให้เลือก Advance ระบุชื่อพนักงานที่เบิกเงินทดรองในช่อง \"จ่ายให้กับ\""},{"style":"sub","text":"การเลือกประเภท Advance จะทำให้ในอนาคตเมื่อนำใบเสร็จมาเคลียร์ ผู้ใช้งานจะสามารถเลือกประเภทเอกสารเป็น Clear Advance และระบบจะอนุญาตให้ดึงเอกสาร Advance เดิมมาหักล้างยอดและตัด APO ให้อัตโนมัติ"},{"style":"sub","text":"หากคีย์ผิดไปเลือก \"Other\" ระบบจะไม่เปิดให้ดึงยอดมาหักล้าง ทำให้เกิดยอด APO ค้าง จนแผนกบัญชีต้องไปทำเอกสาร PL (สมุดรายวัน) เพื่อล้างยอดเองซึ่งผิดขั้นตอน"},{"style":"num","text":"ประเภท Other (เบิกเงินอื่นๆ) ใช้สำหรับ: ค่าใช้จ่ายอื่น ๆ ที่มีจำนวนเงินที่ต้องจ่ายชัดเจน ไม่ต้องมีการรอเคลียร์ยอดในภายหลัง และไม่มีใบเสร็จประกอบ (เช่น ค่าธรรมเนียม, ค่าปรับ) หรือเป็นรายการที่ต้องการจ่ายเงินตรงให้กับร้านค้า/บุคคลภายนอกโดยไม่มีการทดรองจ่าย"},{"style":"sub","text":"ที่ช่องประเภทเอกสาร ให้เลือก Other ที่ช่องประเภทผู้ขาย ให้เลือกเป็น External และระบุชื่อผู้รับเงินปลายทางให้ชัดเจนและกด Save เพื่อส่งอนุมัติ"},{"style":"sub","text":"\"เงินมัดจำ\" และ \"เงินจ่ายล่วงหน้า / เงินดาว์น / เงินทดรองจ่าย\" มีหลักการปฏิบัติในทางบัญชีและทางระบบแตกต่างกันโดยสิ้นเชิง ขอให้ฝ่ายที่เกี่ยวข้องระบุให้ชัดเจนว่าเป็นประเภทไหน เนื่องจาก OF Advance จะรองรับแค่เงินมัดจำที่ต้องได้คืนเพื่อทำการเคลียร์ยอดในระบบ"}],"extra":["PO","AP"],"attachments":[{"label":"SOP-04 · OF Type Selection","url":"https://drive.google.com/file/d/18jb941tRmGmGKOsxDuoA7eW7S_W0whjT/view"}]},{"no":5,"module":"OF","display_no":"OF-2","sort_order":2,"title_th":"กรณีการตั้งวงเงินสดย่อยเพื่อใช้ในโครงการ","title_en":"Petty Cash/Petty Cash Clearance","problem":"เดิมบริษัทไม่ได้ใช้ OF อย่างเต็มรูปแบบ และทำรายการทุกประเภทที่ไม่ใช่ PO/WO เป็น OF หมวด Other ทั้งหมด ทำให้ค่าใช้จ่ายต่าง ๆ ไม่ได้ถูกแยกประเภทตามชนิดเอกสาร เพื่อปรับปรุงมาตรฐานการบันทึกรายการบัญชีที่ไม่ได้ผ่านระบบ PR/PO ให้เกิดความถูกต้องตามประเภทเอกสารที่แท้จริง แยกหมวดหมู่ยอดเงินสดย่อยและการเคลียร์เงินสดย่อยอย่างเป็นระบบ เพื่อนำข้อมูลไปวิเคราะห์ต้นทุนโครงการ","ref":"ERP Manual 14.3.68 – บทที่ 3 (OF) | บทที่ 6 (AP)","note":null,"date_added":"1 เมษายน 2569","steps":[{"style":"num","text":"การบันทึกและเบิกชดเชยเงินสดย่อย (กรณีค่าใช้จ่ายไม่เกิน 3,000 บาท)"},{"style":"sub","text":"[แอดมินโครงการ / ผู้ถือเงินสดย่อย] ➔ เมื่อมีการจ่ายเงินสดย่อยสำหรับค่าใช้จ่ายทั่วไปในโครงการที่มูลค่าไม่เกิน 3,000 บาท ให้บันทึกคำขอชดเชยในระบบโดยเข้าที่ Module OF ➔ ดำเนินการ ➔ ใบเบิกเงินสดย่อยและใบเบิกจ่ายที่ไม่มี PO/WO"},{"style":"sub","text":"[แอดมินโครงการ / ผู้ถือเงินสดย่อย] ➔ กำหนดข้อมูลในเอกสารให้ถูกต้องดังนี้:"},{"style":"sub2","text":"ประเภทเอกสาร (Document Type): เลือกเป็น Petty Cash (เบิกเงินสดย่อย) เท่านั้น (ห้ามเลือกเป็น Other)"},{"style":"sub2","text":"รายละเอียดผู้ถือเงิน: ระบุชื่อผู้ถือเงินสดย่อย และเลือกรหัสโครงการให้ถูกต้อง"},{"style":"sub2","text":"แท็บรายการใบเบิกเงินสดย่อย: กดเพิ่มรายการ และเลือก \"รหัสค่าใช้จ่าย\" (Expense Code) ให้ตรงกับประเภทของค่าใช้จ่ายจริงแต่ละรายการ เช่น ค่าเดินทาง, ค่าน้ำดื่ม, ค่าวัสดุสิ้นเปลือง"},{"style":"sub","text":"[แอดมินโครงการ / ผู้ถือเงินสดย่อย] ➔ หากรายการใดมีภาษีมูลค่าเพิ่ม (VAT) หรือภาษีหัก ณ ที่จ่าย (WHT) ให้กรอกรายละเอียดใบกำกับภาษี/ใบเสร็จรับเงินให้ครบถ้วน พร้อมทำการ แนบไฟล์สแกนเอกสารหลักฐานการจ่ายเงินสดย่อยทุกฉบับเข้าระบบ ตรวจสอบยอดเงินสุทธิให้ถูกต้องแล้วกด Save และส่งอนุมัติเอกสารตามขั้นตอน"},{"style":"num","text":"การตั้งหนี้และการจัดชุดทำจ่ายเงินสดย่อย (สะสมรวมยอด 3,000 บาทขึ้นไป)"},{"style":"sub","text":"[แผนกบัญชีเจ้าหนี้] ➔ การบันทึกตั้งหนี้เงินสดย่อยในระบบ (APO) ให้เข้าไปที่ Module AP ➔ ดำเนินการ ➔ ตั้งหนี้ ➔ เลือก จากการเบิกอื่นๆ (Create Voucher Other)"},{"style":"sub","text":"[แผนกบัญชีเจ้าหนี้] ➔ ดำเนินการดึงเอกสารใบเบิกเงินสดย่อยที่มีสถานะอนุมัติแล้ว (โดยเลือกดึงเฉพาะ Type: Petty Cash) ขึ้นมาตรวจสอบเอกสารแนบและความถูกต้องของรหัสบัญชี จากนั้นกดบันทึกสร้างใบสำคัญตั้งเจ้าหนี้ (APO)"},{"style":"sub","text":"[แผนกบัญชีเจ้าหนี้ / หัวหน้าแผนกบัญชี] ➔ ในการจัดทำชุดอนุมัติจ่ายเงิน (Pre-payment/APP) ให้เข้าไปที่เมนู อนุมัติจ่าย ➔ อนุมัติจ่าย APO โดยนำรายการตั้งหนี้ (APO) ของผู้ถือเงินสดย่อยรายเดียวกัน มารวบรวมเข้าด้วยกันให้ได้ยอดรวมไม่น้อยกว่า 3,000 บาท ตามนโยบายบริษัท จากนั้นระบุเลือกบัญชีธนาคารที่จะใช้จ่ายเงิน และกดบันทึกเพื่อสร้างชุดอนุมัติจ่าย (APP) จำนวน 1 ชุด"},{"style":"sub","text":"[แผนกการเงิน] ➔ ดำเนินการจ่ายชำระเงินโดยเข้าไปที่เมนู Preparing Cheque, Credit Line ➔ ชำระโดยเช็ค หรือโอนเงิน ดึงชุดอนุมัติจ่าย (APP) ดังกล่าวขึ้นมาทำจ่ายเงินให้ผู้ถือเงินสดย่อย เพื่อให้ระบบออกใบสำคัญจ่าย (Voucher PV) เพียง 1 ฉบับต่อ 1 ธุรกรรมโอนเงิน ช่วยลดความซ้ำซ้อนของเอกสาร"},{"style":"num","text":"การจัดการเงินสดย่อยคงเหลือกรณีย้ายโครงการ (ภายในนิติบุคคลเดียวกัน)"},{"style":"sub","text":"[แผนกบัญชีทั่วไป] ➔ ในกรณีที่นายช่างหรือผู้ถือเงินสดย่อยต้องย้ายไปประจำโครงการใหม่ภายใต้นิติบุคคลเดียวกัน และต้องการโอนยอดเงินสดย่อยคงเหลือไปใช้ต่อที่โครงการใหม่ ให้ใช้วิธีโอนย้ายยอดเงินระหว่างโครงการผ่านสมุดรายวันทั่วไป โดยเข้าที่ Module GL ➔ ดำเนินการ ➔ บันทึกสมุดรายวัน (Journal Voucher) ➔ สร้างใบสำคัญ"},{"style":"sub","text":"[แผนกบัญชีทั่วไป] ➔ ทำการบันทึกรายการปรับปรุงบัญชี (JV) โยกย้ายโครงการโดยระบุรหัสบัญชีเงินสดย่อย (Account Name) และกำหนดโครงการดังนี้:"},{"style":"sub2","text":"ด้านเดบิต (Dr.): เลือกรหัสโครงการใหม่เพื่อรับโอนยอดเงินสดย่อยเข้าคลังโครงการใหม่"},{"style":"sub2","text":"ด้านเครดิต (Cr.): เลือกรหัสโครงการเดิม เพื่อปรับลดยอดเงินสดย่อยออกจากโครงการเก่า"},{"style":"bullet","text":"ช่องหมายเหตุ (Description): พิมพ์ระบุรายละเอียดการโอนให้ชัดเจน เช่น \"โอนยอดเงินสดย่อยคงเหลือของ [ระบุชื่อพนักงาน] จากโครงการ [ระบุโครงการเดิม] ไปยังโครงการ [ระบุโครงการใหม่]\" จากนั้นตรวจสอบความสมดุลของบัญชีและกด Save เพื่อบันทึกรายการ"},{"style":"num","text":"การจัดการเงินสดย่อยคงเหลือกรณีย้ายโครงการ (ต่างนิติบุคคล)"},{"style":"sub","text":"[ผู้ถือเงินสดย่อย / พนักงาน] ➔ เนื่องจากเป็นการย้ายบุคลากรข้ามนิติบุคคลทางกฎหมาย ไม่สามารถโอนทางบัญชีตรงๆ ได้ พนักงานผู้ถือเงินสดย่อย ต้องนำเงินสดคงเหลือทั้งหมดฝากคืนเข้าบัญชีธนาคารของบริษัทเดิมให้เรียบร้อย และนำส่งใบ Pay-in หลักฐานการโอนเงินคืนให้แก่แผนกบัญชีเพื่อออกใบเสร็จรับเงิน (RV) ปิดยอดบัญชี"},{"style":"sub","text":"[แผนกบัญชีลูกหนี้] ➔ เมื่อได้รับใบนำฝากเงิน (Pay-in) จากพนักงานเรียบร้อยแล้ว ให้เข้าไปบันทึกรับเงินในระบบที่ Module AR ➔ ดำเนินการ ➔ บันทึกรับลูกหนี้อื่นๆ แบบไม่ออกใบแจ้งหนี้ (Other Receiving without Invoice)"},{"style":"sub","text":"[แผนกบัญชีลูกหนี้] ➔ บันทึกรายละเอียดการรับเงินคืนในระบบดังนี้:"},{"style":"sub2","text":"ประเภทรายรับ (Option Type): เลือกประเภทรายรับให้ตรงกับการคืนเงินสดย่อย"},{"style":"sub2","text":"Customer (ลูกค้า/ผู้จ่ายเงิน): เลือกรหัสพนักงาน/นายช่างผู้ส่งคืนเงินสดย่อย"},{"style":"sub2","text":"Net Amount (ยอดเงินสุทธิ): ระบุจำนวนเงินสดคงเหลือที่พนักงานโอนคืนมาตามจริง"},{"style":"sub2","text":"Bank A/C (บัญชีธนาคาร): ระบุบัญชีธนาคารของบริษัทที่รับโอนเงินเข้าให้ตรงตามใบ Pay-in"},{"style":"sub2","text":"ตรวจสอบรหัสบัญชีแยกประเภท (GL) ว่าลงบันทึกเครดิตลดบัญชีเงินสดย่อยอย่างถูกต้อง จากนั้นกด Save เพื่อสร้างใบสำคัญรับเงิน (RV) ปิดยอดคงค้างของพนักงานในนิติบุคคลเดิมอย่างสมบูรณ์"}],"extra":["AP","GL"],"attachments":[{"label":"SOP-05 · Petty Cash","url":"https://drive.google.com/file/d/1iAKDEQ1QBuyqYyStRJMEVt7CMRU8xhnm/view"}]},{"no":6,"module":"AP","display_no":"AP-1","sort_order":1,"title_th":"กรณีการโอนเงินภายในระหว่างบัญชีบริษัท/กิจการร่วมค้า","title_en":"Bank Transfer & Intercompany Transfer Policy","problem":"แก้ไขปัญหาตัวเลขวิเคราะห์บิดเบือนในระบบจากการใช้การโอน 5 ขั้นตอนแบบเดิม โดยปรับมาใช้รูปแบบ Check-Transfer 3 ขั้นตอน ในระบบ AP (ไม่มีการทำใบเตรียมจ่าย APP) เพื่อรักษาความถูกต้องของข้อมูลวิเคราะห์ทางการเงินและบัญชี","ref":"ERP Manual 14.3.68 – บทที่ 6 (AP)","note":null,"date_added":"1 เมษายน 2569","steps":[{"style":"num","text":"การโอนเงินภายในนิติบุคคลเดียวกัน (ทำรายการในโปรไฟล์บริษัทเดิม)"},{"style":"sub","text":"[ผู้ขอโอน / แผนกบริหาร] อนุมัติการโอนเงินผ่านเอกสาร Internal Memo"},{"style":"sub","text":"บันทึกโอนเงินใน Module AP เลือกประเภท Check-Transfer 3 ขั้นตอน (ไม่ทำ APP) ➔ บันทึกเลขที่เช็ค (ถ้ามี) ➔ พิมพ์ Voucher PV (ใบปะหน้า) และเสนอผู้จัดการตรวจสอบลงนาม"},{"style":"sub","text":"[ขั้นตอนจัดการหลักฐานการโอน - แยกตามประเภทการโอน]:"},{"style":"sub2","text":"กรณีเช็ค TR: เขียนหรือพิมพ์เช็คสั่งจ่ายจริง ➔ เสนอลงนามและประทับตรา ➔ นำเช็คไปโอนที่ธนาคาร ➔ นำใบเสร็จโอนจริง (Pay-in/Slip) แนบประกบชุด PV กระดาษ"},{"style":"sub2","text":"กรณี Anywhere (ออนไลน์): โอนเงินผ่าน App ธนาคาร ➔ อัปโหลดไฟล์รูปสลิป (Digital Slip) แนบในเอกสาร PV ในระบบโดยตรง (ไม่ต้องพิมพ์สลิปกระดาษ)"},{"style":"sub","text":"ดำเนินการตัดจ่ายหนี้ในระบบผ่านเมนู Clear AP"},{"style":"num","text":"การโอนเงินระหว่างต่างนิติบุคคล (ต้องบันทึกรายการทั้งบริษัทผู้โอน และบริษัทผู้รับโอน)"},{"style":"bullet","text":"[ฝั่งผู้โอน - บริษัท A]:"},{"style":"sub","text":"[ผู้ขอโอน / แผนกบริหาร] อนุมัติผ่านเอกสาร Internal Memo"},{"style":"sub","text":"บันทึกโอนข้ามบริษัทใน Module AP เลือกประเภท Check-Transfer 3 ขั้นตอน (ไม่ทำ APP) ระบุคู่ค้าเป็น บริษัท B ➔ พิมพ์ Voucher PV และลงนามตรวจสอบ"},{"style":"sub","text":"[ขั้นตอนจัดการหลักฐานฝั่งโอน - แยกตามประเภทการโอน]:"},{"style":"sub2","text":"กรณีเช็ค TR: เขียน/พิมพ์เช็คสั่งจ่ายบริษัท B ➔ เสนอลงนาม ➔ นำไปโอนที่ธนาคาร ➔ แนบสลิปโอนเงินจริง (Pay-in) เข้าชุด PV บริษัท A ➔ ทำการ Clear AP"},{"style":"sub2","text":"กรณี Anywhere (ออนไลน์): โอนเงินผ่าน App ธนาคาร ➔ อัปโหลดไฟล์สลิป (Digital Slip) แนบในเอกสาร PV บริษัท A ในระบบ ➔ ทำการ Clear AP"},{"style":"bullet","text":"[ฝั่งผู้รับโอน - บริษัท B]:"},{"style":"sub","text":"ล็อกอินเข้าโปรไฟล์ บริษัท B ➔ บันทึกรับเงินใน Module AR เมนู >บันทึกรับลูกหนี้อื่นๆ แบบไม่ออกใบแจ้งหนี้ (Other Receiving without Invoice) ระบุผู้จ่ายเงินเป็น บริษัท A เพื่อออกใบสำคัญรับ (RV) 5. [ขั้นตอนแนบหลักฐานฝั่งรับ]:"},{"style":"sub2","text":"กรณีเช็ค TR: แนบใบนำฝากธนาคารจริง (Pay-in) เข้ากับชุดเอกสาร RV กระดาษ ของบริษัท B"},{"style":"sub2","text":"กรณี Anywhere (ออนไลน์): อัปโหลดไฟล์สลิปเดียวกัน (Digital Slip) แนบในเอกสาร RV ในระบบของบริษัท B โดยตรง"}],"extra":["AR"],"attachments":[{"label":"SOP-13 · Internal Bank Transfer","url":"https://drive.google.com/file/d/1t24uUn6_Kml0rCQTQpV57vfun7VKDWLq/view"}]},{"no":7,"module":"IC","display_no":"IC-1","sort_order":1,"title_th":"นโยบายการตั้งค่าคลังสินค้าและประเภทการเบิกใช้","title_en":"Warehouse & Area Setup","problem":"เดิมบริษัทยังไม่มีการแบ่งหรือกำหนดวัตถุประสงค์การตั้ง Warehouse อย่างชัดเจน ทำให้ไม่สามารถตรวจสอบตำแหน่งและรายละเอียดวัสดุในคลังได้อย่างแม่นยำ","ref":"ERP Manual 14.3.68 – บทที่ 5 (IC)","note":null,"date_added":"1 เมษายน 2569","steps":[{"style":"num","text":"ปัจจุบันกำหนดให้ 1 โครงการ มีคลังสินค้า (Warehouse) ได้ตามจำนวนคลังสินค้าที่ตั้งอยู่จริงหน้างานเท่านั้น โดยการสร้างคลังสินค้าในแต่ละโครงการ จะต้องเริ่มต้นรหัสคลังสินค้าตำแหน่งแรกเป็นรหัส \"001\" เสมอ และหากมีคลังสินค้าตำแหน่งที่ 2 หรือ 3 เพิ่มเติมในโครงการเดียวกัน ให้รันรหัสต่อเนื่องเป็น \"002\", \"003\" ตามลำดับ"},{"style":"num","text":"การตังค่า \"Type of Area\" เพื่อให้สะดวกต่อการเลือกใช้งานปัจจุบันบริษัทมีกำหนดแค่ฉนิดเดียวเป็น 001 \"เบิกใช้งาน\" เท่านั้น"},{"style":"num","text":"การตั้งค่าข้อมูลประเภทการเบิกและสถานที่ใช้งาน \"Area\" ช่วยให้ฝ่ายสโตร์ทำงานได้ง่ายขึ้น และยังเป็นประโยชน์ต่อฝ่ายบริหารในการเรียกดูรายงาน (Report) ว่ามีการใช้วัสดุไปกับส่วนใด หรือด้วยสาเหตุใดมากที่สุด และปัจจุบันมีการตั้งค่าดังต่อไปนี้"},{"style":"sub","text":"Area Code: 001"},{"style":"sub2","text":"Area Name: ใช้งาน"},{"style":"sub2","text":"Description: ค่าใช้จ่ายหรือรายการที่เกี่ยวข้องกับการดำเนินงานปกติ"},{"style":"sub","text":"Area Code: 002"},{"style":"sub2","text":"Area Name: ทรัพย์สินระหว่างก่อสร้าง"},{"style":"sub2","text":"Description: รายการที่บันทึกเป็นสินทรัพย์ระหว่างการก่อสร้าง"},{"style":"sub","text":"Area Code: 003"},{"style":"sub2","text":"Area Name: เบิกคิดเงิน"},{"style":"sub2","text":"Description: การเบิกที่สามารถเรียกเก็บหรือคิดต้นทุนกลับไปยังโครงการ/ลูกค้า"},{"style":"sub","text":"Area Code: 004"},{"style":"sub2","text":"Area Name: เบิกไม่คิดเงิน"},{"style":"sub2","text":"Description: การเบิกที่ไม่เรียกเก็บหรือไม่คิดต้นทุนกลับ"},{"style":"sub","text":"Area Code: 005"},{"style":"sub2","text":"Area Name: ปรับปรุงยอด"},{"style":"sub2","text":"Description: เพื่อทำการปรับปรุงยอดต่างๆ โดยสำนักงานใหญ่"}],"extra":["SE"],"attachments":[{"label":"SOP-21 · Warehouse Area Setup","url":"https://drive.google.com/file/d/1F9Gq4Vl8gx2idH_jc80kRf53UOaqSV4Q/view"}]},{"no":8,"module":"IC","display_no":"IC-2","sort_order":2,"title_th":"นโยบายการควบคุมหน่วยนับวัสดุและการแปลงหน่วย","title_en":"Unit of Measure & Conversion Control","problem":"เพื่อควบคุมมาตรฐานหน่วยนับของวัสดุ (Unit Code) ให้มีความสอดคล้องกันตลอดทั้งกระบวนการ ตั้งแต่ขั้นตอนการจัดทำงบประมาณ (Budget) การจัดซื้อ (PR/PO) ไปจนถึงการรับของเข้าคลัง (IC Receive) เพื่อป้องกันปัญหาการปัดเศษทศนิยมจากการแปลงหน่วยในระบบ ซึ่งส่งผลกระทบต่อความถูกต้องของยอดสต๊อกคงเหลือ (Stock Balance)","ref":"ERP Manual 14.3.68 – บทที่ 5 (IC)","note":null,"date_added":"1 เมษายน 2569","steps":[{"style":"num","text":"การกำหนดหน่วยนับมาตรฐานจากต้นทาง (Standard Unit Definition)"},{"style":"sub","text":"[แผนกวิศวกรรม / ฝ่ายควบคุมต้นทุน] ➔ ในขั้นตอนการจัดทำและอนุมัติงบประมาณ (Budget) ในระบบ Module BD จะต้องกำหนดหน่วยนับมาตรฐานของวัสดุ (Material Code) แต่ละชนิดให้ชัดเจนตั้งแต่ต้นทาง โดยกำหนดว่าการสั่งของและการรับของเข้าสต๊อกทั้งหมดของบริษัทจะต้องใช้รหัสหน่วยนับใด เพื่อให้เป็นมาตรฐานเดียวกันทุกโครงการและทุกแผนก"},{"style":"num","text":"การตรวจสอบหน่วยนับในกระบวนการขอซื้อและสั่งซื้อ (PR/PO Unit Verification)"},{"style":"sub","text":"[ผู้ขอเบิก / แอดมินประจำโครงการ] ➔ ในการจัดทำใบขอซื้อ (PR) หน้างานจะต้องตรวจสอบและระบุหน่วยนับของวัสดุให้ตรงกับหน่วยการรับสินค้า (PO Receive) และการรับเข้าคลัง (IC Receive) ตามที่ผูกไว้ในฐานข้อมูลระบบ ERP เท่านั้น เพื่อป้องกันปัญหาการแปลงหน่วยย้อนหลังซึ่งอาจทำให้เกิดเศษทศนิยมคลาดเคลื่อนในคลังสินค้า"},{"style":"sub","text":"[ฝ่ายจัดซื้อ] ➔ ก่อนอนุมัติออกใบสั่งซื้อ (PO) ให้ดำเนินการตรวจสอบหน่วยนับของรายการสินค้าอีกครั้ง หากพบว่าร้านค้าเสนอราคาในหน่วยที่แตกต่างจากหน่วยมาตรฐานของบริษัท ฝ่ายจัดซื้อจะต้องคำนวณปริมาณและราคาเพื่อเปิด PO ให้เป็นหน่วยมาตรฐานของบริษัทเสมอ"},{"style":"sub","text":"ตัวอย่างกระบวนการ: หากจัดซื้อต้องการบันทึกข้อมูลอ้างอิงของร้านค้าเพิ่มเติม สามารถพิมพ์ระบุน้ำหนักรวมหรือรายละเอียดหน่วยที่ร้านค้าเสนอมาในช่องหมายเหตุ (Remark) หรือฟังก์ชัน Note แทนได้ เพื่อใช้เป็นหลักฐานอ้างอิงตอนตรวจรับของ"},{"style":"num","text":"มาตรฐานหน่วยนับสำหรับกลุ่มวัสดุหลัก (Standard Material Unit Specifications)"},{"style":"sub","text":"[ฝ่ายจัดซื้อ และ แอดมินประจำโครงการ] ➔ เพื่อความเป็นเอกภาพของระบบข้อมูล ให้ทุกฝ่ายที่เกี่ยวข้องยึดถือมาตรฐานหน่วยนับสำหรับวัสดุหลักของบริษัท ดังต่อไปนี้:"},{"style":"sub","text":"กลุ่มวัสดุเหล็ก: ให้จัดทำเอกสาร PR/PO และทำรับของโดยระบุหน่วยนับเป็น \"เส้น\" เท่านั้น"},{"style":"sub","text":"กลุ่มวัสดุหิน / ดิน / ทราย / ปูน  ให้จัดทำเอกสาร PR/PO โดยระบุหน่วยนับเป็น \"ตัน\" เท่านั้น โดยเมื่อแอดมินโครงการทำรับของเข้าคลัง (IC Receive) ระบบจะทำการแปลงหน่วย (Convert) เป็นหน่วย \"กิโลกรัม\" ให้โดยอัตโนมัติในระบบคลังสินค้า"}],"extra":["PO","PM","BD","SE"],"attachments":[{"label":"SOP-31 · Unit of Measure Control","url":"https://drive.google.com/file/d/1K3lBYbSSSvuoRKcr_kQFvV5tZSg_z4l9/view"}]},{"no":9,"module":"IC","display_no":"IC-3","sort_order":3,"title_th":"กรณีการปรับปรุงยอดสินค้าในคลัง","title_en":"IC Balance Adjustment","problem":"เพื่อกำหนดแนวทางและขั้นตอนที่ถูกต้องในการแก้ไขหรือปรับปรุงยอดการรับสินค้าเข้าคลัง (Inventory Control) ทั้งในกรณีที่เป็นการรับยอดทั่วไป และการรับยอดที่อ้างอิงจากใบสั่งซื้อ (PO) เพื่อป้องกันผลกระทบต่อข้อมูลสต๊อกคงเหลือ และเพื่อให้สามารถปิดเอกสารใบสั่งซื้อในระบบได้อย่างสมบูรณ์ โดยให้พิจารณาตามรูปแบบของเอกสารตั้งต้น ดังนี้","ref":"ERP Manual 14.3.68 – บทที่ 5","note":"ห้ามทำการ \"คืนสินค้า\" (PO Return) หรือยกเลิกเอกสารรับของ (Cancel IC Receive) เด็ดขาด เพราะระบบจะไปสร้างใบลดหนี้ (Credit Note - CN) ในโมดูล AP ซึ่งจะไปกระทบกับระบบบัญชีและการตั้งหนี้ที่ได้ทำการจ่ายเงินเสร็จสิ้นไปแล้ว","date_added":"4 สิงหาคม 2569","steps":[{"style":"num","text":"การรับวัสดุกลับเข้าคลัง (กรณีเบิกของ หรือ โอนของผิดพลาด)"},{"style":"bullet","text":"[แอดมินประจำโครงการ / พัสดุกลาง]"},{"style":"sub","text":"กรณีทำการ \"เบิกของผิด\" (Return From Issue)"},{"style":"sub2","text":"เข้าเมนู Module IC ➔ Transaction ➔ Document IC Receive ➔ เลือกเมนู Stock Receive (รับวัสดุเข้าคลัง)"},{"style":"sub2","text":"ที่ช่อง Type ให้เลือกเป็น \"Return From Issue\""},{"style":"sub2","text":"การดึงข้อมูล: กดค้นหาและเลือกเอกสารใบเบิกของ (IC Issue) ใบเดิมที่เบิกผิดออกไป"},{"style":"sub2","text":"การปรับยอด: ระบุ Document Date ให้เป็นวันที่เดียวกับที่เบิกผิด และใส่เหตุผลในช่อง Remark"},{"style":"sub2","text":"จากนั้นไปที่แท็บ Material Receive แล้วระบุปริมาณที่ต้องการรับกลับเข้าคลังในช่อง QTY (IC)"},{"style":"sub2","text":"ตรวจสอบคลังสินค้า (Warehouse) ให้ถูกต้อง แล้วกด Save"},{"style":"sub","text":"กรณีทำการ \"โอนของผิด\" (Return From Transfer)"},{"style":"sub2","text":"เข้าเมนูเดียวกัน เลือก Stock Receive"},{"style":"sub2","text":"ที่ช่อง Type ให้เลือกเป็น \"Return From Transfer\""},{"style":"sub2","text":"การดึงข้อมูล: กดค้นหาและเลือกเอกสารใบโอนของ (IC Transfer) ใบเดิมที่โอนออกไปผิด"},{"style":"sub2","text":"การปรับยอด: ระบุวันที่และหมายเหตุเช่นเดียวกัน จากนั้นระบุปริมาณในช่อง QTY (IC) และกด Save เพื่อรับของกลับเข้าคลังตั้งต้น"},{"style":"num","text":"การลดยอดสต๊อก หรือ ตัดสินค้าคืนร้านค้า (กรณีรับของจาก PO ผิดพลาด)"},{"style":"bullet","text":"[แอดมินประจำโครงการ / พัสดุกลาง]"},{"style":"sub","text":"หากตรวจรับสินค้าเข้าคลังผ่านใบสั่งซื้อ (PO) ไปแล้ว แต่พบว่าสินค้าไม่ตรงสเปก ชำรุด หรือจำนวนเกิน และต้องการส่งคืนร้านค้าเพื่อลดยอดสต๊อกและยอดตั้งหนี้"},{"style":"sub2","text":"เข้าเมนู Module IC ➔ Transaction ➔ Document IC Receive ➔ เลือกเมนู P/O Receive (รับ/คืนสินค้า)"},{"style":"sub2","text":"ค้นหาใบ PO ที่ต้องการคืนสินค้า แล้วเลือกรายการวัสดุที่ต้องการรับคืน"},{"style":"sub2","text":"การปรับยอด: ใส่หมายเหตุในช่อง \"ส่งคืนหมายเหตุ\" จากนั้นไปที่แท็บ รายการสินค้า และระบุจำนวนที่ต้องการลดยอดส่งคืนลงในช่อง Return QTY (หรือกดรับคืนทั้งหมด) แล้วกด Save ระบบจะสร้างใบคืนสินค้าและลดยอดสต๊อกให้ทันที"},{"style":"num","text":"การปรับลดยอดสต๊อกทั่วไป หรือ การย้ายคลังสินค้า"},{"style":"bullet","text":"[แผนกพัสดุกลาง]"},{"style":"sub","text":"กรณีต้องการตัดของทิ้ง / ลดยอดทั่วไป (Stock Issue)"},{"style":"sub2","text":"เข้าเมนู Module IC ➔ Transaction ➔ Document IC Issue ➔ Entry Document"},{"style":"sub2","text":"เลือกประเภทเอกสารเป็น \"Issue\" ระบุรายละเอียด และเลือก Material ที่ต้องการลดยอด พร้อมใส่ปริมาณลงในช่อง QTY"},{"style":"sub2","text":"ระบุ Area Code เป็น 0005 \"ปรับปรุงยอด\"  และระบุหมายเหตุ (Remark) เช่น \"ปรับปรุงลดยอดสต๊อกเนื่องจาก คีย์ข้อมูลผิดพลาด\""},{"style":"sub2","text":"เลือก Material รหัสที่รับเข้ามาผิด และระบุปริมาณ (QTY) ที่ต้องการลดยอดออก"},{"style":"sub2","text":"เมื่อสร้างใบเตรียมเบิกเสร็จสิ้น ให้ไปที่เมนู Stock Issue (เอกสารเบิกวัสดุ) ดึงเอกสารใบเตรียมเบิกดังกล่าวมากด Save เพื่อตัดยอดวัสดุที่ผิดออกจากคลังอย่างสมบูรณ์"},{"style":"sub","text":"กรณีที่ต้องการบันทึกรหัสสินค้าใหม่ที่ถูกต้องเข้าไปในคลังเพื่อทดแทนรหัสเดิม"},{"style":"sub2","text":"เข้าไปที่ Module IC ➔ Transaction ➔ Document IC Receive ➔ Stock Receive (รับวัสดุเข้าคลัง)"},{"style":"sub2","text":"เลือกช่อง Type เป็น Other และ ระบุในช่องหมายเหตุ (Remark) ว่า \"รับเข้าเพื่อปรับปรุงยอดจากการคีย์ข้อมูลผิดพลาด\""},{"style":"sub2","text":"ไปที่แท็บ Material Receive กดแก้ไขแล้วระบุคลังสินค้า (Warehouse) พร้อมด้วยรหัสวัสดุและปริมาณที่ถูกต้อง (ไม่ต้องกรอก QTY PO / Amount PO)"},{"style":"sub2","text":"ตรวจสอบความถูกต้องแล้วกด Save"},{"style":"sub","text":"กรณีต้องการสลับคลัง หรือ โอนย้ายข้ามโครงการ (Stock Transfer)"},{"style":"sub2","text":"ขั้นตอนเตรียมโอน: เข้าเมนูเดียวกับด้านบน แต่เลือกประเภทเอกสารเป็น \"Transfer\""},{"style":"sub2","text":"การตั้งค่า: ระบุโครงการปลายทางในช่อง To Project จากนั้นเลือก Material และใส่ปริมาณ (QTY) ที่ต้องการย้าย"},{"style":"sub2","text":"ขั้นตอนตัดและรับโอน: โครงการต้นทางดึงเอกสารไปทำ Transfer (เอกสารโอนวัสดุ) เพื่อตัดยอดออก และโครงการปลายทางต้องไปทำ Receive (เอกสารรับโอนวัสดุ) เพื่อรับยอดเข้าคลังใหม่"},{"style":"num","text":"การปรับปรุง \"ต้นทุน\" ของวัสดุในคลัง (โดยไม่กระทบปริมาณ)"},{"style":"bullet","text":"[แผนกพัสดุกลาง]"},{"style":"sub","text":"หากจำนวน QTY ของวัสดุในคลังถูกต้องแล้ว แต่มีค่าใช้จ่ายเพิ่มเติม (เช่น ค่าขนส่งนำเข้า หรือค่าใช้จ่ายจากเงินสดย่อย) ที่ต้องการนำมาบวกเฉลี่ยเพิ่มเป็น \"ต้นทุนต่อหน่วย\" ของสินค้านั้นๆ"},{"style":"sub2","text":"ขั้นตอน: เข้าเมนู Module IC ➔ Transaction ➔ Enter Cost Material Other"},{"style":"sub2","text":"การตั้งค่า: เลือก Average by Amount เพื่อให้ระบบถัวเฉลี่ยต้นทุน"},{"style":"sub2","text":"การดึงข้อมูล: ดึงเอกสารใบตั้งหนี้ค่าใช้จ่าย (APO) ที่ต้องการนำมาเป็นต้นทุน ตรวจสอบรายการในแท็บ Material Cost Other แล้วกด Save ต้นทุนดังกล่าวจะถูกปันส่วนเข้ามูลค่าสินค้าในคลังโดยอัตโนมัติ"}],"extra":["PO"],"attachments":[{"label":"SOP-09 · IC Balance Adjustment","url":"https://drive.google.com/file/d/1b9KWZ1u63ioFcJf-wQxMM_kCX9jXqZAe/view"}]},{"no":10,"module":"OF","display_no":"OF-3","sort_order":3,"title_th":"กรณีการเปลี่ยนรูปแบบคำขอเบิกเงิน/ขออนุมัติค่าใช้จ่าย","title_en":"Payment/Expense Request Revision","problem":"เพื่อป้องกันความซ้ำซ้อนในการเบิกจ่ายและการจองงบประมาณซ้ำซ้อน (Double Budgeting) ในระบบ ERP ในทุกกรณีที่มีการเปลี่ยนรูปแบบคำขอจัดซื้อจัดจ้างหรือการเบิกจ่ายเงินสด (เช่น การเปลี่ยนจาก PR เป็นเงินสดย่อย หรือสลับระหว่างเงินสดย่อย เงินทดรองจ่าย และใบเบิกเงินอื่นๆ)","ref":"ERP Manual 14.3.68 – บทที่ 3 (OF)","note":"ห้ามดำเนินการเบิกเงินผ่านหมวดอื่นๆก่อนที่ขั้นตอนการลดยอดในหมวดเดินจะเสร็จสิ้นสมบูรณ์ เพื่อป้องกันการเบิกจ่ายซ้ำซ้อน","date_added":"1 เมษายน 2569","steps":[{"style":"num","text":"การยกเลิกเอกสารคำขอเดิมก่อนการเปลี่ยนรูปแบบ (Cancellation of the Prior Request)"},{"style":"bullet","text":"ข้อกำหนดทั่วไป: ไม่ว่าจะเป็นการเปลี่ยนรูปแบบจากช่องทางใดก็ตาม ห้าม ดำเนินการเปิดเอกสารคำขอใหม่ในระบบหากยังไม่ได้ทำการยกเลิกหรือลดยอดเอกสารคำขอเดิมที่ค้างอยู่ในระบบให้เรียบร้อยก่อน โดยแบ่งเป็นกรณีดังนี้:"},{"style":"sub","text":"กรณีที่ 1.1: เปลี่ยนรูปแบบจาก \"ใบขอซื้อ (PR)\" ➔ \"ใบเบิกเงินสด (OF)\" [ผู้ขอเบิก / แอดมินประจำโครงการ]"},{"style":"sub2","text":"เข้าสู่ระบบงานสำนักงาน Module OF ➔ ดำเนินการ ➔ บันทึกใบขอซื้อ ➔ เลือกเมนู \"ลดยอดรายการขอซื้อ\""},{"style":"sub2","text":"ค้นหาเอกสารใบขอซื้อ (PR) ใบเดิม และเลือกรายการวัสดุที่ต้องการยกเลิก"},{"style":"sub2","text":"ในช่อง QTY Decrement ให้ระบุจำนวนที่ต้องการยกเลิก และระบุสาเหตุในช่องหมายเหตุ เช่น \"ร้านค้าไม่เสนอราคา ขอเปลี่ยนรูปแบบไปเบิกเงินทดรองจ่ายแทน\""},{"style":"sub2","text":"ตรวจสอบข้อมูลและกดปุ่ม Save เพื่อคืนงบประมาณ (Budget) กลับเข้าโครงการ"},{"style":"sub","text":"กรณีที่ 1.2: เปลี่ยนรูปแบบระหว่างเอกสารเบิกเงินสดด้วยกัน \"OF\" ➔ \"OF\" เช่น เงินสดย่อย (Petty Cash) ➔ เงินทดรองจ่าย (Advance) หรือ ใบเบิกเงินอื่นๆ (Other) [ผู้ขอเบิก / แอดมินประจำโครงการ]"},{"style":"sub2","text":"เข้าไปที่เมนูบันทึกรายการของเอกสารเดิมที่เคยสร้างไว้ (เช่น หากเดิมทำเป็นใบเบิกเงินสดย่อย ให้เข้าเมนูบันทึกเงินสดย่อย)"},{"style":"sub2","text":"ค้นหาเลขที่เอกสารใบเดิมที่มีความประสงค์จะยกเลิก"},{"style":"sub2","text":"ดำเนินการกดปุ่ม \"ยกเลิกเอกสาร (Cancel / Void)\" ในระบบเพื่อปลดล็อกยอดเงินงบประมาณที่ถูกจองไว้ให้กลับคืนสู่โครงการ"},{"style":"num","text":"การตั้งคำขอเบิกเงินในรูปแบบใหม่ทดแทน (Creation of the New Request) [ผู้ขอเบิก / แอดมินประจำโครงการ]"},{"style":"sub","text":"เข้าสู่ระบบงานสำนักงาน Module OF ➔ ดำเนินการ ➔ เลือกเมนู \"ใบเบิกเงินสดย่อยและใบเบิกจ่ายที่ไม่มี PO/WO\""},{"style":"sub","text":"เลือกประเภทเอกสารในรูปแบบใหม่ที่ต้องการสลับใช้อย่างเหมาะสม:"},{"style":"bullet","text":"Petty Cash (เงินสดย่อย): สำหรับการจ่ายเงินสดมูลค่าไม่สูงหน้างาน"},{"style":"bullet","text":"Advance (เบิกเงินทดรองจ่าย): สำหรับกรณีขอเบิกเงินก้อนล่วงหน้าไปสำรองจ่ายให้ร้านค้าก่อน"},{"style":"bullet","text":"Other (เบิกเงินอื่นๆ): สำหรับกรณีที่ต้องการให้ฝ่ายการเงินสำนักงานใหญ่โอนเงินชำระตรงให้ร้านค้าภายนอก"},{"style":"sub","text":"ระบุโครงการ รหัสแผนก และผู้ขอเบิกให้ถูกต้อง"},{"style":"sub","text":"ในช่องรายละเอียดหรือคำอธิบายเหตุผลของการเบิกใบใหม่ ต้องระบุข้อความเชื่อมโยงถึงเอกสารเดิมที่ยกเลิกไปเสมอ เพื่อความโปร่งใสและเป็นหลักฐานอ้างอิงในการตรวจสอบย้อนหลัง เช่น \"เบิกเพื่อซื้อวัสดุทดแทน [ระบุประเภทเดิม เช่น PR หรือ เงินสดย่อย] เลขที่ [ระบุเลขเอกสารเดิม] ที่ได้ทำการยกเลิกในระบบแล้ว\""},{"style":"sub","text":"บันทึกระบุรหัสต้นทุน (Cost Code) และยอดเงินให้เรียบร้อย ตรวจสอบความถูกต้องและกดปุ่ม Save เพื่อส่งอนุมัติ"}],"extra":["PO"],"attachments":[{"label":"SOP-30 · Payment Expense Request Revision","url":"https://drive.google.com/file/d/1FVMCh9xMM_8G6DSBYH1QDw0RRs7pz94t/view"}]},{"no":11,"module":"FA","display_no":"FA-1","sort_order":1,"title_th":"นโยบายการออกรหัสทรัพย์สินในระบบ","title_en":"Fixed Asset Registration Policy","problem":"ปัจจุบันเมื่อหน่วยงานหรือโครงการรับทรัพย์สินใหม่เข้ามา ยังไม่มีขั้นตอนและผู้รับผิดชอบที่ชัดเจนในการขอรหัสและบันทึกทรัพย์สินเข้าระบบ ERP ส่งผลให้ทรัพย์สินบางรายการไม่ถูกบันทึกหรือบันทึกล่าช้า ข้อมูลไม่ครบหรือไม่ตรงกับบัญชี การคำนวณค่าเสื่อมราคาคลาดเคลื่อน และไม่สามารถติดตามได้ว่าทรัพย์สินอยู่ที่ใดหรือใครเป็นผู้ถือครอง จึงจำเป็นต้องกำหนด SOP ฉบับนี้ เพื่อให้การขึ้นทะเบียนทรัพย์สินใหม่มีมาตรฐานเดียวกัน มีผู้รับผิดชอบชัดเจน ข้อมูลในระบบถูกต้องครบถ้วน และตรวจสอบย้อนกลับได้","ref":"ERP Manual 14.3.68 – บทที่ 9","note":null,"date_added":"24 กันยายน 2569","steps":[{"style":"num","text":"เงื่อนไขและเอกสารประกอบการขอรหัสทรัพย์สิน"},{"style":"sub","text":"เมื่อหน่วยงาน/โครงการเซ็นรับสินค้า และตรวจสอบแล้วว่ารายการดังกล่าวเข้าเงื่อนไข \"ทรัพย์สินถาวร\" (มีอายุการใช้งานมากกว่า 1 ปีขึ้นไป) ให้จัดเตรียมชุดเอกสารหลักฐานแนบส่งขอรหัสทรัพย์สิน ดังนี้:"},{"style":"sub2","text":"ใบสั่งซื้อ / สัญญาซื้อขาย (PO / Contract)"},{"style":"sub2","text":"ใบส่งของ / ใบกำกับภาษี / ใบเสร็จรับเงิน"},{"style":"sub2","text":"รูปถ่ายสภาพทรัพย์สินจริง"},{"style":"num","text":"การแบ่งหน้าที่การสร้างรหัสและการบันทึกในระบบ"},{"style":"sub","text":"2.1 หมวดเครื่องจักรและยานพาหนะ (Machinery & Vehicles)"},{"style":"sub2","text":"หน่วยงานรับผิดชอบ: ศูนย์ซ่อมพุทธมณฑลสาย 5"},{"style":"sub2","text":"หน้าที่: ตรวจสอบเอกสาร สร้างรหัสทรัพย์สิน (Asset Code) และบันทึกข้อมูลเข้าสู่ระบบ Module FA"},{"style":"sub","text":"2.2 หมวดทรัพย์สินทั่วไปและอุปกรณ์สำนักงาน (Other Assets)"},{"style":"sub2","text":"หน่วยงานรับผิดชอบ: แผนกพัสดุและทรัพย์สิน สำนักงานใหญ่"},{"style":"sub2","text":"หน้าที่: ตรวจสอบเอกสาร สร้างรหัสทรัพย์สิน (Asset Code) และบันทึกข้อมูลเข้าสู่ระบบ Module FA"},{"style":"num","text":"รายละเอียดการบันทึกข้อมูลในระบบ FA"},{"style":"sub","text":"การบันทึกข้อมูลเข้าสู่ระบบ Module FA ต้องประสานงานร่วมกับแผนกบัญชี เพื่อกำหนดมูลค่าและจัดประเภททรัพย์สิน (Asset Type) ให้ถูกต้องตรงกัน โดยต้องระบุรายละเอียดภาคบังคับให้ครบถ้วน ดังนี้:"},{"style":"sub2","text":"ชื่อรายการ และ Serial Number: ระบุยี่ห้อ รุ่น และหมายเลขประจำตัวเครื่อง (ถ้ามี)"},{"style":"sub2","text":"ประเภททรัพย์สิน (Asset Type): เลือกหมวดหมู่การตัดค่าเสื่อมราคาตามที่ประสานกับบัญชี"},{"style":"sub2","text":"วันที่เริ่มใช้งาน / วันที่รับเข้า (Start Date / Received Date): ระบุวันที่รับมอบจริงเพื่อเริ่มคำนวณค่าเสื่อมราคา"},{"style":"sub2","text":"สถานที่จัดตั้งและผู้รับผิดชอบ (Project / Location / Cost Center / Employee): ระบุโครงการและผู้ถือครองให้ตรงตามจริง"},{"style":"sub2","text":"ราคาทุน (Cost): ระบุมูลค่าต้นทุนทรัพย์สินตามใบกำกับภาษี/ใบเสร็จรับเงิน"},{"style":"sub2","text":"การติดป้ายรหัสทรัพย์สิน (Asset Tagging): เมื่อบันทึกในระบบเรียบร้อย ให้ทำการพิมพ์สติ๊กเกอร์รหัสทรัพย์สิน (Asset Tag) ส่งไปติดบนตัวทรัพย์สินจริง ณ หน้างาน"}],"extra":["SE"],"attachments":[]},{"no":12,"module":"PM","display_no":"PM-1","sort_order":1,"title_th":"กรณีการบันทึกและประมาณการรายรับ-รายจ่ายอื่น","title_en":"Plan Forecast Income","problem":"เพื่อกำหนดขั้นตอนการบันทึกวางแผนและประมาณการกระแสเงินสดรับ-จ่ายอื่น ๆ (เช่น ตั๋วสัญญาใช้เงิน, เงินกู้, ดอกเบี้ย) ผ่านฟังก์ชัน Plan Forecast Other ซึ่งเป็นโมดูลใหม่ที่พัฒนาขึ้นบนระบบ On-Web เพื่อให้การคาดการณ์สภาพคล่องทางการเงินของโครงการและแผนกมีความถูกต้อง","ref":"ERP Manual 14.3.68 – บทที่ 8 (PM)","note":null,"date_added":"1 เมษายน 2569","steps":[{"style":"num","text":"ข้อกำหนดและนโยบายการควบคุม:"},{"style":"sub","text":"การปิดรายการเมื่อเกิดขึ้นจริง (Closing Rule): เมื่อรายการรับหรือจ่ายเงินตามที่ประมาณการไว้ \"เกิดขึ้นจริงแล้ว\" ผู้บันทึกจะต้องเข้าไปเปลี่ยนสถานะเอกสารเป็น \"Close\" เสมอ เพื่อป้องกันไม่ให้ระบบยกยอดประมาณการดังกล่าวไปคำนวณซ้ำในเดือนถัดไป"},{"style":"sub","text":"การควบคุมความคลาดเคลื่อน (Variance Control): ผู้บันทึกต้องกลับไปตรวจสอบความถูกต้องของรายการทุกครั้ง หากพบว่ามูลค่าที่เกิดขึ้นจริง มีความคลาดเคลื่อนจากยอดประมาณการ เกินกว่า 10% (ไม่ว่าจะสูงกว่าหรือต่ำกว่า) จะต้องแจ้งให้โครงการหรือแผนกที่เกี่ยวข้องทราบทันทีเพื่อปรับแผนดำเนินงาน"},{"style":"num","text":"ขั้นตอนการปฏิบัติงานในระบบ Mango ERP (System Workflow)"},{"style":"sub","text":"ขั้นตอนที่ 1: การบันทึกสร้างประมาณการ (Create Plan Forecast Other)"},{"style":"bullet","text":"[ผู้บันทึกประมาณการ / ฝ่ายการเงินหรือบัญชี]"},{"style":"sub","text":"เข้าสู่โมดูล PM ➔ เมนู Project Forecast ➔ เลือก Plan Forecast Other"},{"style":"bullet","text":"ระบุข้อมูลรายละเอียดของรายการให้ครบถ้วน ดังนี้:"},{"style":"sub2","text":"Document Type: ระบุประเภทรายการให้ชัดเจนว่าเป็น Income (รายรับ) หรือ Expense (รายจ่าย)"},{"style":"sub2","text":"Option: ระบุประเภทของค่าใช้จ่ายหรือรายได้ให้ตรงตามวัตถุประสงค์ เช่น Promissory Note (ตั๋วสัญญาใช้เงิน), Loan (เงินกู้ยืม), Interest (ดอกเบี้ย) หรืออื่น ๆ"},{"style":"sub2","text":"Bank: ระบุว่ารายการรับ-จ่ายนี้ จะทำธุรกรรมผ่านเข้า/ออกบัญชีธนาคารใด"},{"style":"sub2","text":"Project / Department: ระบุว่ารายการนี้เป็นการทำรายการเข้าโครงการใด หรือรับผิดชอบโดยแผนกใด"},{"style":"sub2","text":"ตรวจสอบข้อมูล ยอดเงินประมาณการ และกดบันทึกข้อมูลในระบบ"},{"style":"sub","text":"ขั้นตอนที่ 2: การติดตามและอัปเดตสถานะ (Follow-up & Close Status)"},{"style":"bullet","text":"[ผู้บันทึกประมาณการ]"},{"style":"sub","text":"การปิดรายการ (Close): เมื่อได้รับเงินหรือจ่ายเงินจริงเรียบร้อยแล้ว ให้ผู้บันทึกกลับเข้ามาที่รายการเดิม แล้วทำการเปลี่ยนสถานะรายการเป็น \"Close\" ทันที"},{"style":"sub","text":"การแจ้งเตือนความคลาดเคลื่อน (Variance Alert): ตรวจสอบยอดเงินที่เกิดขึ้นจริงเทียบกับที่ประมาณการไว้ หากคำนวณแล้วพบว่าคลาดเคลื่อนเกิน 10% ให้ดำเนินการทำสรุปแจ้งโครงการหรือผู้เกี่ยวข้องรับทราบเพื่อหาแนวทางบริหารจัดการต่อไป"}],"extra":[],"attachments":[{"label":"SOP-11 · Plan Forecast Other","url":"https://drive.google.com/file/d/1aezTmVTfOnVwEb9G0B5US2WBrtfQS_EF/view"}]},{"no":13,"module":"FA","display_no":"FA-2","sort_order":2,"title_th":"กรณีการโอนย้ายทรัพย์สินระหว่างโครงการ/กิจการร่มค้า","title_en":"Fixed Asset Transfer","problem":"ปัจจุบันการโอนย้ายทรัพย์สินระหว่างโครงการหรือหน่วยงาน ยังไม่มีขั้นตอนการขออนุมัติ เอกสารประกอบ และผู้รับผิดชอบการบันทึกในระบบที่ชัดเจน ทำให้ทรัพย์สินถูกเคลื่อนย้ายจริงโดยไม่ได้บันทึกโอนย้ายใน Module FA หรือบันทึกล่าช้า ข้อมูล Project / Location และผู้ถือครองในระบบไม่ตรงกับสภาพจริง ต้นทุนและค่าเสื่อมราคาถูกรับรู้ผิดโครงการ และไม่สามารถติดตามหรือตรวจนับทรัพย์สินได้อย่างถูกต้อง จึงจำเป็นต้องกำหนดขั้นตอนนี้ เพื่อให้การโอนย้ายทรัพย์สินทุกครั้งผ่านการอนุมัติ มีเอกสารกำกับ บันทึกในระบบครบถ้วน และข้อมูลในระบบสอดคล้องกับทรัพย์สินจริง","ref":"ERP Manual 14.3.68 – บทที่ 9 (FA)","note":"กรณีซ่อมเปลี่ยน Status เป็น Repair / กรณียืมระหว่างหน่วยงาน ถ้าระยะเวลามากกว่า 1 เดือน จะต้องโอนย้าย Project และเปลี่ยน Location","date_added":"1 เมษายน 2569","steps":[{"style":"num","text":"การแบ่งประเภททรัพย์สินและผู้รับผิดชอบการทำรายการในระบบ"},{"style":"sub","text":"หมวดที่ 1: เครื่องจักรใหญ่และยานพาหนะ (เช่น รถยนต์, รถขุด, เครื่องจักรกลหนัก)"},{"style":"sub2","text":"ให้หน่วยงานแจ้งความประสงค์โอนย้ายมาที่ศูนย์ซ่อมสาย 5 และ ศูนย์ซ่อมสาย 5 เป็นผู้ดำเนินการบันทึกโอนย้ายในระบบ"},{"style":"sub","text":"หมวดที่ 2: ทรัพย์สินทั่วไปและอุปกรณ์สำนักงาน (เช่น โต๊ะ, เก้าอี้, คอมพิวเตอร์, เครื่องใช้สำนักงาน)"},{"style":"sub2","text":"ให้หน่วยงานแจ้งความประสงค์โอนย้ายมาที่แผนกพัสดุทรัพย์สิน (สนญ.) และแผนกพัสดุทรัพย์สิน (สนญ.) เป็นผู้ดำเนินการบันทึกโอนย้ายในระบบ"},{"style":"num","text":"ขั้นตอนการปฏิบัติงาน (Workflow)"},{"style":"sub","text":"ขั้นตอนที่ 1: การแจ้งเรื่องและขออนุมัติ (Request & Approval)"},{"style":"sub2","text":"หน่วยงานที่ต้องการโอนย้าย จัดทำเอกสารขออนุมัติโอนย้าย พร้อมแนบใบประเมินสภาพ/รายละเอียดทรัพย์สิน"},{"style":"sub2","text":"การส่งเรื่อง: หากเป็น เครื่องจักรใหญ่ / รถ ➔ ส่งเรื่องแจ้งมายัง ศูนย์ซ่อมสาย 5"},{"style":"sub2","text":"การส่งเรื่อง: หากเป็น ทรัพย์สินทั่วไป / สำนักงาน ➔ ส่งเรื่องแจ้งมายัง พัสดุทรัพย์สิน สำนักงานใหญ่"},{"style":"sub","text":"ขั้นตอนที่ 2: การบันทึกโอนย้ายในระบบ ERP (System Execution)"},{"style":"sub2","text":"เมื่อได้รับการอนุมัติ เจ้าหน้าที่ผู้ดูแลตามหมวด เข้าสู่ระบบ Module FA ➔ โอนย้ายทรัพย์สิน และดำเนินการ ดังนี้"},{"style":"sub2","text":"ระบุวันที่, ประเภทการโอน และเลือก โครงการ/แผนกปลายทาง (To Project)"},{"style":"sub2","text":"ดึงรายการทรัพย์สิน ระบุ รหัสผู้ถือครองใหม่ (Employee Code) และ ตำแหน่งที่ตั้งใหม่ (Location)"},{"style":"sub2","text":"กรอกข้อมูลการขนส่ง (ชื่อคนขับ, ทะเบียนรถ, ผู้จัดส่ง) แล้วบันทึก (Save)"},{"style":"sub2","text":"พิมพ์เอกสาร \"ใบโอนย้ายทรัพย์สิน\" จากระบบ เพื่อใช้กำกับไปพร้อมกับการขนย้าย"},{"style":"sub2","text":"ในกรณีเป็นการโอนให้แก่กิจการร่วมค้า ให้เลือก To Project: สำนักงานใหญ่ และระบุแค่ในส่วนของ Location เท่านั้น"},{"style":"sub","text":"ขั้นตอนที่ 3: การขนส่งและการตรวจรับจริง (Transport & Physical Receipt)"},{"style":"sub2","text":"การขนย้าย: จัดส่งทรัพย์สินจริงโดยแนบ \"ใบโอนย้ายทรัพย์สิน\" ฉบับจริงไปด้วย"},{"style":"sub2","text":"การตรวจรับ: เมื่อถึงปลายทาง ผู้รับตรวจเช็กสภาพ ลงนามรับมอบในเอกสาร และเจ้าหน้าที่เข้าโมดูล FA ➔ ตรวจสอบทรัพย์สินโอนย้าย เพื่อยืนยันการรับเข้าและอัปเดตสถานะในระบบให้ตรงตามจริง"},{"style":"num","text":"หลักเกณฑ์การระบุตำแหน่งที่ตั้ง (Location Guidelines)"},{"style":"sub","text":"ต้องระบุสถานที่ตั้งจริงเสมอ: กำหนด Location ให้ตรงกับจุดที่ทรัพย์สินตั้งอยู่จริง ณ ขณะนั้น"},{"style":"sub","text":"กรณีจำเป็นต้องโอนต้นทุนแต่ยังไม่ได้ย้ายตัวจริง: (เช่น โครงการเดิมปิด) ให้ทำเอกสารโอนย้ายระบุ โครงการปลายทาง (To Project) เป็นโครงการใหม่เพื่อตัดรับรู้ต้นทุนทางบัญชี แต่ในช่อง Location ต้องระบุสถานที่ที่ทรัพย์สินวางอยู่จริง ณ ปัจจุบันให้ชัดเจน เพื่อให้การตรวจสอบทางกายภาพถูกต้อง"},{"style":"sub","text":"ในกรณีที่ยังไม่มีผู้ใดใช้เครื่องจักรรายการนี้ต่อ ให้โอนมาพักที่ Project: สำนักงานใหญ่ และ Location ศูนย์ซ่อมสาย 5 / องครักษ์ หรืออื่นๆ ตามที่ตั้งจริง"},{"style":"num","text":"การขอ \"ตัดจ่าย FA\" (Fixed Assets หรือสินทรัพย์ถาวร) เป็นขั้นตอนทางบัญชีในการจำหน่ายหรือตัดจำหน่ายสินทรัพย์ออกจากบัญชี เนื่องจากหมดอายุการใช้งาน ชำรุดเสียหาย ขายออก หรือสูญหาย แต่ต้องมีเรื่องผ่านการอนุมัติจากผู้จัดการฝ่ายพัสดุและทรัพย์สิน"},{"style":"sub","text":"กรณีขายสินทรัพย์ถาวร"},{"style":"sub2","text":"ต้องมีเอกสารที่ระบุรหัสทรัพย์สิน, ระบุผู้ซื้อ, ระบุราคาที่ขาย, วัน/เดือน/ปีที่ขายและขอตัดบัญชี ลงนามโดยผู้มีอำนาจ"},{"style":"sub","text":"กรณีสินทรัพย์ชำรุดเสื่อมสภาพ, สูญหาย, บริจาค หรือเลิกใช้งาน (Write-off)"},{"style":"sub2","text":"เอกสารอนุมัติตัดจ่ายสินทรัพย์ (Asset Disposal Form) ที่ลงนามโดยผู้มีอำนาจ ต้องระบุรหัสทรัพย์สิน, ระบุสาเหตุ, วัน/เดือน/ปีที่ขอตัดบัญชี พร้อมรูปภาพ"},{"style":"sub2","text":"กรณีชำรุด: มีรายงานการตรวจนับหรือใบรับรองสภาพชำรุดพร้อมภาพถ่าย ประกอบการลงบัญชี (ตอน Write-off ไม่ต้องนำส่งภาษีขาย แต่ตอนขายซากต้องนำส่งภาษีขาย)"},{"style":"sub2","text":"กรณีสูญหาย: มีรายงานการตรวจนับ, มีภาพถ่าย, รายงานการสอบสวนหรือใบแจ้งความ (ประกอบการบันทึกบัญชี กรมสรรพากร (นำส่งภาษีขาย))"},{"style":"sub2","text":"กรณีบริจาคให้หน่วยงานราชการ: ต้องมีใบอนุมัติบริจาคจากผู้มีอำนาจภายในบริษัท ต้องขอหนังสือส่งมอบ/ตอบรับการบริจาค หรือใบเสร็จรับเงิน/ใบรับบริจาค จากหน่วยงานราชการที่ระบุชื่อผู้บริจาคและรายละเอียดสินทรัพย์ชัดเจน - ไม่ต้องส่งภาษีขาย (เอกสารตอบขอบคุณไม่สมบูรณ์ ถือว่าขาย ต้องนำส่งภาษีขาย)"},{"style":"sub","text":"กรณีทรัพย์สินกิจการร่วมค้าที่ปิด Project นำไปใช้ในกิจการอื่นๆ"},{"style":"sub2","text":"ขายในราคาซากให้แก่กิจการที่นำทรัพย์สินนั้นไปใช้ บัญชีจะออกใบกำกับภาษี เพื่อที่พัสดุ/ทรัพย์สินนำไปออกรหัสทรัพย์สิน (Asset Code)"}],"extra":["GL","AR","SE"],"attachments":[{"label":"SOP-10 · Fixed Asset Transfer","url":"https://drive.google.com/file/d/11MqcK2v-0Azva_ZgnWGXTdDo2pJi8cov/view?usp=drive_link"}]},{"no":14,"module":"AP","display_no":"AP-2","sort_order":2,"title_th":"กรณีการระบุชื่อผู้รับเงินบนหน้าเช็ค / ใบอนุมัติจ่าย / ข้อมูลเจ้าหนี้ในระบบ","title_en":"Beneficiary Mismatch","problem":"เดิมมีการจัดทำใบเตรียมจ่ายในนามบุคลากร แต่มีการออกเช็คเป็นเงินสดและแก้ไขข้อมูลในเอกสารที่พิมพ์จากระบบภายหลัง ส่งผลให้ระบบบันทึกเสมือนว่าได้จ่ายเงินให้แก่ผู้รับประโยชน์ตามชื่อที่ระบุ ทั้งที่ข้อเท็จจริงอาจแตกต่างกัน ทำให้ข้อมูลทางบัญชีและข้อมูลในระบบไม่ถูกต้อง อีกทั้งผู้รับเช็คอาจไม่นำเช็คเข้าหรือดำเนินการตามวัตถุประสงค์ที่กำหนดไว้ ส่งผลให้เกิดความเสี่ยงต่อความผิดพลาดและการทุจริต","ref":"ERP Manual 14.3.68 – บทที่ 6 (AP)","note":null,"date_added":"1 เมษายน 2569","steps":[{"style":"num","text":"วัตถุประสงค์และนโยบายหลัก (Purpose & Core Policies)"},{"style":"sub","text":"Matching 100%: ชื่อผู้รับประโยชน์/ผู้รับเงินบน หน้าเช็ค (หรือเอกสารโอนเงิน) และ ใบอนุมัติจ่าย (APP / Pre-Payment) รวมถึง ใบสำคัญจ่าย (PV) ต้องตรงกันทุกประการ"},{"style":"sub","text":"ห้ามแก้ไขด้วยลายมือ (No Manual Alteration): ห้ามทำการขีดฆ่า แก้ไข หรือเขียนเพิ่มเติมชื่อผู้รับเงินด้วยลายมือบนเอกสารที่พิมพ์ออกจากระบบ ERP โดยเด็ดขาด เอกสารที่มีการแก้ไขด้วยลายมือถือเป็นเอกสารโมฆะและไม่สามารถใช้ประกอบการทำจ่ายได้"},{"style":"sub","text":"ห้ามสั่งจ่ายเช็คเงินสด (No Cash Cheque): ห้ามออกเช็คสั่งจ่าย \"เงินสด\" (Cash) สำหรับรายการที่มีการตั้งจ่ายในนามบุคคลหรือนิติบุคคลในระบบ ยกเว้นได้รับการอนุมัติเป็นกรณีพิเศษจากฝ่ายบริหาร"},{"style":"num","text":"การอนุมัติจ่ายและการออกเช็ค/โอนเงิน (Approve Payment & Preparing Cheque)"},{"style":"bullet","text":"[แผนกการเงิน / บัญชี]"},{"style":"sub","text":"เข้าไปที่โมดูล AP ➔ อนุมัติจ่าย ➔ อนุมัติจ่าย APV/APS/APO"},{"style":"sub","text":"ตรวจสอบชื่อผู้รับเงิน (Pay To) ให้ตรงกับเจ้าหนี้ตามเอกสารตั้งหนี้"},{"style":"sub","text":"ระบบจะสร้างเลขที่ชุดอนุมัติจ่าย (Pre-Payment / APP)"},{"style":"num","text":"การจัดทำเช็ค/โอนเงิน (Preparing Cheque / PV): เข้าไปที่โมดูล AP ➔ Preparing Cheque, Credit Line ➔ ชำระโดยเช็ค หรือโอนเงิน"},{"style":"sub","text":"ดึงชุดอนุมัติจ่ายมาทำรายการสั่งจ่าย โดยระบบจะดึงชื่อผู้รับเงิน (Pay To) และบัญชีธนาคารจากฐานข้อมูล Master มาให้อัตโนมัติ ห้ามผู้ใช้งานเปลี่ยนชื่อผู้รับเงินเป็นเงินสด หรือเปลี่ยนชื่อบุคคลอื่นในขั้นตอนนี้"},{"style":"num","text":"กระบวนการยกเลิก/ถอยเอกสาร เพื่อขออนุมัติใหม่ (Reversal Workflow)"},{"style":"bullet","text":"[แผนกการเงิน / บัญชี / ผู้มีอำนาจอนุมัติ] กรณีจำเป็นต้องเปลี่ยนแปลงชื่อผู้รับเงิน หรือเปลี่ยนรูปแบบ/วิธีการจ่ายเงิน เนื่องจากการอนุมัติของบริหารครอบคลุมทั้งความเหมาะสมของค่าใช้จ่ายและตัวตนผู้รับเงิน/วิธีการจ่าย ห้ามแก้ไขบนกระดาษ แต่ต้องดำเนินการถอยเอกสารในระบบเพื่อขออนุมัติใหม่ทั้งสายงาน ดังนี้:"},{"style":"bullet","text":"กรณียังไม่ออกเช็ค/PV (ยกเลิกชุดอนุมัติจ่าย):"},{"style":"sub","text":"เข้าไปที่โมดูล AP ➔ อนุมัติจ่าย ➔ เลือกเมนู ยกเลิกการอนุมัติจ่าย (Cancel Approve Payment)"},{"style":"sub","text":"เลือกชุดอนุมัติจ่าย (Payment No.) ที่ต้องการยกเลิก ระบุเหตุผลการยกเลิก แล้วกด Save เพื่อปลดล็อกเอกสาร APV/APS/APO กลับไปสู่สถานะรออนุมัติจ่าย"},{"style":"bullet","text":"กรณีมีการบันทึกเช็ค/PV แล้ว:"},{"style":"sub","text":"ต้องทำการยกเลิกเอกสารใบสำคัญจ่าย (PV) และยกเลิกเช็คในระบบก่อน แล้วจึงมาทำรายการ >ยกเลิกการอนุมัติจ่าย ในโมดูล AP"},{"style":"bullet","text":"การแก้ไขข้อมูลและส่งอนุมัติใหม่:"},{"style":"sub","text":"ทำการตั้งชุดอนุมัติจ่าย (APP) และส่งให้ผู้บริหารอนุมัติใหม่ตามชื่อเจ้าหนี้/ผู้รับเงินที่ต้องการก่อนทำการพิมพ์เช็ค/โอนเงินอีกครั้ง"},{"style":"num","text":"การติดตามและควบคุมภายใน (Internal Control & Audit)"},{"style":"sub","text":"ฝ่ายตรวจสอบภายใน (Internal Audit): จะทำการสุ่มตรวจเช็คใบสำคัญจ่าย (PV) สลิปโอนเงิน และสุ่มตรวจเทียบกับชื่อผู้รับเงินในระบบ Mango ERP หากพบรายการขีดฆ่าแก้ไขด้วยลายมือ หรือสั่งจ่ายไม่ตรงกับใบ APP จะถือเป็นข้อบกพร่องร้ายแรงทางด้านการควบคุมภายใน"}],"extra":[],"attachments":[{"label":"SOP-14 · Beneficiary Matching","url":"https://drive.google.com/file/d/1gm8ya14IPoyN9VIOGOw2xKYOEOhl1mN6/view"}]},{"no":15,"module":"AP","display_no":"AP-3","sort_order":3,"title_th":"กรณีการตัดเจ้าหนี้ล่วงหน้าและการบันทึกใบกำกับภาษีย้อนหลัง","title_en":"Pre-Clearing Accounts Payable and Late Tax Invoice Entry","problem":"ในบางกรณีแผนกการเงินจำเป็นต้องทำรายการตัดเจ้าหนี้ก่อนเพื่อให้ยอดแสดงใน Statement และส่งข้อมูลเข้าสู่ระบบ GL แต่เอกสารใบเสร็จรับเงินหรือใบกำกับภาษีตัวจริงยังมาไม่ถึง (เช่น ส่งมาทางไปรษณีย์ หรือเจ้าหนี้ออกเอกสารไม่ถูกต้อง) ทำให้ไม่สามารถแนบเอกสารเพื่อเชื่อมโยงภาษีในขั้นตอนการตัดจ่ายปกติได้ และเมื่อจัดทำงบพิสูจน์ยอดแล้วจะไม่สามารถย้อนกลับไปถอยเอกสารเพื่อแนบหลักฐานเพิ่มเติมได้ จึงจำเป็นต้องกำหนดขั้นตอนการ \"บันทึกรับใบกำกับภาษีย้อนหลัง\" โดยใช้อ้างอิงเลขที่เอกสาร PL เพื่อให้รายงานภาษีซื้อและข้อมูลทางบัญชีถูกต้อง รวมถึงกำหนดแนวทางการจัดเก็บเอกสารหลักฐานตัวจริงให้เป็นมาตรฐานเดียวกัน","ref":"ERP Manual 14.3.68 – บทที่ 6 (AP) | บทที่ 10 (GL)","note":null,"date_added":"1 เมษายน 2569","steps":[{"style":"num","text":"ข้อกำหนดและนโยบายการปฏิบัติงาน (Policy Rules)"},{"style":"sub","text":"การบันทึกรับใบกำกับภาษีย้อนหลังจะทำได้ เฉพาะรายการที่มีการทำเอกสารตัดเจ้าหนี้ (PL) หรือตัดลูกหนี้ (RL) เสร็จสิ้นสมบูรณ์แล้วเท่านั้น โดยเมื่อได้รับใบเสร็จรับเงิน/ใบกำกับภาษีตัวจริงในภายหลัง ให้นำเอกสารต้นฉบับแนบเข้ากับชุดเอกสารกระดาษของ PL/RL โดยตรง ไม่ต้องทำการสแกนแนบไฟล์ในระบบ ERP"},{"style":"num","text":"ขั้นตอนการปฏิบัติงานในระบบ Mango ERP (System Workflow)"},{"style":"bullet","text":"ขั้นตอนที่ 1: การบันทึกตัดเจ้าหนี้ในระบบ (Clear AP)"},{"style":"bullet","text":"[แผนกการเงิน]"},{"style":"sub","text":"เข้าไปที่โมดูล AP ➔ ดำเนินการ ➔ บันทึกตัดเจ้าหนี้/บันทึกรับใบกำกับภาษีย้อนหลัง"},{"style":"sub","text":"เลือกเมนู บันทึกตัดเจ้าหนี้ (Clear AP) ➔ เลือกรายการเจ้าหนี้ที่ต้องการตัดชำระ ตรวจสอบข้อมูลให้ถูกต้อง แล้วกด Save"},{"style":"sub","text":"ระบบจะทำการตัดจ่ายเจ้าหนี้ บันทึกยอดเข้าระบบ GL ทันที และสร้างเอกสารใบสำคัญตัดเจ้าหนี้ (PL)"},{"style":"bullet","text":"ขั้นตอนที่ 2: การบันทึกรับใบกำกับภาษีย้อนหลัง (Receive Document Tax)"},{"style":"bullet","text":"[แผนกการเงิน / บัญชีภาษี] เมื่อได้รับใบกำกับภาษีมาในภายหลัง ให้ดำเนินการบันทึกเข้าภาษีซื้อดังนี้:"},{"style":"sub","text":"เข้าไปที่โมดูล AP ➔ ดำเนินการ ➔ บันทึกตัดเจ้าหนี้/บันทึกรับใบกำกับภาษีย้อนหลัง"},{"style":"sub","text":"เลือกเมนู บันทึกรับใบกำกับภาษีย้อนหลัง (Receive Document Tax)"},{"style":"sub","text":"ที่ช่อง Ref. No. (F) ให้กดค้นหาและระบุ เลขที่เอกสาร PL ที่ได้ทำการตัดเจ้าหนี้ไว้ก่อนหน้านี้"},{"style":"sub","text":"เข้าไปที่แท็บ Tax Invoice Document แล้วกรอกรายละเอียดภาษีให้ครบถ้วน:"},{"style":"sub2","text":"TAX Invoice No.: ระบุเลขที่ใบกำกับภาษีตัวจริง"},{"style":"sub2","text":"TAX Date: ระบุวันที่ตามใบกำกับภาษี"},{"style":"sub2","text":"Amount / Rate % / VAT: ระบุจำนวนเงินก่อนภาษี อัตราภาษี และยอดภาษีมูลค่าเพิ่ม"},{"style":"sub","text":"กดที่แท็บ General Ledger (GL) เพื่อตรวจสอบความถูกต้องของการบันทึกบัญชีภาษีซื้อ"},{"style":"sub","text":"กด Save บันทึกข้อมูล ระบบจะสร้างแบบฟอร์มบันทึกรับใบกำกับภาษีย้อนหลัง และนำยอดภาษีเข้าสู่รายงานภาษีซื้อให้อัตโนมัติ"},{"style":"bullet","text":"ขั้นตอนที่ 3: การจัดทำชุดเอกสารตัวจริง (Physical File Archiving)"},{"style":"bullet","text":"[แผนกการเงิน]"},{"style":"sub","text":"พิมพ์แบบฟอร์มบันทึกรับใบกำกับภาษีย้อนหลังออกจากระบบ"},{"style":"sub","text":"นำใบกำกับภาษี/ใบเสร็จรับเงินตัวจริงที่ได้รับมา แนบเข้ากับชุดเอกสารใบสำคัญ PL เดิม และแนบแบบฟอร์มรับใบกำกับภาษีย้อนหลังไว้เป็นหลักฐานประกอบ"},{"style":"sub","text":"จัดเก็บเข้าแฟ้มเอกสารจ่ายตามงวดบัญชีเพื่อรอการตรวจสอบจาก Auditor"}],"extra":["GL"],"attachments":[{"label":"SOP-16 · Pre Clear AP Late Tax Invoice","url":"https://drive.google.com/file/d/1YdWJckcx_tyxnr68ef1Me9dU3GVUn0uV/view"}]},{"no":16,"module":"GL","display_no":"GL-1","sort_order":1,"title_th":"กรณีการบันทึกขาบัญชีรายการตั๋วอาวัลและตั๋ว PN","title_en":"Accounting Treatment for Bills of Exchange & Promissory Note","problem":"เดิมยังไม่มีขั้นตอนรองรับกรณีที่ ธนาคารอนุมัติออกตั๋ว การขายลดตั๋ว แก่สถาบันการเงิน และ การตัดชำระ ให้แก่ ผู้รับผลประโยชน์ตามหน้าตั๋ว ส่งผลให้ยอดระหว่างแผนกการเงินและแผนกบัญชีไม่ตรงกัน โดยเฉพาะ ในกรณีที่ไม่มีการชำระทันทีหลังจาก การขายลดตั๋ว","ref":"ERP Manual 14.3.68 – บทที่ 10 (GL) | บทที่ 6 (AP)","note":null,"date_added":"1 เมษายน 2569","steps":[{"style":"num","text":"เมื่อธนาคารอนุมัติออกตั๋ว B/E และมีหักค่าธรรมเนียมการออกตั๋ว ให้บันทึกที่โมดูล G/L ดังนี้"},{"style":"sub2","text":"Dr. ลูกหนี้-อื่นๆ  A  (รหัสบัญชี  17501 ลูกหนี้-ธนาคาร/BE/PN )"},{"style":"sub2","text":"Cr. เงินกู้-ตั๋วอาวัล-ธนาคารกรุงเทพ  (รหัสบัญชี  20305 )"},{"style":"sub","text":"ในส่วนของค่าธรรมเนียม:"},{"style":"sub2","text":"Dr.ค่าธรรมเนียมธนาคาร (หมวด6  หรือ หมวด9)"},{"style":"sub2","text":"Cr.ธนาคารที่ตัดบัญชี"},{"style":"sub","text":"โดยหากทางเจ้าหนี้รับตั๋วอาวัลไปขายเอง   จะเข้าสู่ระบบ AP ตัดยอดตาม VC ปกติ"},{"style":"bullet","text":"เมื่อทาง เจ้าหนี้ต้องการให้บริษัทฯ ขายตั๋วให้  บันทึกบัญชีขั้นตอนการขายตั๋วอาวัล ให้บันทึกที่โมดูล AR"},{"style":"sub2","text":"Dr. ธนาคารที่รับเงิน"},{"style":"sub2","text":"Cr. ลูกหนี้-อื่นๆ  A  (รหัสบัญชี  17501 ลูกหนี้-ธนาคาร/BE/PN )"},{"style":"sub","text":"ในส่วนของค่าธรรมเนียม:"},{"style":"sub2","text":"Dr.ค่าธรรมเนียมธนาคาร (หมวด6  หรือ หมวด9)"},{"style":"sub2","text":"Cr.ธนาคารที่ตัดบัญชี"},{"style":"sub","text":"โดยเมื่อจ่ายเจ้าหนี้ จะเข้าสู่ระบบ AP ตัดยอด VC ปกติ Cr.ธนาคารที่ตัดเช็ค"},{"style":"bullet","text":"เมื่อตั๋วอาวัลครบกำหนดชำระตามเงื่อนไขธนาคาร  ให้บันทึกที่โมดูล  G/L"},{"style":"sub2","text":"Dr. เงินกู้-ตั๋วอาวัล-ธนาคารกรุงเทพ  (รหัสบัญชี  20305 )"},{"style":"sub2","text":"Cr.ธนาคารที่ตัดชำระ/ค่างาน/เบิกใช้ตั๋วPNเพื่อชำระอาวัล"},{"style":"num","text":"เมื่อมีการเบิกใช้ตั๋ว PN ให้บันทึกที่โมดูล G/L"},{"style":"sub2","text":"Dr. ธนาคารที่รับเงิน(กรณีให้เป็นเงินสด)"},{"style":"sub2","text":"Dr.ค่าธรรมเนียมธนาคาร (หมวด6 หรือ หมวด9)"},{"style":"bullet","text":"หรือ"},{"style":"sub2","text":"Dr.ตัดชำระตั๋วอาวัลครบกำหนด"},{"style":"sub2","text":"Cr. เงินกู้-ตั๋ว PN -ธนาคารกรุงเทพ (รหัสบัญชี 20204 )"},{"style":"bullet","text":"เมื่อการตัดชำระตั๋ว PN ให้บันทึกที่โมดูล G/L"},{"style":"sub2","text":"Dr. เงินกู้-ตั๋ว PN -ธนาคารกรุงเทพ (รหัสบัญชี 20204 )"},{"style":"sub2","text":"Cr.ธนาคารที่ตัดชำระ/ค่างาน/เบิกใช้ตั๋วPNเพื่อชำระตัวมันเอง(ยกตัวอย่างกรณี CVE)"}],"extra":[],"attachments":[{"label":"SOP-15 · Aval PN Accounting","url":"https://drive.google.com/file/d/1T7v0ZKrainUTbRaI1RyT39Tqh06SHlZA/view"}]},{"no":17,"module":"PM","display_no":"PM-2","sort_order":2,"title_th":"นโยบายการบันทึกรายได้ ค่าใช้จ่าย และค่าเสื่อมราคาเครื่องจักรและทรัพย์สิน","title_en":"Asset Revenue / Expense / Depreciation Allocation Policy","problem":"เดิมการบันทึกค่าเช่าเครื่องจักรและค่าซ่อมบำรุงอะไหล่ของโครงการเป็นรายได้ของสาย 5 ในมุมมองของ Profit Centre ซึ่งไม่สอดคล้องกับโครงสร้างสินเชื่อเพื่อโครงการ (Project Finance) ที่ธนาคารอนุมัติและเบิกจ่ายวงเงินโดยผูกกับแต่ละโครงการตาม Master Plan ที่ใช้ประกอบการขออนุมัติสินเชื่อ การเบิกใช้วงเงินต้องมีหลักฐานว่าค่าใช้จ่ายเกิดขึ้นเพื่อโครงการนั้น ค่าใช้จ่ายและเอกสารจัดซื้อที่บันทึกภายใต้สาย 5 จึงไม่สามารถใช้ประกอบการเบิกเงินได้ และบริษัทฯ ต้องใช้เงินทุนหมุนเวียนของตนเองรับภาระแทน นอกจากนี้ ค่าเช่าเครื่องจักรเป็นเพียงรายการโอนต้นทุนภายใน ไม่ใช่กระแสเงินสดรับจริง ทำให้ผลประกอบการของสาย 5 สูงเกินจริง และต้นทุนโครงการคลาดเคลื่อนจากงบประมาณที่ธนาคารใช้ติดตามผล จึงจำเป็นต้องปรับเกณฑ์การบันทึกให้ยึดโครงการเป็นหลัก เพื่อให้งบการเงินสำหรับผู้บริหารสอดคล้องกับมุมมองของธนาคาร","ref":"ERP Manual 14.3.68 – บทที่ 8 (PM)","note":null,"date_added":"1 เมษายน 2569","steps":[{"style":"num","text":"บันทึกภายใต้สำนักงานใหญ่ (Head Office / Central Fleet):"},{"style":"sub","text":"การรับรู้รายได้ (Revenue): บันทึกรายได้จากการคิดค่าเช่าเครื่องจักรและยานพาหนะทั้งหมด ที่เกิดจากการให้บริการแก่โครงการต่างๆ"},{"style":"sub","text":"การรับรู้ค่าใช้จ่าย (Expenses): บันทึกค่าใช้จ่ายที่เกี่ยวข้องกับตัวทรัพย์สินทั้งหมด รวมถึงค่าใช้จ่ายบุคลากรประจำเครื่องจักร (เช่น เงินเดือน/ค่าจ้าง พนักงานขับรถ, พนักงานขับเครื่องจักรกล และพนักงาน Oiler ที่ไปปฏิบัติงานตามโครงการต่างๆ)"},{"style":"num","text":"บันทึกภายใต้โครงการ (Project Cost Center):"},{"style":"sub","text":"การรับรู้ค่าใช้จ่าย (Project Expenses): บันทึกเฉพาะค่าใช้จ่ายที่อยู่ภายใต้งบประมาณของโครงการตาม Master Plan ที่ใช้ประกอบการขออนุมัติสินเชื่อ (Project Finance) กับสถาบันการเงินเท่านั้น เพื่อให้ผลการดำเนินงานของโครงการสะท้อนตามแผนวงเงินกู้จริง"},{"style":"num","text":"เกณฑ์การบันทึกค่าเสื่อมราคาและการโอนย้ายทรัพย์สิน (Depreciation & FA Asset Transfer)"},{"style":"sub","text":"การคิดค่าเสื่อมราคาประจำงวด (Period Depreciation): บันทึกค่าเสื่อมราคาเป็นค่าใช้จ่ายตาม \"โครงการ/หน่วยงานผู้ถือครองทรัพย์สิน\" นั้นๆ ณ งวดบัญชีปัจจุบัน"},{"style":"sub","text":"การโอนย้ายทรัพย์สินในระบบ ERP (Module FA Transfer):"},{"style":"sub2","text":"เมื่อสิ้นสุดโครงการและทำการโอนย้ายเครื่องจักร/ทรัพย์สิน ให้บันทึกรายการโอนย้ายใน Module FA"},{"style":"sub2","text":"ระบบจะทำการโอนยอดค่าเสื่อมราคาสะสม (Accumulated Depreciation) ไปยังโครงการใหม่ และคำนวณค่าเสื่อมราคาต่อเนื่องจากยอดคงเหลือเดิมทันทีอย่างอัตโนมัติ"},{"style":"num","text":"ขอบเขตผลกระทบและการปฏิบัติงานหน้างาน (Scope & Operational Impact)"},{"style":"sub","text":"ผลกระทบทางบัญชีและการบริหาร: มีผลเฉพาะการจัดทำงบการเงินสำหรับผู้บริหาร (Management Financial Statement) เพื่อวิเคราะห์ประสิทธิภาพการดำเนินงาน อัตราผลตอบแทนของสินทรัพย์ (ROA) และกำไรขาดทุนที่แท้จริงของแต่ละโครงการ"},{"style":"sub","text":"การปฏิบัติงานหน้างาน (On-site Daily Operations): ไม่มีผลกระทบใดๆ ต่อขั้นตอนปฏิบัติงานหน้ารายวัน พนักงานสโตร์ จัดซื้อ และวิศวกรหน้างานยังคงบันทึกเอกสารและดำเนินกระบวนการตามปกติทุกประการ (เช่น การเปิด PR, PO, OF, IC)"}],"extra":["AP","FA","GL","AR"],"attachments":[{"label":"SOP-27 · Profit Centre Bookkeeping","url":"https://drive.google.com/file/d/1UHKd7IpkG-GF-jpJuYzbmkdnlCkHL5bt/view"}]},{"no":18,"module":"PM","display_no":"PM-3","sort_order":3,"title_th":"กรณีการวิเคราะห์และบริหารเงินในระบบ","title_en":"Bank Account Management","problem":"เดิมบริษัทมีการทำรายการจ่ายเงินหรือโอนเงินระหว่างบัญชีภายในของบริษัท ทั้งกรณีที่เป็นนิติบุคคลเดียวกันและต่างนิติบุคคล โดยมิได้ระบุประเภทหรือออปชั่นการโอนเงินให้ถูกต้อง ส่งผลให้ระบบ Bank Account Management ซึ่งเป็นโมดูลที่พัฒนาเพิ่มเติมบนระบบ On-Web ไม่สามารถวิเคราะห์และจัดประเภทรายการได้อย่างถูกต้อง","ref":"ERP Manual 14.3.68 – บทที่ 8 (PM) | SE/FIN","note":null,"date_added":"1 เมษายน 2569","steps":[{"style":"num","text":"วัตถุประสงค์และปัญหาเดิม (Problem & Purpose)"},{"style":"sub","text":"ปัญหาเดิม: การทำรายการจ่ายเงินหรือโอนเงินระหว่างบัญชีภายในบริษัท (ทั้งนิติบุคคลเดียวกันและต่างนิติบุคคล) รวมถึงการบันทึกรายการในสมุดรายวัน (JV) ไม่ได้มีการระบุประเภทรายการรับ-จ่าย (Option) ให้ถูกต้อง ส่งผลให้โมดูล Bank Account Management บนระบบ On-Web ไม่สามารถวิเคราะห์ จัดกลุ่ม และตั้งยอด เดบิต/เครดิต (Debit/Credit) ของแต่ละบัญชีธนาคารได้อย่างถูกต้อง"},{"style":"sub","text":"วัตถุประสงค์: บังคับใช้มาตรฐานการระบุ Option ทุกครั้งที่มีการคีย์รายการ รับ-โอน-จ่าย เงิน เพื่อให้ข้อมูลวิ่งไปแสดงผลในหน้า Bank Account Management และรายงานกระแสเงินสด (Cash Flow) ได้อย่างแม่นยำแบบ Real-Time"},{"style":"num","text":"ข้อกำหนดและนโยบายการปฏิบัติงาน (Policy Rules)"},{"style":"sub","text":"บังคับระบุ Option ทุกรายการ: ทุกธุรกรรมที่มีการรับเงิน จ่ายเงิน หรือโอนเงินระหว่างบัญชีธนาคาร (ทั้งในโมดูล AP, AR, FN และ GL/JV) ต้องเลือก Option ให้ตรงตามวัตถุประสงค์จริงเสมอ"},{"style":"sub","text":"การตั้งค่าล็อกในระบบ (System Control): ให้แผนกบัญชี/Admin ตั้งค่าผังบัญชีธนาคารทุกบัญชี โดยเปิดปุ่ม Warning Option เพื่อให้ระบบแจ้งเตือนและบังคับให้ผู้ใช้งานต้องกรอก Option ก่อนบันทึกเอกสารทุกครั้ง"},{"style":"num","text":"ขั้นตอนการปฏิบัติงานในระบบ Mango ERP (System Workflow)"},{"style":"bullet","text":"ขั้นตอนที่ 1: การตรวจสอบและตั้งค่าข้อมูลหลัก (Master Setup)"},{"style":"bullet","text":"[ผู้ดูแลระบบ / แผนกบัญชี]"},{"style":"sub","text":"ตั้งค่า/แก้ไขชื่อกลุ่มรายการรับ-จ่าย: ไปที่ Setup Master ➔ Financial (FN) ➔ จัดกลุ่มรายการรับ-จ่าย (Option Pay / Receipt)"},{"style":"sub","text":"ตรวจสอบ/แก้ไข หรือเพิ่มรหัส Option Code และ Option Name สำหรับรายการโอนเงินระหว่างบัญชีภายในให้ชัดเจน (เช่น เงินโอนระหว่างบัญชี, เงินโอนข้ามนิติบุคคล)"},{"style":"sub","text":"เปิดการแจ้งเตือนเตือน Warning Option บนผังบัญชีธนาคาร: ไปที่ Setup Master ➔ Account (บัญชี) ➔ ผังบัญชี (Account Code)"},{"style":"sub","text":"เลือกรหัสบัญชีธนาคาร (Bank Account) ที่ต้องการ แล้วเปิดสวิตช์ Warning Option"},{"style":"sub","text":"กด Save บันทึกข้อมูล (เมื่อเปิดปุ่มนี้ ระบบจะล็อกไม่ให้บันทึกเอกสารหากผู้ใช้งานไม่ได้ระบุ Option)"},{"style":"bullet","text":"ขั้นตอนที่ 2: การบันทึกรายการประจำวัน (Daily Transaction Entry)"},{"style":"bullet","text":"[เจ้าหน้าที่การเงิน / แอดมิน / บัญชี]"},{"style":"sub","text":"การบันทึกโอนเงิน/ชำระเงินผ่านโมดูลการเงิน/เจ้าหนี้/ลูกหนี้ (AP / AR / FN):"},{"style":"sub","text":"ในขั้นตอนการคีย์รับ-จ่าย หรือโอนเงินผ่านธนาคาร ให้เลือกระบุช่อง Option Type / Option Name ให้ตรงกับประเภทธุรกรรมการโอนเงินนั้นๆ ทุกครั้ง"},{"style":"sub","text":"การบันทึกผ่านสมุดรายวันทั่วไป (GL - Journal Voucher / JV):"},{"style":"sub","text":"เข้าไปที่โมดูล GL ➔ บันทึกสมุดรายวัน (Journal Voucher) ➔ สร้างใบสำคัญ"},{"style":"sub","text":"ในตารางบันทึกบัญชี (General Ledger) บรรทัดที่เป็นรหัสบัญชีธนาคาร ให้เลื่อนไปที่คอลัมน์ Option แล้วเลือกระบุ Option Name ที่เกี่ยวข้องเสมอ ตรวจสอบความถูกต้องและกด Save"},{"style":"num","text":"การตรวจสอบผลลัพธ์ในระบบ (Verification & Monitoring)"},{"style":"bullet","text":"[ผู้บริหาร / ฝ่ายการเงิน]"},{"style":"sub","text":"สามารถเข้าไปตรวจสอบการจัดกลุ่มรายการโอนและยอดคงเหลือ เดบิต/เครดิต ของแต่ละบัญชีธนาคารได้ที่:"},{"style":"bullet","text":"Module PM ➔ Inquiry ➔ Bank Account Management"},{"style":"bullet","text":"ข้อมูลจะแสดงรายรับ (Debit) รายจ่าย (Credit) และยอดเช็คค้างชำระของแต่ละบัญชีธนาคารได้อย่างถูกต้องเพื่อใช้บริหารสภาพคล่องทางการเงิน"}],"extra":["AP","GL","AR","FIN"],"attachments":[{"label":"SOP-28 · Bank Account Management","url":"https://drive.google.com/file/d/1_W4xFgoxe8cXRvhf1q2sa6pxUWZKShAJ/view"}]},{"no":19,"module":"AP","display_no":"AP-4","sort_order":4,"title_th":"กรณีการจ่ายเงินทดลองเพื่อเปิดวงเงินในการซื้อ-ขาย","title_en":"Advance Payment for Vendor Purchase Credit","problem":"ปัจจุบันมีความสับสนในการบันทึกเงินที่ จ่ายล่วงหน้าให้กับร้านค้า (Advance) ที่มีลักษณะคล้ายคลึงกับการวางเงินมัดจำ (Other) เนื่องจากมีการซื้อขายอย่างต่อเนื่อง และไม่มีการเปลี่ยนเช็คค้ำประกันที่ร้านค้าได้นำมาวางไว้กับบริษัท","ref":"ERP Manual 14.3.68 – บทที่ 6 (AP)","note":"แนวทางการบันทึกและจัดการเงินจ่ายล่วงหน้า (Advance) แบบเครดิตหมุนเวียน (Rolling Credit) ตาม SOP ฉบับนี้ จะสามารถใช้ได้เฉพาะกรณีที่ร้านค้าออกใบกำกับภาษีเงินจ่ายล่วงหน้า (Advance Tax Invoice) ให้แก่บริษัทเท่านั้น","date_added":"1 เมษายน 2569","steps":[{"style":"num","text":"การแยกแยะประเภทเอกสารและความแตกต่างในระบบ [แผนกจัดซื้อ และ แผนกบัญชี]"},{"style":"bullet","text":"ต้องตรวจสอบและแยกแยะประเภทเงินที่จ่ายให้คู่ค้าออกจากกันให้ถูกต้องตั้งแต่ขั้นตอนตกลงสัญญาและจัดทำเอกสารหลัก:"},{"style":"sub","text":"Advance (เงินจ่ายล่วงหน้า): เป็นเงินจ่ายล่วงหน้าตามเงื่อนไขใบสั่งซื้อ (PO) ซึ่งบันทึกตั้งหนี้ในระบบผ่านหน้าจอ จากการรับสินค้าตาม PO (Type: Down) ยอดเงินนี้สามารถนำมาบันทึกหักลด รายงวด ได้ผ่านขั้นตอนรับของตาม PO Receive หรือหักจากงวดงานผู้รับเหมา"},{"style":"sub","text":"Deposit (เงินมัดจำ): บันทึกคำขอเบิกเงินสดผ่าน Module OF ➔ Deposit ถือเป็นเงินค้ำประกันสัญญากลาง ไม่สามารถนำมาทำตารางหักลดยอดรายงวดในหน้ารับของ PO ได้ ยอดเงินนี้จะคงค้างเป็นสินทรัพย์ในระบบจนกว่าจะยุติสัญญา และต้องทำเรื่องรับโอนคืนเต็มจำนวน (Refund/Return) เท่านั้น"},{"style":"num","text":"ขั้นตอนการบันทึกบัญชีและการบริหาร Rolling Credit ในระบบ [แผนกบัญชี]"},{"style":"sub","text":"เมื่อบริษัทจ่ายเงินล่วงหน้าตาม PO ให้ทำการตั้งหนี้ในระบบที่ Module AP ➔ ตั้งหนี้ ➔ จากการรับสินค้าตาม PO โดยเลือกประเภทการตั้งหนี้ (Type) เป็น Down เพื่อบันทึกยอดเป็น \"เงินจ่ายล่วงหน้าค่าสินค้า (Advance)\""},{"style":"sub","text":"ในแต่ละงวดเมื่อคู่ค้าส่งมอบสินค้าและวางบิล ให้แผนกบัญชีบันทึกรับของเต็มจำนวนโดย \"ไม่มีการระบุค่าหัก Less Adv. ออกจากยอดจ่าย\" เพื่อรักษายอดเครดิตหมุนเวียน (Rolling Credit) และลดภาระของคู่ค้าในการถอนและเปลี่ยนเช็คหรือเอกสารค้ำประกันในทุกๆ รอบงวด"},{"style":"sub","text":"เมื่อบริษัทต้องการ \"ยุติการซื้อขาย\" หรือจบโครงการร่วมกัน ให้แผนกบัญชีเข้าทำการปรับปรุงบัญชีล้างยอด โดยนำยอดตั้งหนี้ค่าสินค้าลอตสุดท้าย (APV) มาทำรายการหักล้าง (Offset) กับยอดบัญชี Advance สะสมที่คงค้างทั้งหมดในระบบ เพื่อเคลียร์ยอดคงเหลือของคู่ค้ารายนั้นให้เป็นศูนย์"},{"style":"num","text":"นโยบายการคืนหลักประกันและการจัดการงวดสุดท้าย (Guarantee Return & Final Settlement)"},{"style":"sub","text":"[แผนกจัดซื้อ และ แผนกวิศวกรรมโครงการ] ➔ ในช่วง 2–3 งวดสุดท้ายของการซื้อขาย แผนกจัดซื้อต้องประสานงานกับแผนกวิศวกรรมโครงการเพื่อร่วมกันวางแผนการสั่งซื้อและตรวจสอบยอดวางบิล เพื่อให้มั่นใจว่างวดงานที่เหลืออยู่จะเพียงพอต่อการตัดยอดเงิน Advance สะสมได้ครบถ้วนทั้งหมดภายในรอบการซื้อขายนั้นๆ"},{"style":"sub","text":"[แผนกการเงิน] ➔ บริษัทกำหนดเงื่อนไขในการคืนเอกสารค้ำประกัน เช่น เช็คค้ำประกัน หรือหนังสือค้ำประกันธนาคาร (Bank Guarantee - BG) กลับคืนให้แก่คู่ค้า ต่อเมื่อยอดเงิน Advance ในระบบได้รับการหักล้างจนครบถ้วน 100% แล้วเท่านั้น หากยอดเงิน Advance ยังค้างคาหรือร้านค้ายังไม่สามารถคืนเงินส่วนต่างให้บริษัทได้ครบถ้วน ห้ามทำการส่งคืนเอกสารหลักประกันค้ำประกันให้แก่คู่ค้าเด็ดขาด"},{"style":"sub","text":"[แผนกจัดซื้อ และ แผนกบัญชี] ➔ ในกรณีที่สุดวิสัย ยอดส่งสินค้าในงวดสุดท้ายมีมูลค่าไม่เพียงพอสำหรับการหักล้างเงิน Advance ให้ดำเนินการประสานงานให้ร้านค้าทำการ โอนเงินสดส่วนต่างคงเหลือทั้งหมดคืนเข้าบัญชีธนาคารของบริษัท และออก ใบลดหนี้ (Credit Note - CN) สำหรับยอดเงิน Advance ส่วนที่ยังไม่ได้หักล้างส่งมอบให้แผนกบัญชี เพื่อใช้ประกอบการบันทึกปรับปรุงบัญชีและรายงานภาษีให้ถูกต้อง"}],"extra":["PO","OF"],"attachments":[{"label":"SOP-06 · Advance Vendor Credit","url":"https://drive.google.com/file/d/1wy8lqZcA4KwKr5sF4U1KJHuLd6qzbcC5/view"}]},{"no":20,"module":"BD","display_no":"BD-1","sort_order":1,"title_th":"ขั้นตอนการนำเข้าและควบคุมงบประมาณ","title_en":"Budget Import & Control","problem":"เพื่อกำหนดมาตรฐานการนำเข้างบประมาณ การเปิดระบบควบคุมงบประมาณและปริมาณวัสดุ (Control Budget & BOQ) รวมถึงการตั้งค่าประมาณการงบประมาณล่วงหน้า (Forecast Budget) ให้มีความถูกต้องและเชื่อมโยงข้อมูลระหว่างโมดูล BD และ PM ได้อย่างสมบูรณ์","ref":"ERP Manual 14.3.68 – บทที่ 2 (BD) | บทที่ 8 (PM)","note":null,"date_added":"1 เมษายน 2569","steps":[{"style":"num","text":"การนำเข้าและตั้งค่าควบคุมงบประมาณในหมวด BD (Module BD)"},{"style":"bullet","text":"[ฝ่ายประเมินราคา / วิศวกรสำนักงาน / แอดมิน BD]"},{"style":"bullet","text":"การนำเข้า BOQ/Budget และระบุ Job Code:"},{"style":"sub","text":"เข้าโมดูล BD ➔ Transaction ➔ Bill of Quantity (BOQ)"},{"style":"sub","text":"ทำการ Import ไฟล์งบประมาณ/BOQ เข้าระบบ"},{"style":"sub","text":"ในช่อง Job Code สำหรับงาน Civil Work ให้กรอกเป็น \" '001 \" ทุกรายการ"},{"style":"num","text":"การตั้งค่าควบคุมงบประมาณ (Control Budget):"},{"style":"sub","text":"ก่อนส่งเอกสารขออนุมัติงบประมาณ ต้องทำเครื่องหมายถูก (Check) ที่ช่อง \"Control Budget\" (หรือเลือกเป็น By Summary Cost Code) เสมอ เพื่อเปิดระบบการควบคุมต้นทุน"},{"style":"sub","text":"การปรับขยายวงเงินราย Item: ค่า Default ของระบบจะตั้งไว้ที่ 100% หากหน้างานมีความจำเป็นต้องขยายวงเงินเฉพาะบางรายการ ให้เข้าไปที่หน้า Project Budget (แท็บ Cost Code Summary / Setup % Control) เพื่อแก้ไขปรับเพิ่ม % Control ให้รองรับการทำงานจริง"},{"style":"num","text":"การตั้งค่าควบคุมปริมาณวัสดุ (Control Material QTY):"},{"style":"sub","text":"หากต้องการควบคุมปริมาณวัสดุเพิ่มเติม ต้องระบุรหัสวัสดุ (Material Code) ให้ครบถ้วนทุกรายการ"},{"style":"sub","text":"จากนั้นทำเครื่องหมายถูกที่ช่อง \"Control BOQ\" หรือ \"Control by Summary\" (ในแท็บ Summary Material) เพื่อให้ระบบล็อกปริมาณการขอซื้อ/ขอเบิกไม่ให้เกิน BOQ"},{"style":"num","text":"การตั้งค่างบประมาณประมาณการล่วงหน้าในหมวด PM (Module PM)"},{"style":"bullet","text":"[แผนกวิศวกรรม]"},{"style":"sub","text":"เข้าสู่โมดูล PM ➔ Transaction ➔ Project Forecast Expected Cost (Forecast Budget)"},{"style":"sub","text":"ค้นหาและเลือกรหัสโครงการ (Project No.) ที่ต้องการ"},{"style":"sub","text":"ไปที่แท็บ Budget แล้วให้แผนกวิศวกรรมกดปุ่ม \"Copy Forecast Budget\" (หรือ Init. Budget Cost) ระบบจะทำการดึงยอดงบประมาณปัจจุบัน (Current Budget) มากรอกในช่อง Forecast ให้อัตโนมัติ"},{"style":"sub","text":"ตรวจสอบความถูกต้องของตัวเลขงบประมาณ แล้วกดปุ่ม Save (บันทึก) ข้อมูลจะถูกนำไปใช้ประมวลผลต่อในรายงาน Project Status Overview, S-Curve Graph และรายงานวิเคราะห์สภาพคล่องของโมดูล PM ทันที"}],"extra":["PM"],"attachments":[{"label":"SOP-17 · Budget Import Control","url":"https://drive.google.com/file/d/1H7tHAe22DPy_Ye_sQ2bvak0nYSDdc44B/view"}]},{"no":21,"module":"OF","display_no":"OF-4","sort_order":4,"title_th":"กรณีการเคลียร์ยอดเงินทดลองและและการซ่อมทรัพย์สิน","title_en":"Advance Balance Clearance and Asset Maintenance","problem":"เดิมการเคลียร์ยอดถูกดำเนินการผ่านขั้นตอนปกติที่ต้องผ่าน Loop ใบเตรียมจ่าย ส่งผลให้รายการดังกล่าวไปแสดงรวมอยู่ในรายงานค่าใช้จ่ายของโครงการซึ่งไม่ถูกต้องตามหลักการ เนื่องจากรายงานควรแสดงเฉพาะการจ่ายออกเท่านั้น ส่วนรายการเคลียร์ยอดซึ่งมีผลสุทธิเป็น 0 ไม่ควรปรากฏในรายงานดังกล่าว","ref":"ERP Manual 14.3.68 – บทที่ 3 (OF) | บทที่ 5 (IC)","note":null,"date_added":"1 เมษายน 2569","steps":[{"style":"num","text":"การเคลียร์เงินทดรองจ่าย (Clear Advance) และค่าอะไหล่ซ่อมแซม ให้แอดมินโครงการไปที่โมดูล OF ➔ ดำเนินการ ➔ ใบเบิกเงินสดย่อยและใบเบิกจ่ายที่ไม่มี PO/WO เลือกประเภทเอกสาร (Document Type) เป็น Clear Advance ทำการระบุชื่อผู้เบิกเงินทดรองและโครงการให้ตรงกับตอนที่ตั้งเรื่องเบิก Advance"},{"style":"sub","text":"กรณีเป็นค่าอะไหล่ซ่อมแซม (ไม่เข้าสต๊อก): ที่แท็บรายการ ให้เลือก \"รหัสค่าใช้จ่าย\" เป็นกลุ่ม \"อะไหล่ซ่อมแซม\" และในช่อง รายละเอียดเพิ่มเติม (Remark) ให้ระบุ เลขที่อ้างอิงทรัพย์สิน/เครื่องจักร และรายละเอียดอะไหล่ให้ครบถ้วน"},{"style":"sub","text":"จากนั้นกดปุ่ม \"เงินทดรองจ่าย\" เพื่อดึงยอด Advance เดิมมาหักล้าง (ระบบจะคำนวณส่วนต่างและล้างยอด APO ค้างให้อัตโนมัติ โดยไม่ต้องผ่านกระบวนการใบเตรียมจ่าย) กด Save และส่งอนุมัติ"},{"style":"sub","text":"หากเป็นการเบิกเงินไปเพื่อซื้อของเข้าสต๊อก ควรให้จัดซื้อเปิด PR/PO แทนการใช้เงิน Advance เพื่อป้องกันปัญหาสินค้าตกหล่นจากการไม่มี PO Receipt"},{"style":"num","text":"การคืนอะไหล่ส่วนที่ใช้ไม่หมดเข้าสต๊อก (Manual IC Receive)"},{"style":"sub","text":"ให้แอดมินโครงการ ไปที่โมดูล IC ➔ Document IC Receive ➔ Stock Receive (รับวัสดุเข้าคลัง) ระบุคลังสินค้า (Warehouse) ที่ต้องการนำอะไหล่ไปเก็บ"},{"style":"sub","text":"บันทึกรับรหัสวัสดุ (อะไหล่) กลับเข้าคลัง โดยระบุจำนวน (QTY) ที่เหลือจริง และ ใส่มูลค่าต่อหน่วย (Price/Unit) เป็น 0 ตามนโยบาย กด Save เพื่ออัปเดตยอดคงเหลือในสต๊อก"},{"style":"sub","text":"หากอะไหล่เหลือมีมูลค่าน้อยมาให้ข้ามขั้นตอนนี้ และบันทึกเป็นค่าใช้จ่ายเต็มจำนวนในส่วนที่ 1 ได้เลย"},{"style":"num","text":"การตั้งรหัสและรับของเข้าทรัพย์สิน (กรณีซ่อมข้ามนิติบุคคล)"},{"style":"sub","text":"กรณีนำอะไหล่ไปซ่อมข้ามนิติบุคคล และต้องตั้งรหัสทรัพย์สินเฉพาะกลุ่ม: ให้แผนกบัญชีทรัพย์สินไปที่โมดูล FA ➔ บันทึกรายการ ➔ บันทึกเพิ่มทรัพย์สิน (Entry Asset)"},{"style":"sub","text":"Asset Code (รหัสทรัพย์สิน): ให้ระบุรหัสโดยขึ้นต้นด้วย \"Z\" ตามนโยบาย"},{"style":"sub","text":"Depreciation (การคิดค่าเสื่อม): ให้เลือกเป็น \"No\" (ไม่คิดค่าเสื่อม)"},{"style":"sub","text":"Description (รายละเอียดเพิ่มเติม): ให้ระบุหมายเหตุว่า \"ทรัพย์สินเก่าก่อนขึ้นระบบ\""},{"style":"sub","text":"ระบุข้อมูลอื่นๆ ให้ครบถ้วน (เช่น ประเภททรัพย์สิน, สถานที่ตั้ง, รหัสบัญชี)"},{"style":"sub","text":"ตรวจสอบความถูกต้องและกด Save ระบบจะสร้างฟอร์มใบบันทึกข้อมูลทรัพย์สิน"},{"style":"num","text":"การบันทึกประวัติการซ่อมบำรุงและค่าใช้จ่ายของเครื่องจักร [แผนกบัญชี / ช่างซ่อมบำรุง] เพื่อให้แผนกบัญชีสามารถตรวจสอบประวัติการซ่อมและจำนวนอะไหล่ที่ใช้กับเครื่องจักรแต่ละเครื่องได้อย่างถูกต้อง:"},{"style":"sub","text":"หลังจากเคลียร์เอกสารในโมดูล OF แล้ว ให้ไปที่โมดูล FA ➔ บันทึกรายการ ➔ บันทึกค่าใช้จ่ายเกี่ยวกับทรัพย์สิน ➔ บันทึกค่าบำรุงรักษาและค่าใช้จ่าย"},{"style":"sub","text":"เลือก Asset Code (รหัสทรัพย์สินเครื่องจักร/รถยนต์ ที่ทำการซ่อม)"},{"style":"sub","text":"ที่ช่อง Maintenance/Cost code ให้เลือกรหัสค่าใช้จ่ายซ่อมแซม"},{"style":"sub","text":"ระบุจำนวน (Qty) ของอะไหล่ และจำนวนเงิน (Amount) ค่าซ่อมแซมที่เกิดขึ้นจริง"},{"style":"sub","text":"ระบุรายละเอียดในช่อง Description ให้ชัดเจน (เช่น เปลี่ยนอะไหล่ชิ้นไหน) แล้วกด Save"},{"style":"sub","text":"เมื่อบันทึกข้อมูลส่วนนี้ ข้อมูลจะถูกเก็บเป็น \"ประวัติการซ่อมบำรุงเครื่องจักร\" ซึ่งสามารถเรียกดูรายงาน (Maintenance Report) ได้อย่างครบถ้วนในอนาคต"}],"extra":["IC","FA"],"attachments":[{"label":"SOP-20 · Advance Clearance Asset Repair","url":"https://drive.google.com/file/d/1ds7tzQ8lxV75ksV5hWHcGttf5gwOgR32/view"}]},{"no":22,"module":"SE","display_no":"SE-1","sort_order":1,"title_th":"กรณีการแก้ไขสิทธิ์การใช้งานและการเพิ่มบุคลากร ในระบบ","title_en":"User Setup & Access Rights","problem":"เดิมบริษัทกำหนดสิทธิ์การใช้งานแยกตามแต่ละบริษัทเป็นจำนวนมาก ทำให้สิทธิ์ของผู้ใช้งานที่อยู่ในตำแหน่งเดียวกัน หรือลักษณะงานที่คล้ายกัน ไม่มีมาตรฐานเดียวกัน มีการเปิดและปิดสิทธิ์แตกต่างกันในแต่ละคนจนยากต่อการตรวจสอบ บริษัทจึงได้ทำการ set running number ของพนักงานทุกคนทุกกิจการให้ตรงกันและเปลี่ยนมาใช้ **Permission Template** และ **User Group** มาตรฐาน เพื่อให้สามารถกำหนดสิทธิ์ตามบทบาทหน้าที่ได้อย่างเป็นระบบ ลดความผิดพลาดในการกำหนดสิทธิ์รายบุคคล และทำให้สามารถตรวจสอบและบริหารจัดการสิทธิ์ของผู้ใช้งานให้เป็นมาตรฐานเดียวกันทั้งองค์กร","ref":"ERP Manual 14.3.68 – บทที่ 1","note":"ห้ามแก้ไข User Rights รายบุคคล ไม่ว่าจะใน บริษัท วิจิตรภัณฑ์ ก่อสร้าง จำกัด หรือบริษัทอื่นในเครือโดยไม่ได้รับอนุมัติ หากมีความจำเป็นต้องกำหนดสิทธิที่แตกต่างจาก Template ปัจจุบัน ให้แจ้งเหตุผลว่าทำไม Template User Rights ที่ใช้อยู่จึงไม่รองรับความต้องการ และให้พิจารณาปรับปรุง Template User Rights เป็นหลัก แทนการแก้ไขสิทธิเป็นรายบุคคล เพื่อให้มาตรฐานการกำหนดสิทธิเป็นไปในแนวทางเดียวกันทั้งองค์กร","date_added":"24 กรกฎาคม 2569","steps":[{"style":"num","text":"กรณีเพิ่มผู้ใช้งาน (User) ใหม่"},{"style":"sub","text":"ให้สร้าง User ใน บริษัท วิจิตรภัณฑ์ก่อสร้าง จำกัด ก่อนเสมอ"},{"style":"num","text":"กรณีแก้ไขสิทธิ์การใช้งาน (User Rights)"},{"style":"sub","text":"ให้ดำเนินการแก้ไขใน บริษัท วิจิตรภัณฑ์ก่อสร้าง จำกัด ก่อนเสมอ โดยทำการ “Copy Template User Rights” ปัจจุบัน จาก Template Group ที่กำหนดไว้ 13 กลุ่มหลักสำหรับแต่ละตำแหน่งงาน ไปยังพนักงานที่ต้องการ"},{"style":"sub","text":"หลังจากตรวจสอบความถูกต้องแล้ว ให้ดำเนินการ “Copy User to Company” เพื่อคัดลอก User และ User Rights ไปยังบริษัทอื่นในเครือตามลำดับ"},{"style":"num","text":"กรณีตั้งค่าสิทธิการมองเห็นโครงการ (Project Rights)"},{"style":"sub","text":"ให้กำหนดสิทธิการมองเห็นโครงการตาม รายบุคคล สำหรับ แต่ละ Company เนื่องจากสิทธิการเข้าถึงโครงการของแต่ละบริษัทอาจแตกต่างกัน"},{"style":"num","text":"กรณีตั้งค่าสิทธิ์การมองเห็นคลังสินค้า (Site IC)"},{"style":"sub","text":"ให้กำหนดสิทธิ์การมองเห็นรายบุคคล โดยให้พัสดุประจำโครงการสามารถมองเห็นแค่โครงการที่ตัวเองรับผิดชอบ และในกรณีจำเป็นต้องมองเห็นเพิ่มเติม เช่น การใช้ถังน้ำมันร่วมกัน ให้แจ้งเป็นรายกรณีไป"}],"extra":[],"attachments":[{"label":"SOP-29 · User Rights Template","url":"https://drive.google.com/file/d/12nbKemU4K4_1RADfc4cQizTcka6wmzfM/view"}]},{"no":23,"module":"SE","display_no":"SE-2","sort_order":2,"title_th":"กรณีการกำหนดผู้รับผิดชอบเปิด PR/OF และ Loop อนุมัติ","title_en":"PR/OF Responsibility & Loop Assignment","problem":"เดิมการเปิดเอกสาร OF ทั้งหมดดำเนินการโดยแผนกบัญชี และยังไม่มีการกำหนดมาตรฐานที่ชัดเจนว่าหน่วยงานหรือโครงการใดมีหน้าที่เปิดเอกสาร PR และ OF สำหรับงานแต่ละประเภท ส่งผลให้มีการเปิดเอกสารผ่าน Loop อนุมัติ/โครงการที่ไม่ถูกต้อง เช่น โครงการเปิด PR งานซ่อมบำรุงเองโดยไม่ผ่านศูนย์ซ่อมสาย 5 ทำให้การซ่อมบำรุงขาดการกำกับดูแลจากผู้จัดการศูนย์ซ่อม และข้อมูลทรัพย์สินในระบบ FA คลาดเคลื่อน บริษัทฯ จึงกำหนดผู้รับผิดชอบและ Loop อนุมัติสำหรับการเปิดเอกสาร PR และ OF แยกตามประเภทงาน ดังนี้","ref":"ERP Manual 14.3.68 – บทที่ 1 (SE) | บทที่ 4 (PO) | บทที่ 3 (OF)","note":null,"date_added":"1 เมษายน 2569","steps":[{"style":"num","text":"กรณีการเปิด PR (Purchase Requisition):"},{"style":"sub","text":"งานก่อสร้างปกติที่ต้องการเปิดใบสั่งซื้อ (PO): ให้โครงการเป็นผู้เปิด PR เอง โดยเลือกชื่อโครงการหลักและใช้ Loop PR010: อนุมัติเอกสาร PR (โครงการ-PO)"},{"style":"sub","text":"งานก่อสร้างปกติที่ต้องการเปิดใบสั่งจ้าง (WO): ให้โครงการแจ้งความประสงค์มายังแผนกวิศวกรรมสำนักงานใหญ่ เพื่อให้ทางวิศวะสำนักงานใหญ่เปิด PR ที่ถูกต้องผ่าน Loop PR012: อนุมัติเอกสาร PR (โครงการ-WO)"},{"style":"sub","text":"งานซ่อมบำรุงเครื่องจักรและทรัพย์สิน: ให้โครงการแจ้งความประสงค์มายังสาย 5 เท่านั้น เพื่อให้ทางสาย 5 เปิด PR ที่ถูกต้องผ่าน Loop PR007: อนุมัติเอกสาร PR (โครงการ-ซ่อมเครื่องจักร) โดยผ่านการอนุมัติของผู้จัดการศูนย์ซ่อม สาย 5 และหัวหน้าแผนกพัสดุทรัพย์สิน"},{"style":"sub","text":"ค่าใช้จ่ายของสาย 5 โดยตรง (ไม่เกี่ยวข้องกับโครงการ): ให้เลือก Project เป็น \"ศูนย์ซ่อมเครื่องจักรกล พุทธมณฑลสาย 5\" เท่านั้น"},{"style":"num","text":"กรณีการเปิด OF (Office Service):"},{"style":"sub","text":"งานก่อสร้างปกติภายในประเทศ: ให้โครงการหลักเป็นผู้เปิด OF เข้ามาเอง โดยใช้ Loop OF-B002 และ OF-B003: อนุมัติเอกสารเงินทดรองจ่ายและจ่ายอื่นๆ (โครงการในประเทศ)"},{"style":"sub","text":"งานก่อสร้างปกติต่างประเทศ: ให้โครงการหลักเป็นผู้เปิด OF เอง โดยใช้ Loop OF-B004 และ OF-B005: อนุมัติเอกสารเงินทดรองจ่ายและจ่ายอื่นๆ (โครงการต่างประเทศ)"},{"style":"sub","text":"งานซ่อมบำรุงเครื่องจักรและทรัพย์สิน: ให้โครงการแจ้งความประสงค์มายังสาย 5 (เช่นเดียวกับกรณี PR) ทางสาย 5 จะเปิด OF ผ่าน Loop OF-B007 และ OF-B008: อนุมัติเอกสารเงินทดรองจ่ายและจ่ายอื่นๆ (ค่าซ่อมเครื่องจักร) โดยเลือกโครงการที่จะทำการซ่อม และส่งอนุมัติผ่านผู้จัดการศูนย์ซ่อม สาย 5 และหัวหน้าแผนกทรัพย์สิน โดยอนุญาตให้พนักงานสาย 5 สามารถเข้าถึงทุกโครงการ (Multi-Company) เพื่อให้สามารถเลือกโครงการที่ถูกต้องในการเปิด PR ซ่อมเครื่องจักรได้อย่างเหมาะสม ทั้งนี้โครงการอื่นจะไม่มีสิทธิ์เปิด PR งานซ่อมบำรุงเอง"},{"style":"sub","text":"ค่าเงินเดือน ภงด.1 กยส., ประกันสังคม, ค่าสวัสดิการต่างๆ ของพนักงาน, ค่าธรรมเนียมธนาคาร, ค่าภาษีต่าง ๆ ที่ไม่อยู่ภายใต้หลักการดูแลของแผนกวิศวกรรม ให้เปิดผ่าน Loop OF-B000 และ OF-B001: อนุมัติเอกสารเงินทดรองจ่ายและจ่ายอื่นๆ (บริหาร) โดยพนักงานของสำนักงานใหญ่เท่านั้น"}],"extra":["PO","OF"],"attachments":[{"label":"SOP-19 · PR OF Loop Assignment","url":"https://drive.google.com/file/d/1Jzkr9WnBO9RM0RQE3Vs7nlk1Q4Nqun71/view"}]},{"no":24,"module":"OF","display_no":"OF-5","sort_order":5,"title_th":"กรณีการบันทึกยอดการรับเงินค่างานจากผู้ว่าจ้าง","title_en":"Progress Submission and Payment Receipt Recording","problem":"เดิมบริษัทไม่มีขั้นตอนการรับเงินและการบันทึกส่งมอบงานในระบบอย่างเป็นทางการ ทำให้เมื่อขึ้นระบบใหม่ ไม่สามารถดึงยอดรายรับตามช่องทางต่าง ๆ ไปประมวลผลในโมดูลบริหารโครงการ (PM) และโมดูลการเงิน (FIN) ได้อย่างถูกต้อง จึงกำหนดขั้นตอนการบันทึกเอกสารส่งมอบงานโครงการ (Progress Submit) สำหรับฝ่ายวิศวกรรม เพื่อใช้เป็นฐานข้อมูลรายรับที่แม่นยำในการนำไปเปิดใบแจ้งหนี้ (Invoice) ในโมดูล AR และส่งต่อข้อมูลไปประมวลผลในรายงานสถานะโครงการและกระแสเงินสด","ref":"ERP Manual 14.3.68 – บทที่ 3 (OF) | บทที่ 8 (PM)","note":null,"date_added":"1 เมษายน 2569","steps":[{"style":"num","text":"ข้อกำหนดและนโยบายหลัก"},{"style":"sub","text":"การบันทึกตามผลงานที่ Certify จริง: ในเบื้องต้น เพื่อลดขั้นตอนการทำงานและป้องกันความคลาดเคลื่อนของข้อมูล ให้ฝ่ายวิศวกรรมบันทึกยอดเงินขอเบิกโดยอ้างอิงจาก \"ใบตรวจรับงาน\" (Certify Progress) ที่ได้รับการเซ็นรับมอบและรับรองผลงานจริงจากผู้ว่าจ้าง/เจ้าของโครงการแล้วเท่านั้น"},{"style":"sub","text":"การส่งต่อข้อมูลข้ามโมดูล: เมื่อทำการบันทึกและตรวจรับรองในโมดูล OF เสร็จสิ้นแล้ว แผนกบัญชีจึงจะสามารถดึงยอดดังกล่าวไปเปิดใบแจ้งหนี้ (Invoice) ในโมดูล AR เพื่อบันทึกตั้งลูกหนี้ได้อย่างถูกต้อง"},{"style":"num","text":"การบันทึกขอเบิกเงินส่งมอบงาน (ฝ่ายวิศวกรรม / หน้าโครงการ)"},{"style":"sub","text":"เข้าสู่โมดูล OF ➔ ดำเนินการ ➔ บันทึกความคืบหน้าของโครงการ ➔ กดปุ่ม ส่งมอบงานโครงการ (Progress Submit)"},{"style":"sub","text":"วันที่: ระบุวันที่ของเอกสารส่งมอบงาน"},{"style":"sub","text":"โครงการ: กดค้นหาและเลือกรหัสโครงการที่ต้องการเรียกเก็บเงิน (ระบบจะดึงข้อมูลลูกหนี้/เจ้าของโครงการมาแสดงให้อัตโนมัติ)"},{"style":"sub","text":"ประเภทรับวางบิล: เลือกเป็น Progress Payment"},{"style":"sub","text":"รายละเอียดเพิ่มเติม: ระบุงวดงาน หรือรายละเอียดการส่งมอบ"},{"style":"sub","text":"ไปที่แท็บ Job: ระบุยอดเงินที่ต้องการเบิกจริงตามใบตรวจรับงานที่ผู้ว่าจ้าง Certify แล้วลงในช่อง Amount"},{"style":"sub","text":"ตรวจสอบความถูกต้องแล้วกดปุ่ม Save (บันทึก) เพื่อให้ระบบสร้างแบบฟอร์ม ใบขอเบิกเงิน (Progress Submit Form)"},{"style":"num","text":"การตรวจสอบและรับรองผลงาน (Submit Certificate)"},{"style":"sub","text":"ในหน้าต่าง เอกสารส่งมอบงานโครงการ (Progress Submit) ให้กดค้นหาเอกสารรายการที่ได้บันทึกไว้"},{"style":"sub","text":"กดปุ่ม Submit Certificate (หรือยืนยันส่งตรวจสอบผลงาน) ระบบจะ Auto ยอดเงินในช่อง Amount Certification ให้เท่ากับยอดเงินขอเบิก (หากยอดเงินที่ได้รับอนุมัติจริงตรงตามที่ Certify ให้ยืนยันยอดดังกล่าว)"},{"style":"sub","text":"ระบุวันที่ผู้ว่าจ้างอนุมัติรับรองผลงานในช่อง Certification Date"},{"style":"sub","text":"ตรวจสอบข้อมูลแล้วกด Save (บันทึก) เพื่อเปลี่ยนสถานะเอกสารเป็น Certificated (รับรองผลงานเรียบร้อยแล้ว)"},{"style":"num","text":"การเปิดใบแจ้งหนี้และตั้งลูกหนี้ (แผนกบัญชีและการเงิน)"},{"style":"bullet","text":"[เจ้าหน้าที่บัญชีลูกหนี้ AR]"},{"style":"sub","text":"เข้าสู่โมดูล AR ➔ บันทึกรายการ ➔ บันทึกใบแจ้งหนี้ (Create Invoice) ➔ จากสัญญาในโครงการ (Progress Payment)"},{"style":"sub","text":"กดปุ่มค้นหาที่ช่อง เลขที่ใบรับรองอ้างอิง (Ref. Certification No.) เลือกเอกสาร Submit-Certification ที่ฝ่ายวิศวกรรมทำรายการรับรองผลงานมาจากโมดูล OF"},{"style":"sub","text":"ตรวจสอบยอดเงิน วันที่ และรายละเอียดภาษีให้ถูกต้อง จากนั้นกด Save (บันทึก) เพื่อสร้างใบแจ้งหนี้ (Invoice) และบันทึกตั้งหนี้ลูกหนี้ในระบบ"},{"style":"num","text":"การเชื่อมโยงและประมวลผลข้อมูล (Impact on PM & FN Modules)"},{"style":"sub","text":"เมื่อดำเนินกระบวนการตั้งแต่ OF (Progress Submit ➔ Submit Cert.) ถึง AR (Create Invoice) เรียบร้อยแล้ว ยอดรายรับจะวิ่งไปประมวลผลในระบบให้อัตโนมัติ ดังนี้:"},{"style":"sub","text":"โมดูล PM: แสดงยอดผลงานจริงที่ทำได้ (Actual Progress / Progress Submit) และยอดการตั้งหนี้ (Invoiced) ในหน้า Project Status Overview และกราฟ S-Curve"},{"style":"sub","text":"โมดูล FN: ดึงยอดไปแสดงใน Dashboard ประมาณการรายได้ส่งผลงานวางอินวอยซ์ถึงเก็บเงินได้จริง (Dashboard 5 & 6) และรายงาน Cash Flow เพื่อวิเคราะห์สภาพคล่องทางการเงิน"}],"extra":["PM","AR"],"attachments":[{"label":"SOP-18 · Progress Submit","url":"https://drive.google.com/file/d/10s2ZJ-FvflMqOHT54KINB_caVoPxL5Dv/view"}]},{"no":25,"module":"IC","display_no":"IC-4","sort_order":4,"title_th":"กรณีการควบคุมสต็อกระหว่างโครงการ/บริษัทในเครือ","title_en":"Inter-Company Stock Control - No Credit Line","problem":"ในกรณีที่โครงการใช้ถังน้ำมันร่วมกัน มีความจำเป็นต้องกำหนดสัดส่วนการเบิกเข้า–เบิกออก ของแต่ละโครงการให้ชัดเจนตามปริมาณไน PO เพื่อให้สามารถควบคุมต้นทุน ตรวจสอบการใช้น้ำมัน และจัดทำรายงานได้อย่างถูกต้อง เดิมบริษัทถือว่าการจัดส่งน้ำมันไปยังจุดใด เป็นการโอนน้ำมันให้แก่โครงการนั้นทันที ซึ่งแนวปฏิบัติดังกล่าวไม่สอดคล้องกับหลักการบริหารคลังและระบบการควบคุมภายในของ ERP","ref":"ERP Manual 14.3.68 – บทที่ 5 (IC)","note":null,"date_added":"1 เมษายน 2569","steps":[{"style":"num","text":"การซื้อขายวัสดุกรณีใช้คลังจัดเก็บร่วมกัน (Inter-Company Shared Storage)"},{"style":"bullet","text":"(ใช้สำหรับไซต์งานที่หลายบริษัทในเครือเบิกใช้วัสดุจากคลังจัดเก็บเดียวกัน เช่น ถังน้ำมันกลางที่รถของแต่ละบริษัทวิ่งเข้ามาเติม โดยบริษัท B เป็นผู้มีวงเงินสินเชื่อกับร้านค้า)"},{"style":"sub","text":"ขั้นตอนที่ 1.1: การเปิด PR และการตรวจสอบวงเงินสินเชื่อ"},{"style":"sub2","text":"[ผู้ขอ / แอดมินบริษัท A] เปิดใบขอซื้อ (PR) ระบุปริมาณวัสดุที่ต้องใช้"},{"style":"sub2","text":"[แผนกจัดซื้อ] ตรวจสอบว่าบริษัท A มีวงเงินสินเชื่อกับร้านค้าหรือไม่"},{"style":"bullet","text":"— กรณีมีวงเงิน: เปิดใบสั่งซื้อ (PO) ซื้อตรงจากร้านค้าตามปกติ ไม่เข้าข่ายการซื้อขายระหว่างบริษัท"},{"style":"bullet","text":"— กรณีไม่มีวงเงิน: ให้ดำเนินการเปิด PO สองฉบับ"},{"style":"sub2","text":"[แผนกจัดซื้อ] เปิดใบสั่งซื้อ PO ฉบับที่ 1 (บริษัท A ➔ ซื้อจาก บริษัท B)"},{"style":"sub2","text":"[แผนกจัดซื้อ] เปิดใบสั่งซื้อ PO ฉบับที่ 2 (บริษัท B ➔ ร้านค้าภายนอก)"},{"style":"sub","text":"ขั้นตอนที่ 1.2: การรับวัสดุเข้าคลังกลางและการบันทึกรับ–จ่ายหน้างานจริง (Real-time Transaction)"},{"style":"sub2","text":"เมื่อร้านค้าภายนอกส่งมอบวัสดุเข้าคลังจัดเก็บกลางที่หน้างาน [แอดมินบริษัท B] บันทึกรับของ (PO Receive) อ้างอิง PO ฉบับที่ 2 เพื่อรับวัสดุเข้าสต๊อกของบริษัท B ตามราคาทุนจริงที่ซื้อ"},{"style":"sub2","text":"[แผนกบัญชี บริษัท B] ดึงเอกสารรับของจาก PO ฉบับที่ 2 มาบันทึกตั้งหนี้ (APV) เพื่อเตรียมชำระเงินให้แก่ \"ร้านค้า\""},{"style":"sub2","text":"เมื่อบริษัท A เบิกใช้วัสดุจากคลังกลาง (กรณีน้ำมัน คือเมื่อรถของบริษัท A วิ่งมาเติมน้ำมันจากถังกลาง) ➔ [แอดมินบริษัท B] ทำรายการเบิกจ่าย (IC Issue) ➔ ระบุ Area Code เป็นประเภท \"คิดเงิน\" เพื่อตัดปริมาณวัสดุออกจากคลังของบริษัท B"},{"style":"sub2","text":"[ฝั่งบริษัท A (ผู้ซื้อ)]: [แอดมินบริษัท A] บันทึกรับของ (PO Receive) อ้างอิง PO ฉบับที่ 1 ทันที ตามปริมาณที่เบิกใช้จริง (กรณีน้ำมัน คือตามปริมาณที่จ่ายจริงจากหัวจ่าย) เพื่อลงเป็นต้นทุนโครงการของบริษัท A"},{"style":"sub","text":"ขั้นตอนที่ 1.3: กระบวนการทางบัญชีและการปิดยอด (Accounting Closure)"},{"style":"sub2","text":"[แผนกบัญชี บริษัท B (ผู้ขาย)] ดึงยอดการเบิกจ่ายจริงทั้งหมดผ่าน Module AR ➔ เลือกประเภทรายการเป็น \"Trading\" (ซื้อมาขายไป) ➔ ออกใบกำกับภาษีขายโดยบวกกำไรเพิ่ม 1% เรียกเก็บกับบริษัท A"},{"style":"sub2","text":"[แผนกบัญชี บริษัท A (ผู้ซื้อ)] ดึงเอกสารรับของจาก PO ฉบับที่ 1 มาบันทึกตั้งหนี้ (APV) ตามรอบบัญชี เพื่อรอทำจ่ายชำระเงินคืนให้แก่บริษัท B"},{"style":"num","text":"การซื้อขายวัสดุกรณีหน้างานคนละตำแหน่ง (Inter-Company Separate Locations)"},{"style":"bullet","text":"(ใช้สำหรับกรณีที่บริษัท A ต้องการใช้วัสดุที่หน้างานของตนเอง แต่ไม่มีวงเงินสินเชื่อกับร้านค้า จึงให้บริษัท B ในเครือเป็นผู้ซื้อจากร้านค้าแล้วขายต่อให้บริษัท A โดยร้านค้าส่งสินค้าตรงถึงหน้างานของบริษัท A)"},{"style":"sub","text":"ขั้นตอนที่ 2.1: การเปิด PR และการเปิด PO (เปิด PO 2 ฉบับ)"},{"style":"sub2","text":"[ผู้ขอ / แอดมินบริษัท A] เปิดใบขอซื้อ (PR) โดยระบุปริมาณตามที่ต้องใช้งานจริง"},{"style":"sub2","text":"[แผนกจัดซื้อ] ตรวจสอบว่าบริษัท A มีวงเงินสินเชื่อกับร้านค้าหรือไม่"},{"style":"bullet","text":"— กรณีมีวงเงิน: เปิดใบสั่งซื้อ (PO) ซื้อตรงจากร้านค้าตามปกติ ไม่เข้าข่ายการซื้อขายระหว่างบริษัท"},{"style":"bullet","text":"— กรณีไม่มีวงเงิน: ให้ดำเนินการเปิด PO สองฉบับ"},{"style":"sub2","text":"[แผนกจัดซื้อ] เปิดใบสั่งซื้อ (PO) ฉบับที่ 1 ในนาม บริษัท A โดยระบุผู้ขายเป็น \"บริษัท B\""},{"style":"sub2","text":"[แผนกจัดซื้อ] เปิดใบสั่งซื้อ (PO) ฉบับที่ 2 ในนาม บริษัท B โดยระบุผู้ขายเป็น \"ร้านค้าภายนอก\" (อ้างอิงราคาตามที่ตกลงกัน)"},{"style":"sub","text":"ขั้นตอนที่ 2.2: การรับของและการบันทึกคู่ขนาน (Parallel PO Receive)"},{"style":"sub2","text":"เมื่อร้านค้าส่งสินค้าถึงหน้างานของบริษัท A [แอดมินบริษัท A] เซ็นรับใบส่งสินค้าและบันทึกรับของเข้าคลัง (PO Receive) อ้างอิง PO ฉบับที่ 1 ทันที เพื่อลงเป็นต้นทุนโครงการของบริษัท A"},{"style":"sub2","text":"[แอดมินบริษัท A] ถ่ายรูปใบส่งสินค้าที่เซ็นรับ ส่งแชร์เข้ากลุ่ม Line / Email แจ้งบริษัท B ให้บันทึกรับของในทันที"},{"style":"sub2","text":"[แอดมินบริษัท B] บันทึกรับของเข้าคลัง (PO Receive) อ้างอิง PO ฉบับที่ 2 ตามปริมาณเดียวกัน"},{"style":"sub","text":"ขั้นตอนที่ 2.3: กระบวนการทางบัญชีและการปิดยอด (Accounting Closure)"},{"style":"sub2","text":"[แผนกบัญชี บริษัท B] ดึงเอกสารรับของจาก PO ฉบับที่ 2 มาบันทึกตั้งหนี้ (APV) ให้แก่ \"ร้านค้าภายนอก\""},{"style":"sub2","text":"[แผนกบัญชี บริษัท A] ดึงเอกสารรับของจาก PO ฉบับที่ 1 มาบันทึกตั้งหนี้ (APV) เพื่อรอทำจ่ายชำระเงินคืนให้แก่บริษัท B"},{"style":"sub2","text":"[แอดมินบริษัท B] บันทึกเบิกจ่าย (IC Issue) เต็มจำนวน โดยระบุ Area Code เป็นประเภท \"คิดเงิน\" เพื่อตัดยอดสต๊อกวัสดุออกจากคลังของบริษัท B"},{"style":"sub2","text":"[แผนกบัญชี บริษัท B (ผู้ขาย)] ดึงข้อมูลการเบิกจ่าย (IC Issue) ผ่าน Module AR ➔ เลือกประเภทรายการเป็น \"Trading\" (ซื้อมาขายไป) ➔ ออกใบกำกับภาษีขายโดยบวกกำไรเพิ่ม 1% เรียกเก็บกับบริษัท A"},{"style":"num","text":"การซื้อขายวัสดุกรณีซื้อผ่านโครงการอื่นในบริษัทเดียวกัน (Inter-Project Purchase)"},{"style":"bullet","text":"(ใช้สำหรับกรณีที่โครงการ A ต้องการใช้วัสดุ แต่ไม่มีวงเงินคงเหลือของโครงการ จึงเปิดใบสั่งซื้อในนามโครงการ B ที่มีวงเงิน แล้วโอนสต๊อกและต้นทุนกลับเข้าโครงการ A)"},{"style":"sub","text":"ขั้นตอนที่ 3.1: การเปิด PR และการตรวจสอบวงเงินโครงการ"},{"style":"sub2","text":"[ผู้ขอ / แอดมินโครงการ A] เปิดใบขอซื้อ (PR) โดยระบุปริมาณตามที่ต้องใช้งานจริง"},{"style":"sub2","text":"[แผนกจัดซื้อ] ตรวจสอบว่าโครงการ A มีวงเงินคงเหลือหรือไม่"},{"style":"bullet","text":"— กรณีมีวงเงิน: เปิดใบสั่งซื้อ (PO) ในนามโครงการ A ตามปกติ ไม่เข้าข่ายการซื้อข้ามโครงการ"},{"style":"bullet","text":"— กรณีไม่มีวงเงิน: ดำเนินการตามขั้นตอนที่ 3.2"},{"style":"sub2","text":"[แผนกจัดซื้อ] เปิดใบสั่งซื้อ (PO) ในนามโครงการ B โดยระบุผู้ขายเป็น \"ร้านค้าภายนอก\" ตามรายการที่โครงการ A ขอ"},{"style":"sub","text":"ขั้นตอนที่ 3.2: การรับของและการตั้งหนี้"},{"style":"sub2","text":"เมื่อร้านค้าภายนอกส่งมอบสินค้าถึงหน้างาน [แอดมินโครงการ B] บันทึกรับของเข้าคลัง (PO Receive) เพื่อรับวัสดุเข้าสต๊อกของโครงการ B ตามราคาทุนจริงที่ซื้อ"},{"style":"sub2","text":"[แผนกบัญชี โครงการ B] ดึงเอกสารรับของมาบันทึกตั้งหนี้ (APV) เพื่อเสนออนุมัติจ่ายชำระเงินให้แก่ \"ร้านค้าภายนอก\""},{"style":"sub","text":"ขั้นตอนที่ 3.3: การโอนสต๊อกและต้นทุนเข้าโครงการผู้ขอ"},{"style":"sub2","text":"[แอดมินโครงการ B] บันทึกโอนออก (IC Transfer) ระบุปลายทางเป็นคลังของโครงการ A ระบุ Area Code \"เบิกใช้งาน\""},{"style":"sub2","text":"[แอดมินโครงการ A] บันทึกรับเข้า (IC Receive) ที่คลังปลายทาง เพื่อนำวัสดุเข้าสต๊อกของโครงการ A"},{"style":"sub2","text":"[แผนกบัญชี โครงการ A] ต้นทุนวัสดุย้ายจากโครงการ B เข้าโครงการ A ตามรายการโอน และคืนต้นทุนให้กับโครงการ B"}],"extra":["PO","AR"],"attachments":[{"label":"SOP-07a - Inter-Company Purchase (Shared Storage)","url":"https://drive.google.com/file/d/1pAcAnyxtaoyPaasyiMa-RQJ7lv__3mAk/view?usp=drive_link"},{"label":"SOP-07b - Inter-Company Purchase (Separate Locations)","url":"https://drive.google.com/file/d/1OGlxhQuKEbcIhAjalnwjYYIF-g3xPt-Q/view?usp=drive_link"},{"label":"SOP-07c - Inter-Project Purchase","url":"https://drive.google.com/file/d/1a4-ru_Hqeutarymr23gJOAyMyop4uOYZ/view?usp=drive_link"}]},{"no":26,"module":"AP","display_no":"AP-5","sort_order":5,"title_th":"กรณีมีการจ่ายด่วนที่มียอดเกินจากใบเตรียมจ่ายในระบบ","title_en":"Urgent Payments Exceeding the APP","problem":"มีการจ่ายเงินสดหรือออกตั๋วสัญญาใช้เงินให้แก่ร้านค้าก่อนที่จะมีการตั้งหนี้ (AP) และก่อนที่ระบบจะมีเอกสารอนุมัติจ่าย (APP) ทำให้การชำระเงินไม่สอดคล้องกับข้อเท็จจริงทางบัญชี เกิดยอดค้างชำระผิดปกติ รวมถึงส่งผลกระทบต่อกระบวนการรับสินค้าเข้าโครงการ (PO Receive / IC Receive) และทำให้ข้อมูลสต๊อกคลังสินค้าคลาดเคลื่อนจากความเป็นจริง จึงกำหนดให้การจ่ายเงินทุกประเภทต้องผ่านกระบวนการตั้งหนี้และอนุมัติจ่ายในระบบ Mango ERP อย่างเป็น Real-Time เพื่อควบคุมเงินสด/การออกตั๋วสัญญาใช้เงิน และรักษาความถูกต้องของคลังสินค้า","ref":"ERP Manual 14.3.68 – บทที่ 6 (AP) | บทที่ 4 (PO) | บทที่ 3 (OF)","note":"แผนกบัญชีการเงินสามารถตรวจสอบรายการสั่งซื้อที่รับของแล้วแต่ยังไม่ได้ตั้งหนี้ หรือรายการขอซื้อคงค้าง ได้ผ่านรายงาน P/O Pending ในโมดูล IC","date_added":"1 เมษายน 2569","steps":[{"style":"num","text":"ข้อกำหนดและนโยบายหลัก (Core Policy Rules)"},{"style":"sub","text":"ห้ามจ่ายเงินก่อนมียอดอนุมัติจ่าย (No Payment without Approved Pre-payment): การจ่ายเงินทุกกรณี (เงินสด, เช็ค, ตั๋วสัญญาใช้เงิน หรือช่องทางอื่น ๆ) ต้องมีเอกสารชุดอนุมัติจ่าย (APP / Pre-payment) ในระบบรองรับก่อนเสมอ ห้ามโอนเงินหรือตัดเช็คออกจากระบบล่วงหน้าโดยเด็ดขาด"},{"style":"sub","text":"การสั่งซื้อวัสดุต้องมี PO รองรับเสมอ: โครงการต้องมีใบสั่งซื้อ (PO) ที่ผ่านการอนุมัติล่วงหน้า เพื่อใช้สำหรับรับของเข้าคลัง (PO Receive / IC Receive) ให้ถูกต้องตามปริมาณจริง"},{"style":"sub","text":"การบันทึกข้อมูลแบบ Real-Time: ผู้เกี่ยวข้องต้องเร่งบันทึกเอกสารตามลำดับขั้นตอนในระบบทันทีเพื่อไม่ให้กระทบต่อการตั้งหนี้และการอนุมัติจ่ายของแผนกบัญชีการเงิน"},{"style":"num","text":"ขั้นตอนการปฏิบัติงานในระบบ Mango ERP (System Workflow)"},{"style":"bullet","text":"ลำดับที่ 1: สายงานจัดซื้อวัสดุ/สินค้า (Materials & Goods Process)"},{"style":"sub","text":"ใบขอซื้อ (PR): โครงการเปิด PR และส่งอนุมัติผ่านระบบ"},{"style":"sub","text":"ใบสั่งซื้อ (PO): ฝ่ายจัดซื้อเปิด PO อ้างอิงจาก PR และส่งอนุมัติตามสายงาน"},{"style":"sub","text":"การรับสินค้าเข้าสต๊อก (PO Receive / IC Receive): เมื่อสินค้ามาส่ง โครงการต้องบันทึกรับของผ่านโมดูล IC หรือ PO ทันที เพื่อให้ยอดสินค้าเข้าคลังอย่างถูกต้อง"},{"style":"sub","text":"การตั้งหนี้ (APV): แผนกบัญชีดึงรายการรับสินค้า (PO Receive) มาบันทึกตั้งสำคัญตั้งหนี้ (APV)"},{"style":"sub","text":"การอนุมัติจ่าย (APP): แผนกการเงินตั้งชุดอนุมัติจ่าย (APP / Pre-payment) เสนอผู้บริหารอนุมัติ"},{"style":"sub","text":"การจ่ายเงิน (PV / Cheque / Promissory Note): ออกเช็ค โอนเงิน หรือบันทึกการจ่ายตั๋วสัญญาใช้เงินผ่านชุดอนุมัติจ่ายในระบบ"},{"style":"bullet","text":"ลำดับที่ 2: สายงานค่าใช้จ่ายทั่วไป/บริการที่ไม่มี PO/WO (Office & Other Expenses Process)"},{"style":"sub","text":"ใบเบิกเงิน (OF): ผู้ขอเบิกจัดทำเอกสารเบิกจ่ายในโมดูล OF และส่งอนุมัติ"},{"style":"sub","text":"การตั้งหนี้ (APO): แผนกบัญชีดึงเอกสาร OF มาบันทึกตั้งใบสำคัญตั้งหนี้อื่นๆ (APO)"},{"style":"sub","text":"การอนุมัติจ่าย (APP): ตั้งชุดอนุมัติจ่าย (APP / Pre-payment) เสนออนุมัติ"},{"style":"sub","text":"การทำจ่าย (PV): ดำเนินการชำระเงินตามชุดอนุมัติจ่าย"},{"style":"num","text":"แนวทางปฏิบัติกรณีฉุกเฉินและการย้อนหลัง (Emergency Procedure)"},{"style":"sub","text":"ผู้ประสานงาน/โครงการ ต้องแจ้งผู้เกี่ยวข้องให้ดำเนินการเปิดเอกสารตั้งต้น (PR / PO / WO / OF) และตั้งหนี้ (APV / APO) ในระบบให้เสร็จสิ้น ภายในวันทำการถัดไปโดยเร็วที่สุด"},{"style":"sub","text":"การระบุหมายเหตุ (Remark): ในขั้นตอนการคีย์เอกสารย้อนหลัง ผู้จัดทำต้องระบุในช่อง Remark / Comment ชัดเจนว่าเป็น \"รายการตั้งเบิกย้อนหลัง เนื่องจากจ่ายเงินฉุกเฉินเมื่อวันที่ [ระบุวันที่]\" เพื่อเน้นย้ำและป้องกันไม่ให้แผนกบัญชี/การเงิน ทำรายการจ่ายเงินซ้ำซ้อน (Double Payment)"},{"style":"bullet","text":"และรายงาน Pending Purchase Requisition ในโมดูล OF"},{"style":"bullet","text":"เพื่อกระตุ้นให้หน้างานเร่งส่งเอกสารได้ทันท่วงทีครับ"}],"extra":[],"attachments":[{"label":"SOP-22 · Urgent Payment Control","url":"https://drive.google.com/file/d/1_iHbdNK4GtmtlivLPAmybnNbh8oOzYqT/view"}]},{"no":27,"module":"SE","display_no":"SE-3","sort_order":3,"title_th":"กรณีการตั้งชื่อโครงการในระบบ ERP","title_en":"Project Naming Convention","problem":"เดิมบริษัทมีการตั้งชื่อโครงการในลักษณะห้อยท้าย เช่น \"บางเตย ตอน 1 – ศูนย์ซ่อมสาย 5\" ซึ่งระบบจะตีความว่าเป็นคนละโครงการกับโครงการหลัก ส่งผลให้ค่าใช้จ่ายไม่ถูกบันทึกเข้าที่โครงการหลัก ข้อมูลใน Module: PO / WO / OF ไม่ถูกต้อง และรายงานทางบัญชีและการเงินคลาดเคลื่อน","ref":"ERP Manual 14.3.68 – บทที่ 1 (SE) | บทที่ 2 (BD)","note":null,"date_added":"1 เมษายน 2569","steps":[{"style":"num","text":"ให้ทุกโครงการเลือกชื่อโครงการหลักเท่านั้นในทุก Module ของระบบ ERP ห้ามสร้างหรือเลือกชื่อโครงการในลักษณะห้อยท้าย เช่น \"บางเตย ตอน 1 – ศูนย์ซ่อมสาย 5\" เนื่องจากระบบ ERP จะตีความว่าเป็นคนละโครงการ ส่งผลให้เกิด Budget Misallocation ทันที"},{"style":"num","text":"หากต้องการระบุประเภทค่าใช้จ่าย เช่น งานซ่อมบำรุง ให้ใช้ Cost Code / หมวดค่าใช้จ่ายในระบบ ERP สำหรับการรายงานและการแสดง Report เท่านั้น ห้ามแก้ไขชื่อโครงการเพื่อสื่อความหมายของค่าใช้จ่ายโดยเด็ดขาด"},{"style":"num","text":"ผู้ดูแลระบบและผู้ที่ได้รับมอบหมายสิทธิ์ในการแก้ไขข้อมูลโครงการ ให้งดการสร้างโครงการหรือ Loop อนุมัติใดๆ ที่ขัดหรือแย้งกับหลักการนี้"}],"extra":[],"attachments":[{"label":"SOP-26 · Project Naming Convention","url":"https://drive.google.com/file/d/1n8ISdRs36dr0gvoBo6vXWdvzr6wz6sS5/view"}]},{"no":28,"module":"FA","display_no":"FA-3","sort_order":3,"title_th":"กรณีการ Overhaul เครื่องจักรและการเพิ่มมูลค่าทรัพย์สิน","title_en":"Machine Overhaul and Asset Value Enhancement","problem":"เพื่อกำหนดหลักเกณฑ์ที่ชัดเจนในการพิจารณาบันทึกรายการซ่อมบำรุงใหญ่ (Overhaul) ว่าเป็น \"ค่าใช้จ่ายประจำงวด (Expense)\" หรือ \"การเพิ่มมูลค่าทรัพย์สิน (Capitalization)\" รวมถึงกำหนดมาตรฐานการสร้างรหัสทรัพย์สิน (Asset Code) การควบคุมสิทธิ์ข้อมูล และการระบุตำแหน่งสถานที่ตั้ง (Location) ในระบบ Mango ERP (Module FA) ให้สอดคล้องกันทั้งองค์กร","ref":"ERP Manual 14.3.68 – บทที่ 9 (FA)","note":null,"date_added":"1 เมษายน 2569","steps":[{"style":"num","text":"หลักเกณฑ์การพิจารณาทางบัญชี (Capitalization vs. Expense Policy)"},{"style":"sub","text":"ดุลพินิจและการอนุมัติ: การตัดสินใจว่าจะบันทึกเป็นค่าใช้จ่าย หรือ นำไปบันทึกเพิ่มมูลค่าทรัพย์สิน ให้ถือเป็น ดุลพินิจและอำนาจการพิจารณาของแผนกบัญชีและฝ่ายบริหาร เท่านั้น"},{"style":"sub","text":"เกณฑ์มูลค่าขั้นต่ำ (Threshold): รายการที่จะพิจารณา Overhaul เป็นการเพิ่มมูลค่าทรัพย์สิน ต้องมีมูลค่าการซ่อมบำรุง มากกว่า [xxx] บาท/ล้านบาท ขึ้นไป (หากมูลค่าต่ำกว่าเกณฑ์ ให้บันทึกเป็นค่าใช้จ่ายซ่อมแซมประจำงวดในหมวด OF/AP)"},{"style":"sub","text":"เกณฑ์เพิ่มประสิทธิภาพ/อายุการใช้งาน: การ Overhaul นั้นต้องส่งผลให้อายุการใช้งานของเครื่องจักรยาวนานขึ้น หรือเพิ่มประสิทธิภาพการทำงานอย่างมีนัยสำคัญ"},{"style":"num","text":"การควบคุมสิทธิ์การแก้ไขข้อมูล (Security & Permission Control)"},{"style":"sub","text":"สิทธิ์การแก้ไข Serial No.: จำกัดสิทธิ์ในการแก้ไข/ปรับปรุงข้อมูลเลขซีเรียล (Serial No.) ของทรัพย์สิน เฉพาะพนักงานแผนกบัญชีทรัพย์สินที่ได้รับมอบหมายอย่างเป็นทางการเท่านั้น (กำหนดสิทธิ์ผ่าน Module SE / User Management) เพื่อป้องกันการแก้ไขข้อมูลโดยไม่ได้รับอนุญาต"},{"style":"num","text":"การตั้งรหัสทรัพย์สินและการลงทะเบียน (Asset Code Naming Convention)"},{"style":"sub","text":"รูปแบบรหัส (Asset Code Structure): ให้สร้างรหัสทรัพย์สินเฉพาะสำหรับการ Overhaul โดย ต้องอ้างอิงและต่อท้ายรหัสเครื่องจักรคันเดิมเสมอ เช่น ใช้เครื่องหมาย - หรือ / ต่อท้าย"},{"style":"bullet","text":"ตัวอย่าง: เครื่องจักรเดิมรหัส MC-001 เมื่อทำ Overhaul ให้ตั้งรหัสทรัพย์สินใหม่เป็น MC-001-1 หรือ MC-001/O1"},{"style":"sub","text":"วันที่เริ่มบันทึกทรัพย์สิน (Asset Date / Ready for Use): ให้บันทึกเพิ่มทรัพย์สินในระบบ FA ณ วันที่การซ่อมบำรุง Overhaul เสร็จสมบูรณ์ และเครื่องจักรพร้อมกลับมาใช้งานจริงเท่านั้น (ไม่อนุญาตให้ลงบันทึกทรัพย์สินล่วงหน้าขณะยังซ่อมไม่เสร็จ)"},{"style":"sub","text":"ปัจจุบัน บริษัทวิจิตรภัณฑ์ก่อสร้างจํากัด ยังมีทรัพย์สินของบริษัท CVN Development รวมอยู่ด้วย ซึ่งจะตั้งรหัสพิเศษขึ้นมาขึ้นต้นด้วย \"2\" และทำการผูก Account Code แยกจากทรัพย์สินปกติ เพื่อเป็นการแยกกรรมสิทธิ์กันอย่างชัดเจนออกจากทรัพย์สินของวิจิตรภัณฑ์ก่อสร้างที่จะขึ้นต้นรหัสด้วย \"1\" โดยที่ไม่ได้สร้างเพิ่มใน Multi Company เนื่องจาก CVN ยังไม่มีรายได้ที่จะสามารถดูแลรักษาค่าใช้จ่ายเกี่ยวกับเครื่องจักรได้ ทั้งนี้การ Ref. Asset ซ่อมบำรุงทั้งหมดจะทำในรหัสหมายเลข \"2\""},{"style":"num","text":"การเชื่อมโยงประวัติและค่าเสื่อมราคา (Depreciation & History Tracking)"},{"style":"sub","text":"เมื่อบันทึกรับรู้ทรัพย์สิน Overhaul รหัสใหม่เรียบร้อยแล้ว ให้เลือกวิธีคิดค่าเสื่อมราคา (Depreciation Method) ตามอายุการใช้งานที่เพิ่มขึ้นจริงของงาน Overhaul นั้น"},{"style":"sub","text":"ให้ระบุรหัสทรัพย์สินเดิมในช่อง Ref. Code / Description เพื่อผูกประวัติการซ่อมบำรุงและประวัติค่าใช้จ่ายในรายงาน Asset History Report ของ Module FA"},{"style":"sub","text":"ในกรณีที่มีการซ่อมแซมเพิ่มเติม ให้ Ref Asset ที่ทรัพย์สินตัวตั้งต้น"}],"extra":["GL","SE"],"attachments":[{"label":"SOP-12 · Machine Overhaul","url":"https://drive.google.com/file/d/1Wr94EmfPsuslrsOaPsvLOt6mcuGBbtBk/view"}]},{"no":29,"module":"GL","display_no":"GL-2","sort_order":2,"title_th":"ขั้นตอนการปันส่วนค่าใช้จ่ายส่วนกลาง","title_en":"Allocate Expense","problem":"เพื่อกำหนดมาตรฐานในการบันทึกค่าใช้จ่ายส่วนกลาง (เช่น เงินเดือน, ค่าน้ำ, ค่าไฟ, ค่าสำนักงาน) ไว้ที่โครงการหลักก่อน และใช้ระบบบัญชีแยกประเภท (GL) ทำการปันส่วนค่าใช้จ่ายดังกล่าวไปยังโครงการย่อยเป้าหมายในฐานข้อมูลเดียวกัน โดยอิงจากเกณฑ์สัดส่วนเงินที่ผลิตได้ (รายได้) อย่างถูกต้องเป็นระบบ","ref":"ERP Manual 14.3.68 – บทที่ 10 (GL)","note":null,"date_added":"4 สิงหาคม 2569","steps":[{"style":"num","text":"การบันทึกค่าใช้จ่ายตั้งต้นเข้าโครงการหลัก (Module OF)"},{"style":"bullet","text":"[ฝ่ายธุรการ หรือ แผนกบัญชีทั่วไป]"},{"style":"sub","text":"ขั้นตอนปฏิบัติ: ดำเนินการเปิดใบเบิกเงินสดย่อย หรือ ใบเบิกจ่ายอื่น ๆ ตามประเภทค่าใช้จ่าย เช่น ค่าไฟ ค่าน้ำ ค่าสำนักงาน โดยในช่อง \"โครงการ/แผนก\" ให้เลือกโครงการหลักคือ \"สำนักงานชวนา\" เพื่อรวบรวมค่าใช้จ่ายส่วนกลางทั้งหมดไว้ที่นี่ก่อน"},{"style":"num","text":"การตั้งค่าหัวข้อการปันส่วน (Module GL ➔ Setup Allocate Subject)"},{"style":"bullet","text":"[แผนกบัญชี หรือ บัญชีบริหาร]"},{"style":"sub","text":"ขั้นตอนปฏิบัติ: (ทำเพียงครั้งแรกที่มีการตั้งค่า) ไปที่เมนู Module GL ➔ Report ➔ เลือก 14. Allocate (Depreciation/Expense) ➔ Setup ➔ เลือก 14.2.1 Subject กด เพิ่มรายการ และกำหนดข้อมูลดังนี้:"},{"style":"sub","text":"Code / Name: กำหนดรหัสและชื่อการปันส่วน (เช่น ปันส่วนค่าใช้จ่ายสำนักงานชวนา)"},{"style":"sub","text":"DR A/C Cost: เลือกรหัสบัญชีปันส่วนโครงการ (บัญชีค่าใช้จ่ายที่จะวิ่งเข้าโครงการย่อยเป้าหมาย)"},{"style":"sub","text":"CR A/C Contra: เลือกรหัสบัญชีในการหักล้างค่าเดบิต (บัญชีค่าใช้จ่ายที่ต้องการเครดิตออกจากโครงการ \"สำนักงานชวนา\")"},{"style":"sub","text":"กำหนดโครงการรับปันส่วน: ในส่วนของโครงการเป้าหมายปลายทางที่จะรับปันส่วน ให้เพิ่มรหัสโครงการย่อย \"ไลน์ผลิตโครงการ บางเตย-บ้านพร้าว ตอน 1\" และ \"ตอน 2\" เข้าไปในรายการเพื่อเป็นโครงการเป้าหมายในฐานข้อมูลเดียวกัน แล้วกดบันทึก"},{"style":"num","text":"การกำหนดสัดส่วนการปันส่วนตามรายได้ (Module GL ➔ Setup QTY of Use)"},{"style":"bullet","text":"[แผนกบัญชี หรือ บัญชีบริหาร]"},{"style":"sub","text":"ขั้นตอนปฏิบัติ: (ดำเนินการเป็นประจำทุกเดือนเพื่ออัปเดตสัดส่วนตามยอดเงินที่ผลิตได้จริง)"},{"style":"sub","text":"ไปที่เมนู Module GL ➔ Report ➔ เลือก 14. Allocate (Depreciation/Expense) ➔ Setup ➔ เลือก 14.2.2 QTY of Use"},{"style":"sub","text":"ดึงหัวข้อการปันส่วนที่สร้างไว้ในข้อ 2 ขึ้นมา พร้อมระบุวันที่/เดือนที่ต้องการคำนวณ"},{"style":"sub","text":"ในคอลัมน์สุดท้ายของแต่ละโครงการย่อย ให้ระบุสัดส่วนการปันส่วนที่คำนวณได้จริงในเดือนนั้นๆ (เช่น คำนวณจากสัดส่วนรหัสบัญชีรายได้ที่แต่ละโครงการย่อยผลิตเงินได้จริง)"},{"style":"bullet","text":"กดบันทึกข้อมูล"},{"style":"num","text":"การสร้างสมุดรายวันปันส่วนค่าใช้จ่ายอัตโนมัติ (Module GL ➔ Journal Voucher)"},{"style":"bullet","text":"[แผนกบัญชีทั่วไป]"},{"style":"sub","text":"ขั้นตอนปฏิบัติ: เข้าเมนู Module GL ➔ บันทึกสมุดรายวัน (Journal Voucher) ➔ สร้างใบสำคัญ (Create GL)"},{"style":"sub","text":"ระบุรายละเอียดหัวเอกสารให้ครบถ้วน"},{"style":"sub","text":"กดปุ่มเมนูด้านซ้ายเพื่อดึงข้อมูลอัตโนมัติ และเลือกฟังก์ชัน \"Allocate Expense\""},{"style":"sub","text":"ระบบจะดึงยอดค่าใช้จ่ายจากโครงการ \"สำนักงานชวนา\" มาทำรายการเครดิตออก (CR) และ>กระจายเดบิตเข้า (DR) โครงการย่อยปลายทางทั้ง 2 โครงการตามสัดส่วนที่ระบุในหน้า QTY of Use ให้อัตโนมัติ"},{"style":"sub","text":"ตรวจสอบความถูกต้องของตัวเลขเดบิต/เครดิต บันทึกเอกสาร (Save) และส่งอนุมัติ"}],"extra":["AP","OF"],"attachments":[{"label":"SOP-24 · Allocate Expense","url":"https://drive.google.com/file/d/1yvCH_6onJ_cu74jfAzORHS7ObHdgadkZ/view"}]},{"no":30,"module":"IC","display_no":"IC-5","sort_order":5,"title_th":"กรณีการเบิกจ่ายวัสดุให้แก่ผู้รับเหมาและการหักผลงาน","title_en":"Raw Material Issuance to Subcontractors","problem":"เดิมบริษัทมีการจ่ายวัสดุต่างๆ เช่นเหล็ก ให้แก่ผู้รับเหมาโดยไม่ได้บันทึกผ่านระบบในทันที และจะบันทึกข้อมูลย้อนหลังภายหลังเมื่อผู้รับเหมาแจ้งยอดการใช้งานแล้วเท่านั้น ส่งผลให้ไม่สามารถตรวจสอบปริมาณวัสดุคงเหลือได้แบบ real-time จึงก่อให้เกิดความเสี่ยงต่อการสูญหายหรือรั่วไหลของวัสดุ","ref":"ERP Manual 14.3.68 – บทที่ 5 (IC)","note":"ไม่ทำการ Compound ขั้นตอนโดยการให้ผู้รับเหมานำส่วนที่เหลือจากการใช้งานมาคืนเพื่อทำรายการทีเดียว ในกรณีที่ผู้รับเหมานำวัสดุไปใช้งานแล้วและมีวัสดุคงเหลือจากการใช้งาน ให้รับวัสดุกลับเข้าคลังผ่านหมวด Other / Return ในระบบทันที","date_added":"1 เมษายน 2569","steps":[{"style":"num","text":"การบันทึกรับรู้การจ่ายวัสดุออกจากคลังทันที (Real-time IC Recording)"},{"style":"sub","text":"[แอดมินประจำโครงการ] ➔ เมื่อมีการจ่ายวัสดุออกจากคลังสินค้าหน้างานจริง (เช่น เหล็ก, ปูน) จะต้องทำการบันทึกรายการจ่ายออกผ่านระบบ Module IC ทันทีตามเวลาที่เกิดขึ้นจริง เพื่อให้ระบบบันทึกยอดสต๊อกคงเหลือได้ถูกต้องแบบ Real-time และห้ามสะสมเอกสารเพื่อบันทึกย้อนหลังเกิน 1 วันทำการอย่างเด็ดขาด"},{"style":"sub","text":"[ผู้ขอเบิก / วิศวกรโครงการ / โฟร์แมนหน้างาน] ➔ ดำเนินการจัดทำเอกสารขอเบิกวัสดุในระบบผ่านเมนู Module IC ➔ Transaction ➔ Document IC Issue ➔ Entry Document เพื่อจองปริมาณวัสดุในระบบไว้ก่อนจ่ายจริง โดยต้องกำหนดรายละเอียดประเภทวัสดุ จำนวน QTY และเลือกระบุรหัสพื้นที่ใช้งานในช่อง Area Code รวมถึงระบุชื่อผู้รับเหมาและเลขที่เอกสารสัญญาจ้าง (WO) ให้ชัดเจน เพื่อระบุว่าเป็นการเบิกใช้งานปกติ หรือเป็นการเบิกของไปให้ผู้รับเหมาแบบ \"คิดเงิน\" (Charge) หรือ \"ไม่คิดเงิน\" (No Charge)"},{"style":"sub","text":"[แอดมินประจำโครงการ] ➔ บันทึกเอกสารตัดจ่ายสินค้าออกจากคลังจริงในระบบผ่านเมนู Module IC ➔ Transaction ➔ Document IC Issue ➔ Stock Issue โดยกดดึงเอกสารขอเบิก (Entry Document) ที่บันทึกไว้ในข้อ 2 ขึ้นมาตรวจสอบความถูกต้องของรายการและกดยืนยันบันทึก เพื่อให้ยอดสต๊อกในระบบถูกหักออกอย่างเป็นทางการ ซึ่งสถานะสินค้าจะถูกเปลี่ยนเป็นยอดที่เบิกออกไปแล้ว (QTY Out Booked)"},{"style":"sub","text":"[แอดมินประจำโครงการ] ➔ สั่งพิมพ์แบบฟอร์มใบเบิกวัสดุ (IC Issue) จากระบบ และนำเอกสารฉบับจริงส่งให้ผู้รับของฝ่ายผู้รับเหมาลงนามรับสินค้าเพื่อใช้เป็นหลักฐานยืนยันทางกายภาพ ณ คลังสินค้าหน้างาน ถือเป็นการสิ้นสุดกระบวนการจ่ายของหน้าคลัง"},{"style":"num","text":"การหักค่าใช้จ่ายวัสดุออกจากผลงานผู้รับเหมา (Material Deduction & Verification)"},{"style":"sub","text":"[แผนกบัญชีเจ้าหนี้] ➔ เมื่อผู้รับเหมาส่งมอบผลงานงวดงานและมีการทำเรื่องเบิกเงิน (Progress Billing) ในระบบผ่านเมนู Module OF ➔ บันทึกรายการ ➔ บันทึกรับงานของผู้รับเหมา/บันทึกเบิกตามใบสั่งจ้าง ➔ เลือก Progress Payment ระบบจะทำการเชื่อมโยงข้อมูลจากระบบคลังและดึงยอดหักค่าใช้จ่ายวัสดุทั้งหมดที่ระบุเบิกแบบคิดเงิน (Charge) ที่ผูกอยู่กับรหัสผู้รับเหมาและใบสั่งจ้าง (WO) นั้นๆ มาแสดงเพื่อนำมาหักลดจากยอดจ่ายงวดปัจจุบันในช่อง Deduct Material (หักค่าวัสดุ) อัตโนมัติในหน้าต่างรับวางบิล"},{"style":"sub","text":"[ฝ่ายควบคุมต้นทุน / แผนกวิศวกรรมโครงการ และ แผนกบัญชีสำนักงานใหญ่] ➔ ร่วมกันตรวจสอบความถูกต้องของยอดหักค่าวัสดุสุทธิที่แสดงในระบบ โดยทำการเปรียบเทียบกับเงื่อนไขในใบสั่งจ้าง (Work Order - WO) และบันทึกข้อตกลงที่ระบุไว้ในสัญญาจ้างอย่างละเอียด เพื่อตรวจสอบยอดให้ตรงกันก่อนทำการอนุมัติตั้งหนี้ (APV) เพื่อจ่ายเงินงวดถัดไป"},{"style":"num","text":"นโยบายการคิดราคาสินค้าและการเบิกจ่ายกรณีพิเศษ (Pricing & Approval Policy)"},{"style":"sub","text":"[แผนกจัดซื้อ และ แผนกบัญชีบริหาร] ➔ การกำหนดราคาสินค้าที่จะนำมาคิดเงินและหักยอดเงินกับผู้รับเหมา ให้ใช้การคำนวณราคาตามลำดับสินค้าที่รับเข้าคลังจริง (ราคา FIFO) เพื่อความเป็นธรรมและง่ายต่อการติดตามต้นทุน และกำหนดนโยบายให้ทำการ บวกค่าดำเนินการเพิ่มอีก 4% (Handling Fee) ของมูลค่าวัสดุสุทธิ เพื่อครอบคลุมค่าธรรมเนียมและค่าดำเนินการบริหารจัดการของบริษัทในการจัดหาวัสดุ"},{"style":"sub","text":"[ผู้ขอเบิก / วิศวกรโครงการ และ กรรมการผู้จัดการ] ➔ ในกรณีฉุกเฉินหรือกรณีที่มีความจำเป็นต้องจ่ายวัสดุให้แก่ผู้รับเหมาโดยเป็นแบบ \"ไม่คิดเงิน\" (No Charge) ผู้ขอเบิกต้องทำการส่งเอกสารขออนุมัติในระบบผ่านขั้นตอนสายอนุมัติพิเศษรหัส ICM012: อนุมัติเอกสารใบเตรียมเบิก/โอนวัสดุ (เบิกไม่คิดเงิน) เพื่อส่งเสนอขอความเห็นชอบและอนุมัติจากฝ่ายบริหารระดับสูงและกรรมการผู้จัดการก่อน แอดมินโครงการจึงจะสามารถดำเนินการทำ Stock Issue ปล่อยของออกจากสต๊อกได้"}],"extra":["AP","OF","AR"],"attachments":[{"label":"SOP-25 · Material Issuance Subcontractor","url":"https://drive.google.com/file/d/1Hm_6tLaVpSyXr8vwUjObtxRGq4xWgmjn/view"}]},{"no":31,"module":"FA","display_no":"FA-4","sort_order":4,"title_th":"กรณีการซื้อเครื่องจักรและเบิกสินเชื่อระหว่างบริษัทในเครือ","title_en":"Intercompany Vehicle Acquisition","problem":"เนื่องจาก Project Finance อยู่ที่ JV แต่ทะเบียนรถยนต์/ใบกำกับภาษีต้องออกในนามบริษัทแม่ ส่งผลให้ธนาคารไม่สามารถโอนเงินค่าซื้อรถตรงให้แก่ดีลเลอร์ได้ บริษัทแม่จึงต้องสำรองจ่ายเงินสดเพื่อซื้อรถยนต์ไปก่อน และจึงเรียกเก็บค่าเช่าเพื่อ Reimburse ค่าใช้จ่ายจาก JV","ref":"ERP Manual 14.3.68 – บทที่ 9","note":null,"date_added":"27 สิงหาคม 2569","steps":[{"style":"num","text":"ฝั่ง Company A (บริษัทแม่) — ซื้อรถยนต์และขึ้นทะเบียนทรัพย์สิน"},{"style":"sub","text":"[แผนกจัดซื้อ - Company A] บันทึกเปิดใบสั่งซื้อ (PO) ซื้อรถยนต์จากดีลเลอร์ภายนอกในระบบ"},{"style":"sub","text":"[แผนกบัญชี - Company A] บันทึกรับของ (PO Receive) และทำการขึ้นทะเบียนสินทรัพย์ (Asset Registration) ใน Module FA"},{"style":"sub","text":"[แผนกบัญชี - Company A] บันทึกตั้งหนี้ดีลเลอร์ (APV) ในระบบ"},{"style":"sub","text":"[แผนกการเงิน - Company A] บันทึกทำจ่ายเงิน (PV) โดยใช้เงินสดสำรองโอนจ่ายชำระตรงให้แก่ดีลเลอร์รถยนต์ เพื่อปิดบัญชีเจ้าหนี้และนำรถออกมาใช้งาน"},{"style":"num","text":"ฝั่ง Company B (JV) — เบิกเงินกู้จากธนาคารเข้าโครงการ"},{"style":"sub","text":"[แผนกการเงิน - Company B] ยื่นเอกสารเบิกเงินกู้ (Loan Drawdown) กับธนาคาร โดยแนบเอกสาร PO และหลักฐานการจ่ายเงินของ Company A เพื่อแสดงว่ามีกิจกรรมจัดซื้อเพื่อโครงการจริง"},{"style":"sub","text":"[แผนกการเงิน - Company B] เมื่อธนาคารโอนเงินกู้กลับเข้ามาที่บัญชีของ JV ให้ทำการบันทึกรับเงินกู้ยืมใน"},{"style":"num","text":"ขั้นตอนการเรียกเก็บและจ่าย \"ค่าเช่ารายเดือน\" (Monthly Rental Process)"},{"style":"sub","text":"[แผนกบัญชี - Company A (ผู้ให้เช่า)] ทุกสิ้นเดือน บันทึกออกใบแจ้งหนี้/ใบกำกับภาษี \"ค่าเช่ารถยนต์\" ใน Module AR (Service/Rental) ส่งไปเก็บเงินที่ Company B"},{"style":"sub","text":"[แผนกบัญชี - Company B (ผู้เช่า)] บันทึกตั้งหนี้ค่าเช่า (APV) เป็นต้นทุนค่าเช่าของโครงการ JV"},{"style":"sub","text":"[แผนกการเงิน - Company B] บันทึกทำจ่ายเงิน (PV) โอนเงินค่าเช่ารถยนต์รายเดือน จากบัญชีธนาคารของ JV ไปยังบัญชีธนาคารของ Company A"},{"style":"sub","text":"[แผนกการเงิน - Company A] บันทึกรับเงินค่าเช่ารายเดือน (RV) ในระบบฝั่ง Company A เพื่อตัดยอดลูกหนี้การค้าของ Company B ให้เรียบร้อย"}],"extra":["PO","AP","AR"],"attachments":[{"label":"SOP-32 · Intercompany Vehicle Acquisition","url":"https://drive.google.com/file/d/1_aRDNN3KATBVCCcvRZojo2R-O-I-YBV_/view?usp=drive_link"}]},{"no":32,"module":"AP","display_no":"AP-6","sort_order":6,"title_th":"แนวทางการจัดเตรียมเอกสารและการจ่ายเช็ค","title_en":"Payment Document Preparation & Cheque Release","problem":"เดิมเมื่อบริษัทมีการจ่ายเงิน มักนำเช็คเสนอผู้บริหารลงนามโดยเอกสารประกอบยังไม่ครบถ้วน เช่น ไม่ได้แนบใบเตรียมจ่าย (APP) ของงวดก่อนหน้าในกรณีที่แบ่งจ่ายหลายงวด ไม่ได้ Stamp Paid เอกสารที่เกี่ยวข้อง หรือไม่ได้ระบุว่าเงินจากตั๋ว Aval จะนำไปจ่ายให้คู่ค้ารายใด จำนวนกี่รายการ และจำนวนเงินเท่าใด ส่งผลให้ผู้ลงนามไม่สามารถตรวจสอบและ Cross-check รายการจ่ายได้ในขณะลงนาม จึงให้ดำเนินการตามขั้นตอนดังต่อไปนี้","ref":"ERP Manual 14.3.68 – บทที่ 6","note":null,"date_added":"18 กันยายน 2569","steps":[{"style":"num","text":"ทุกครั้งที่มีการจ่ายเงิน ต้องจัดทำใบเตรียมจ่าย (APP) และใบสำคัญจ่าย (PV) ให้เรียบร้อย พร้อมจัดเตรียมเอกสารประกอบการจ่ายให้ครบถ้วนก่อนนำเช็คเสนอผู้บริหารลงนาม โดยเอกสารที่เกี่ยวข้องกับการจ่ายทุกฉบับต้อง Stamp Paid ให้เรียบร้อยก่อนนำเสนอเช็ค"},{"style":"sub","text":"กรณีแบ่งจ่ายบางส่วน (Partial Payment): ใน APP ต้องระบุรายละเอียดให้ชัดเจนว่าเป็นการจ่ายครั้งที่เท่าใด จากจำนวนทั้งหมดกี่ครั้ง จำนวนเงินที่จ่ายในแต่ละครั้ง และเลขที่ PL ที่เกี่ยวข้องในแต่ละครั้ง เพื่อให้สามารถตรวจสอบและติดตามรายการจ่ายได้อย่างครบถ้วน"},{"style":"sub","text":"กรณีจ่ายต่อเนื่องและมี APP มากกว่าหนึ่งชุด: ต้องแนบ APP ที่เกี่ยวข้องทุกฉบับมาพร้อมกับชุดเอกสารตั้งแต่ครั้งที่นำเสนอเช็คให้ผู้บริหารลงนาม"},{"style":"num","text":"กรณีการจ่ายเงินที่เกี่ยวข้องกับตั๋ว Aval"},{"style":"sub","text":"ขั้นตอนการเซ็นสลักหลังตั๋วเพื่อขาย: ก่อนขายตั๋ว ให้แนบเอกสาร 3 ฉบับ ได้แก่ ใบคำขออนุมัติตั๋ว ใบยินยอมขายตั๋ว และใบขายลดตั๋ว Aval"},{"style":"sub","text":"ขั้นตอนการเซ็นเช็คหลังขายตั๋ว Aval แล้ว: เมื่อขายตั๋วและเงินเข้าบัญชีแล้ว ให้แนบใบคำขออนุมัติตั๋ว ใบเงินเข้าบัญชี และเอกสารการจ่ายเช็ค ประกอบกับชุด APP และ PV ตามข้อ 1 เพื่อเสนอผู้บริหารลงนาม"},{"style":"sub","text":"รายละเอียดในใบคำขออนุมัติตั๋ว: ต้องระบุให้ชัดเจนว่าเงินจากตั๋ว Aval จะนำไปจ่ายให้แก่คู่ค้ารายใด จำนวนกี่รายการ และจำนวนเงินเท่าใด เพื่อให้สามารถตรวจสอบรายละเอียดและ Cross-check การนำเงินไปจ่ายได้อย่างชัดเจน"},{"style":"num","text":"การทำ PL และการส่งเอกสารให้ฝ่ายบัญชี - เมื่อเช็คได้รับการลงนามเรียบร้อยแล้ว ให้ดำเนินการ Paid (PL) ในระบบทันที หรือไม่เกิน +1 วันทำการ"},{"style":"sub","text":"บันทึกยืนยันการจ่ายเช็ค: เข้าโมดูล AP เมนู \"บันทึกยืนยันการจ่ายเช็ค\" และค้นหาเอกสารที่ต้องการ Paid (PL) จากนั้นพิจารณาเพียงจุดเดียวว่าได้รับใบเสร็จรับเงิน/ใบกำกับภาษีแล้วหรือยัง"},{"style":"sub","text":"กรณีมีแล้ว ให้ Link ข้อมูลภาษีซื้อ สแกนแนบไฟล์ และบันทึกข้อมูล"},{"style":"bullet","text":"กรณียังไม่มี ให้ Paid (PL) ไปก่อนโดยไม่ต้อง Link ภาษีซื้อและไม่ต้องแนบไฟล์ (ขั้นตอนนี้ข้อมูลยังไม่วิ่งไปหน้า GL)"},{"style":"sub","text":"บันทึกตัดเจ้าหนี้ (Clear AP): เลือกเมนู \"บันทึกตัดเจ้าหนี้\" ค้นหาเอกสารและกด Clear AP ต้องดำเนินการ Clear AP ทุกครั้งหลังจาก Paid (PL) แล้ว ทั้งกรณีที่มีใบกำกับภาษีแล้วและกรณีที่ยังไม่มี (ขั้นตอนนี้ข้อมูลจะถูกส่งไปยัง GL)"},{"style":"sub","text":"กรณีได้รับใบเสร็จรับเงิน/ใบกำกับภาษีย้อนหลัง: ใช้เฉพาะเอกสารที่ Paid (PL) ไปโดยยังไม่ได้ Link ภาษีซื้อตามข้อ 3.1 เมื่อได้รับเอกสารตัวจริงภายหลัง ให้เลือกเมนู \"บันทึกรับใบกำกับภาษีย้อนหลัง\" ค้นหาด้วยเลขที่ใบสำคัญจ่าย (PV) Link ข้อมูลตามลำดับ สแกนแนบไฟล์ และบันทึกข้อมูล จากนั้น Print ใบบันทึกรับใบกำกับภาษีย้อนหลังแนบไว้กับเอกสารที่เกี่ยวข้อง เอกสารที่ Link ภาษีซื้อไว้แล้วตั้งแต่ตอน Paid (PL) ไม่ต้องผ่านขั้นตอนนี้"},{"style":"sub","text":"การส่งเอกสารให้ฝ่ายบัญชี: เมื่อเอกสารครบถ้วนและบันทึกข้อมูลครบทุกขั้นตอนแล้ว ให้จัดส่งเอกสารให้ฝ่ายบัญชีจัดเก็บ โดยถ่ายสำเนาหน้า APP ส่งไปพร้อมกับ PV ฉบับจริง เพื่อให้ฝ่ายบัญชีสามารถตรวจสอบและจัดเก็บเอกสารประกอบรายการจ่ายได้ครบถ้วน"}],"extra":["GL"],"attachments":[{"label":"SOP 33 - Cheque Preparation & Release","url":"https://drive.google.com/file/d/17C0qGHHZepvV9NrMbl19SFpX4zrvedtk/view?usp=drive_link"}]},{"no":33,"module":"FA","display_no":"FA-5","sort_order":5,"title_th":"กรณีเบิกจ่ายและบันทึกประวัติการซ่อมบำรุงเครื่องจักรระหว่างบริษัทในเครือ","title_en":"Maintenance History of Machinery Between Joint Venture and Parent Company","problem":"เดิมการเปิดเอกสาร PR/PO สำหรับการซ่อมบำรุงเครื่องจักร ถูกดำเนินการและบันทึกในฐานข้อมูลของกิจการร่วมค้า (JV) ซึ่งเป็นคนละนิติบุคคลกับบริษัทแม่ ทำให้เกิดปัญหาประวัติการซ่อมบำรุงขาดความต่อเนื่อง และเมื่อสิ้นสุดโครงการ ประวัติของเครื่องจักรจะไม่ถูกรวมไว้ที่เดียว\nวัตถุประสงค์: เพื่อกำหนดมาตรฐานการบันทึกค่าใช้จ่ายการซ่อมบำรุงให้ JV สามารถรับผิดชอบค่าใช้จ่ายตามเงื่อนไขของธนาคารได้ แต่ในขณะเดียวกัน ก็สามารถรวบรวมประวัติการเปลี่ยนอะไหล่และอุปกรณ์ต่างๆ กลับมาบันทึกรวมไว้ที่ทะเบียนทรัพย์สิน (Fixed Asset) ของบริษัทแม่ได้อย่างสมบูรณ์","ref":"ERP Manual 14.3.68 – บทที่ 9","note":"ไม่บันทึกการเติมน้ำมันเป็นประวัติทรัพย์สิน โดยให้สร้าง **Asset Code (Dummy)** แยกสำหรับแต่ละโครงการเพื่อใช้บันทึกการเติมน้ำมันเฉพาะโครงการ และยกเลิกการใช้งานเมื่อโครงการสิ้นสุด","date_added":"4 สิงหาคม 2569","steps":[{"style":"num","text":"ข้อกำหนดและนโยบายหลัก (Core Policy Rules)"},{"style":"bullet","text":"อ้างอิงตามสัญญาระหว่างบริษัทแม่และกิจการร่วมค้า (JV) ให้ยึดหลักการในการตีความทรัพย์สินดังนี้:"},{"style":"sub","text":"กรรมสิทธิ์หลัก: เครื่องจักรเป็นกรรมสิทธิ์ของ \"บริษัท วิจิตรภัณฑ์ก่อสร้าง จำกัด\" หรือ \"ชวนาเอ็นจิเนียร์ริ่ง จำกัด\" เท่านั้น (บริษัทแม่)"},{"style":"sub","text":"กรรมสิทธิ์ส่วนควบ: อะไหล่ หรืออุปกรณ์ใดๆ ที่จัดซื้อและนำมาติดตั้งเข้ากับเครื่องจักร จะตกเป็นกรรมสิทธิ์ของบริษัทแม่ในทันที (ถือว่าทรัพย์สินดังกล่าวไม่เคยเป็นกรรมสิทธิ์ของ JV แม้จะจัดซื้อในนาม JV ก็ตาม)"},{"style":"sub","text":"ความรับผิดชอบค่าใช้จ่าย: กิจการร่วมค้า (JV) เป็นผู้รับผิดชอบเรื่องค่าใช้จ่ายเกี่ยวกับเครื่องจักรทั้งหมดตามสัญญา"},{"style":"num","text":"ขั้นตอนการปฏิบัติงานในระบบ Mango ERP (System Workflow)"},{"style":"bullet","text":"เพื่อให้ประวัติเครื่องจักรเชื่อมโยงกันอย่างถูกต้อง ให้แบ่งการทำงานออกเป็น 2 ส่วน (ทำใน 2 ฐานข้อมูลของบริษัท) ดังนี้:"},{"style":"sub","text":"ส่วนที่ 1: การดำเนินงานในฝั่งกิจการร่วมค้า (JV) – รับผิดชอบค่าใช้จ่าย"},{"style":"bullet","text":"[ฝ่ายจัดซื้อ / แอดมินประจำโครงการ JV / ศูนย์ซ่อมสาย 5]"},{"style":"sub2","text":"การขอซื้อและสั่งซื้อ (PR/PO): ให้ศูนย์ซ่อมเครื่องจักรสาย 5 เปิดใบขอซื้อ (PR) และฝ่ายจัดซื้อเปิดใบสั่งซื้อ (PO) ในระบบ ERP ของฝั่ง JV เพื่อเป็นหลักฐานการสั่งซื้อและรับผิดชอบค่าใช้จ่ายให้กับร้านค้าตามเงื่อนไขของธนาคาร"},{"style":"sub2","text":"การรับเข้าคลัง (IC Receive): เมื่อของมาส่งหน้างาน ให้แอดมินโครงการทำการรับสินค้าเข้าคลังในระบบของ JV ตามปกติ"},{"style":"sub2","text":"การตัดจ่ายออกจากระบบ JV (IC Issue): ให้แอดมินโครงการฝั่ง JV ทำการเบิกของออก (Issue) เพื่อตัดสต๊อก โดยให้ระบุช่อง Area Code เป็น 005 \"ปรับปรุงยอด\" เพื่อให้ทราบวัตถุประสงค์ว่าเป็นการตัดอะไหล่ออกเพื่อส่งมอบกรรมสิทธิ์ให้บริษัทแม่ (ไม่ต้องทำขั้นตอน AR)"},{"style":"sub","text":"ส่วนที่ 2: การดำเนินงานในฝั่งบริษัทแม่ – บันทึกประวัติทรัพย์สิน"},{"style":"bullet","text":"[แอดมินร์ส่วนกลาง และ ส่วนซ่อมสาย 5]"},{"style":"sub2","text":"การนำอะไหล่เข้าระบบบริษัทแม่ (Receive Other): เมื่อฝั่ง JV ตัดของออกแล้ว ให้ศูนย์ซ่อมเครื่องจักรสาย 5 ทำการรับอะไหล่/อุปกรณ์ดังกล่าวเข้าคลังของบริษัทแม่ โดยใช้ฟังก์ชันรับเข้าอื่นๆ (Receive Other) ในโมดูล IC"},{"style":"sub2","text":"การเบิกเข้าเครื่องจักร (Issue to Fixed Asset): ให้ทำการเปิดใบเบิกวัสดุ (IC Issue) ในระบบของบริษัทแม่ โดยระบุการเบิกจ่ายเพื่อนำไปติดตั้งเข้ากับ รหัสเครื่องจักร (Asset Code) คันนั้นๆ โดยตรง"},{"style":"sub2","text":"ผลลัพธ์การบันทึกประวัติ: ข้อมูลอะไหล่และมูลค่าอุปกรณ์ทั้งหมดจะวิ่งไปเก็บเป็นประวัติการซ่อมบำรุง (Maintenance History) ที่โมดูล FA (Fixed Asset) ของบริษัทแม่ ทำให้ประวัติเครื่องจักรครบถ้วน ไม่สูญหายแม้โครงการ JV จะปิดไปแล้ว"}],"extra":["PO","IC","OF"],"attachments":[{"label":"SOP-23 · JV Maintenance History","url":"https://drive.google.com/file/d/1MI3AVcFh-HUOlJs_8v3a3RW6JZ63M2vr/view"}]}],"reports":[{"case_no":1,"scenario_text":"ตรวจสอบประวัติ/ยอด/รายการจ่ายเช็ค","report_path":"AP -> Report -> 5.1.2 (Cheque Register Report)","sort_order":1},{"case_no":2,"scenario_text":"ตรวจสอบยอดค้างจ่ายจาก PO แต่ละโครงการ","report_path":"AP -> Report -> 9.1.1 (Vendor Movement Report)","sort_order":2},{"case_no":3,"scenario_text":"ตรวจสอบยอดหนี้คงค้างในระบบ (ทุกชนิด)","report_path":"AP -> Report -> 10.2.1 (AP Aging Report)","sort_order":3},{"case_no":4,"scenario_text":"ตรวจสอบรายการการตั้งหนี้ (รวม Advance/Ret.)","report_path":"AP -> Report -> 2.3 (Tracking AP Voucher)","sort_order":4},{"case_no":5,"scenario_text":"ตรวจสอบเงิน Advance ร้านค้า/ผู้รับเหมา APV/APS","report_path":"AP -> Report -> 9.4.1 (Summary Advance Report)","sort_order":5},{"case_no":6,"scenario_text":"ตรวจสอบเงินสดย่อย (Petty Cash)","report_path":"OF -> Report -> 9.2 (Petty Cash Reimbursement Report)","sort_order":6},{"case_no":7,"scenario_text":"ตรวจสอบรายละเอียด PO ย้อนหลัง","report_path":"PO -> Report -> 6.1 / 2.1.3 / 2.8.1 (Detail Purchase Order Report)","sort_order":7},{"case_no":8,"scenario_text":"ตรวจสอบประวัติการการรับสินค้า (PO Receipt)","report_path":"PO -> Report -> 3.1 3.2 (Receipt by Material Code Report)","sort_order":8},{"case_no":9,"scenario_text":"ตรวจสอบสินค้าค้างรับ (PO Pending)","report_path":"PO -> Report -> 2.7.2 (P/O Pending Report)","sort_order":9},{"case_no":10,"scenario_text":"ตรวจสอบรายการที่เปิด PO/WO แล้วแต่ยังไม่ได้ตั้งหนี้","report_path":"PO -> Report -> 6.2 (PO&Contract Report) / 7.1 (Summary Report on PO/WO by Project)","sort_order":10},{"case_no":11,"scenario_text":"ตรวจสอบปริมาณวัสดุในคลัง (Stock Balance)","report_path":"IC -> Report -> 3.7.1 (Summary Stock Balance)","sort_order":11},{"case_no":12,"scenario_text":"ตรวจสอบรายการและมูลค่าตัดจ่ายวัสดุออกจากคลัง","report_path":"IC -> Report -> 4.1.2 (Document Issue Report)","sort_order":12},{"case_no":13,"scenario_text":"ตรวจสอบรายการเข้า-ออกและจ่ายสินค้าจากคลังทั้งหมด","report_path":"IC -> Report -> 2.2 (Stock Card Report)","sort_order":13},{"case_no":14,"scenario_text":"ตรวจสอบรายการเครื่องจักร แต่ละโครงการ","report_path":"FA -> Report -> 1.5.2 (Asset Report)","sort_order":14},{"case_no":15,"scenario_text":"ตรวจสอบรายการโอนย้ายเครื่องจักร","report_path":"FA -> Report -> 2.1 (Transfer Report)","sort_order":15},{"case_no":16,"scenario_text":"ตรวจสอบ Loop อนุมัติ เต็มฉบับ","report_path":"PO -> Report -> 19.0 (Authorized Signature Report)","sort_order":16},{"case_no":17,"scenario_text":"ตรวจสอบประวัติการอนุมัติโดยบุคลากรทุกฉนิด","report_path":"PO -> Report -> 5.2 (Approval Report by Authorized Person)","sort_order":17},{"case_no":18,"scenario_text":"ตรวจสอบเลขที่ APO จากเลข OF","report_path":"OF -> Report 2 (Petty Cash Tracking)","sort_order":18},{"case_no":19,"scenario_text":"ตรวจสอบเลขที่ APV/APS จากเลข PO/WO (มี PR)","report_path":"PO -> Report -> 2.3 (PO/WO Tracking)","sort_order":19},{"case_no":20,"scenario_text":"ตรวจสอบเลขที่ APV/APS จากเลข PO/WO (ไม่มี PR)","report_path":"PO -> Retrieve -> View PO Receive","sort_order":20},{"case_no":21,"scenario_text":"ตรวจสอบเลขที่ APP จากเลข APO/APV/APS","report_path":"AP -> Report -> 2.3 (AP Tracking)","sort_order":21},{"case_no":22,"scenario_text":"ตรวจสอบเลขที่ PO/WO จากเลข APV/APS","report_path":"AP -> Report -> 2.1.1 (A/P Voucher Report by Voucher)","sort_order":22},{"case_no":23,"scenario_text":"ตรวจสอบสถานะการวางบิลผู้รับเหมา","report_path":"OF -> Report -> 5.1 (Tracking Billing Subcontractor)","sort_order":23},{"case_no":24,"scenario_text":"ตรวจสอบยอด PL จากใบเตรียมจ่าย","report_path":"AP -> Report -> 2.3 (AP Voucher Tracking) -> Condition: Approve No.","sort_order":24}],"flows":[{"id":"BD-1.0","narrative":["1. เมื่อมีการประมูลงาน ฝ่ายงบประมาณโครงการสร้าง Tender ใหม่ ชื่อตามโครงการที่ไปประมูล (BD Module)","2. เปิดโครงการใหม่ (Create Project) ข้อมูลโครงการที่ BD Module โดยอ้างอิงข้อมูลดังนี้","» 2.1) Tender ที่สถานะ Award มาผูกกับข้อมูลโครงการ","3. กำหนดข้อมูล Budget ใน Template BOQ เมื่อข้อมูลเรียบร้อยให้ดำเนินการ Import BOQ/Budget เข้าในระบบ","4. Initial Budget (ปุ่ม Init Summary Cost Code) ใน BD Module","5. Initial Project Budget ใน PM Module","6. กำหนดการ Control Budget (กรณีที่ต้องการ Control งบประมาณ)","7. Approve Budget (ผู้มีอำนาจอนุมัติทำการ Approve Budget เพื่อล็อคเวอร์ชั่นของ Budget)","! การกำหนด Control Budget จะต้องกำหนด Control Budget By Summary Cost Code ที่ข้อมูลโครงการก่อน"]},{"id":"BD-1.1","narrative":["1. ฝ่ายงบประมาณโครงการ กดปุ่ม Revise Budget ที่ PM Module > Project Budget ในกรณีที่มีการแก้ไข (ยังไม่ต้องส่งอนุมัติ)","2. กำหนด BOQ/Budget เข้าไปใหม่โดยวิธีการ Revise ใน Budget ของสัญญาหลัก","3. Init Summary Cost Code ใน BD Module","4. Init. Budget Cost ใน PM Module","5. กำหนดการ Control Budget (กรณีที่ต้องการ Control งบประมาณ และส่งอนุมัติ)","6. Approve Budget — ผู้มีอำนาจอนุมัติทำการ Approve Budget เพื่อล็อคเวอร์ชั่นของ Budget","! เมื่อข้อมูลงบประมาณ Budget ถูก Reject ข้อมูลจะส่งกลับมาที่หน้าต่าง Project Budget","! กรณีต้องการ Revise Budget อีกครั้ง ให้กดปุ่ม Revise เพื่อเปิดให้ทำการ Create VO และ Transfer Budget ต่อไปได้"]},{"id":"BD-1.2","narrative":["Additional Work (BD Module)","1. หน่วยงานโครงการ ระบุโครงการเพื่อบันทึกรายการเปลี่ยนแปลง (เพิ่ม/ลด) โดยการ Import ตามไฟล์ Excel หรือคีย์เพิ่มทีละบรรทัด โดยระบุข้อมูลดังนี้","» Material code : กรณีควบคุม BOQ","» Cost code : ต้นทุนจัดทำงบประมาณเพิ่ม/ลด","» Qty./Unit : ปริมาณ และหน่วยของงานเพิ่ม/ลด","» Unit price : ราคาต่อหน่วยของ Material, Labor","2. Save และส่งอนุมัติ (Submit Approve)","3. หน้าต่าง Bill Of Quantity เลือก Tender no. ที่มีรหัสโครงการเดียวกันกับงานเพิ่ม/ลด","4. Create VO และดึง Ref.VO มาเชื่อมโยงกับ BOQ หลัก (Ref.VO คือเอกสาร Additional Work ที่ผ่านการอนุมัติแล้ว)","5. Init Summary Cost Code ระบบจะคำนวณ Cost code ที่ใช้ในงานเดียวกันรวมเป็นจำนวนเดียวกัน","6. Init. Budget Cost ใน PM Module เพื่อรับข้อมูลที่อัพเดตจาก BOQ","7. กำหนดการ Control Budget กรณีที่ต้องการควบคุมงบประมาณ","8. Approve Budget เมื่อต้องการ Lock การแก้ไขข้อมูลงบประมาณโครงการ"]},{"id":"PR-1.1","narrative":["1. หน่วยงาน / ผู้ควบคุมงานเปิดใบขอซื้อ (PR) โดยเลือก Ref. BOQ จากนั้นเลือกประเภทเอกสาร แยกเป็น Type 3 ประเภทหลัก ดังนี้","» 1.1 PR For PO / WO สำหรับทั้งซื้อวัสดุและงานจ้างเหมาในชุดเอกสารเดียวกัน (PR ใบเดียวมีทั้งซื้อวัสดุและจ้างเหมา)","» 1.2 PR For PO Only สำหรับซื้อวัสดุต่าง ๆ","» 1.3 PR For WO Only สำหรับงานจ้างเหมา","» การอ้างอิงจาก BOQ จะอ้างอิงรายการ/ปริมาณการสั่งซื้อ/สั่งจ้างที่ Control BOQ ไว้ และสัมพันธ์กับ Cost Code ที่มีการ Control Budget","2. ผู้มีอำนาจอนุมัติในระบบ และมีลายเซ็นลงนามบนเอกสาร","3. ฝ่ายจัดซื้อดึงใบขอซื้อ (PR) ที่ผ่านการอนุมัติแล้ว ไปเปิดใบสั่งซื้อ (PO) / หนังสือสั่งจ้าง (WO)","! กรณีซื้อวัสดุของโครงการ ให้เลือก Type เป็น PO Only","! กรณีจ้าง Subcontractor ให้เลือก Type เป็น WO Only (ทั้งจ้างแรงอย่างเดียว หรือทั้งของและแรง)","! กรณีค่าบริการ / ค่าเช่า / ค่าซ่อม ฯลฯ ที่มี W/T ให้เลือก Type เป็น WO Only"]},{"id":"PR-1.2","narrative":["1. หน่วยงานเปิดใบขอซื้อ (PR) โดยไม่อ้างอิง BOQ เลือกประเภทเอกสาร Type 3 ประเภทหลัก ดังนี้","» 1.1 PR For PO / WO สำหรับซื้อวัสดุและงานจ้างเหมาในชุดเอกสารเดียวกัน","» 1.2 PR For PO Only สำหรับซื้อวัสดุต่าง ๆ","» 1.3 PR For WO Only สำหรับงานจ้างเหมา","» การบันทึก PR แบบไม่อ้างอิง BOQ เป็นการเลือกรายการซื้อวัสดุ/งานจ้างเหมาแบบอิสระ: เลือก Material Code / Cost Code (M/S/L) / ระบุจำนวน / ราคาต่อหน่วย","2. ผู้มีอำนาจอนุมัติในระบบ และมีลายเซ็นลงนามบนเอกสาร","3. ฝ่ายจัดซื้อดึงใบขอซื้อ (PR) ที่ผ่านการอนุมัติแล้ว ไปเปิดใบสั่งซื้อ (PO) / หนังสือสั่งจ้าง (WO)","! กรณีซื้อวัสดุของโครงการ ให้เลือก Type เป็น PO Only","! กรณีจ้าง Subcontractor ให้เลือก Type เป็น WO Only","! กรณีค่าบริการ / ค่าเช่า / ค่าซ่อม ฯลฯ ที่มี W/T ให้เลือก Type เป็น WO Only"]},{"id":"PR-1.3","narrative":["1. หน่วยงานเปิดใบขอซื้อ (PR) เลือกประเภทเอกสาร PR For PO Only สำหรับซื้อวัสดุ และระบุรายละเอียดเพิ่มเติม","» 1.1) ระบุ Information: ประเภทการสั่งซื้อ \"Cost\" / ระบุชื่อผู้รับเหมาที่ช่อง Subcontractor / เลือกเอกสารหนังสือสั่งจ้างที่ช่อง \"เลขที่เอกสารสัญญาจ้าง (WO)\"","» กรณีซื้อวัสดุให้ผู้รับเหมา ต้องอ้างอิงเลขที่หนังสือสั่งจ้างทุกครั้ง เพื่อให้มีผลต่อการหัก Deduct Material ขั้นตอนรับวางบิลตามหนังสือสั่งจ้าง","» 1.2) ระบุรายละเอียดการสั่งซื้อ: เลือก Material Code / Cost Code (M / Dummy) / ระบุจำนวน / ราคาต่อหน่วย","» กรณีเกิดค่าใช้จ่ายในการซื้อของให้ผู้รับเหมา ให้กำหนดรหัสต้นทุน Dummy เป็น \"Material Cost Code สำหรับซื้อของให้ผู้รับเหมา\" หรือบันทึกเป็นต้นทุนตามแต่ละงานได้","2. ผู้มีอำนาจอนุมัติในระบบ และมีลายเซ็นลงนามบนเอกสาร","3. ฝ่ายจัดซื้อดึงใบขอซื้อ (PR) ที่อนุมัติแล้ว ไปเปิดใบสั่งซื้อ (PO)"]},{"id":"PO-1.1","narrative":["1. ฝ่ายจัดซื้อทำการเปรียบเทียบราคา โดยจัดทำเอกสารขอราคา ได้ 2 กรณี: ขอราคาโดยอ้างอิงจาก PR และขอราคาแบบอิสระ (กำหนดรายการวัสดุที่ต้องการขอราคาเอง)","» 1.1) บันทึกเอกสารขอราคา โดยอ้างอิง PR และระบุร้านค้า (Vendor) — แบบฟอร์มใบขอราคาส่งให้ร้านค้า","» 1.2) บันทึกราคาตามใบเสนอราคาของร้านค้า แล้วเปรียบเทียบราคาที่ PO > Compare Price โดยอ้างอิงจากเอกสารใบขอราคา","2. ฝ่ายจัดซื้อดึงใบขอซื้อ (PR) ที่อนุมัติแล้วมาเปิดใบสั่งซื้อ (PO)","3. ผู้มีอำนาจอนุมัติเอกสารในระบบ และมีลายเซ็นลงนามบนเอกสาร","4. ฝ่ายจัดซื้อส่งใบสั่งซื้อ (PO) ให้ร้านค้า — ร้านค้ารับ PO และเตรียมของส่ง"]},{"id":"PO-1.2","narrative":["1. ฝ่ายจัดซื้อดึงใบขอซื้อ/ขอจ้าง (PR For PO/WO หรือ PO Only / WO Only) ที่อนุมัติแล้วมาเปิดใบสั่งซื้อ (PO)/ใบสั่งจ้าง (WO) และระบุข้อมูลจำเป็น","» ระบุโครงการ/แผนก (กรณีโครงการต้องระบุ Job ด้วยทุกครั้ง)","» เลือกเอกสารใบขอซื้อ (PR) โดยกดปุ่มอ้างอิงเอกสารใบขอซื้อ (PR/MR No.)","» ประเภทการสั่งซื้อ/สั่งจ้าง: 1) Cost ค่าใช้จ่ายของโครงการ/แผนก  2) Asset ทรัพย์สินโครงการ/แผนก  3) Stock สินค้าคงเหลือเพื่อบริหารคลัง (Stock IC)","2. ผู้มีอำนาจอนุมัติในระบบ และมีลายเซ็นลงนามบนเอกสาร","3. ฝ่ายจัดซื้อส่งใบสั่งซื้อ (PO) ให้ร้านค้า หรือส่งใบสั่งจ้าง (WO) ให้ผู้รับจ้าง/ผู้รับเหมา","» ร้านค้ารับ PO เตรียมส่งของ","» ผู้รับจ้าง/ผู้รับเหมารับ WO เพื่อดำเนินงานตามเอกสารสั่งจ้าง"]},{"id":"IC-1.1","narrative":["1. ร้านค้าส่งสินค้าตามใบสั่งซื้อ (PO) โดยแนบใบกำกับภาษี / ใบส่งของชั่วคราว","2. หน่วยงานทำการรับสินค้าตามใบสั่งซื้อ (PO) ที่ขั้นตอนรับสินค้า (PO Receive)","3. พิจารณาว่าวัสดุต้องรับเข้าสต๊อกหรือไม่","» ถ้าไม่รับเข้าสต๊อก จะไม่อ้างอิงไปขั้นตอนรับ IC Receive (ข้อ 4) — สินค้าบางประเภทไม่นำเข้า Stock เช่น ของที่ซื้อมาใช้ไป บริหารการเบิกไม่ได้","4. ถ้ารับเข้าสต๊อก หน่วยงานรับสินค้าที่ IC Receive ระบุสถานที่เก็บสินค้า โดยกำหนดข้อมูลคลัง (Warehouse)","5. แผนกบัญชีดึงรายการที่ทำรับของตามใบสั่งซื้อ (PO Receive) แล้วอ้างอิงไปตั้งเจ้าหนี้ เพื่อทำจ่ายชำระในขั้นถัดไป","! เมื่อสั่งซื้อและร้านค้าจัดส่งแล้ว ต้องจัดทำเอกสารใบรับของในระบบ เพื่อให้บัญชีอ้างอิง PO Receive ไปตั้งหนี้จนถึงจ่ายชำระเงิน"]},{"id":"IC-1.2","narrative":["1. หน่วยงานทำรับสินค้าเข้าคลังผ่าน IC Receive โดยเลือกประเภทเอกสารเป็น Type Other (ต้องใส่ราคาในช่อง IC Cost = ราคารวมทั้งหมด และตัวแปลงหน่วยถ้ามี)","2. หน่วยงานทำรับ IC Receive ระบุสถานที่เก็บวัสดุหรือคลังสินค้า (Warehouse)","! เอกสารที่ใช้ทำรับ อาจเป็นใบเสร็จรับเงิน / ใบกำกับภาษี / บิลที่หน่วยงานซื้อวัสดุมา โดยไม่ผ่านกระบวนการจัดซื้อ","! Receive Other เช่น สินค้าที่ซื้อโดยเงินสด หรือผ่าน Petty Cash ที่ต้องการเก็บเข้าสต๊อก"]},{"id":"IC-1.3","narrative":["1. จัดทำเอกสารใบเตรียมเบิก โดยเลือก (Entry Document Issue) ระบุ Type Issue","» เลือกรายการวัสดุที่จะเบิก (ดึงจาก Material Balance)","» ระบุ Warehouse","» ระบุ Type และ Area (พื้นที่ที่จะนำวัสดุไปใช้งาน)","» ระบุชื่อผู้ขอเบิก (Ref. by)","» ระบุหมายเหตุเพิ่มเติม (Remark)","2. ดึงเอกสารใบเตรียมเบิกมาตัดสต๊อก โดยเลือก (IC Issue)","» กดปุ่ม Ref. Document เพื่อดึงเอกสารใบเตรียมเบิกมาตรวจสอบ และบันทึกตัดเบิกในระบบ"]},{"id":"IC-1.4","narrative":["1. จัดทำเอกสารใบเตรียมเบิก (Entry Document) ระบุข้อมูล Type Transfer","» ระบุโครงการปลายทาง (To Project) ที่จะรับโอนวัสดุ","» ระบุ Type และ Area (พื้นที่ที่นำวัสดุไปใช้งาน หรือชื่อโครงการที่โอนไป)","» ระบุชื่อผู้ขอโอน (Ref. by)","» เลือกรายการวัสดุที่จะโอน (ดึงจาก Material Balance)","» ระบุ Cost Code (ต้นทางและปลายทาง)","2. ทำการโอนวัสดุไปยังหน่วยงานผู้รับโอน (Inventory Transfer) แยกการโอนเป็น 2 ประเภท","» 2.1) โอนวัสดุโดยอ้างอิงใบเตรียมโอน (Ref. Entry Document (IC))","» 2.2) สโตร์กลางดึงใบขอวัสดุ (PR For Stock) ที่อนุมัติแล้ว ไปเปิดใบโอนย้ายวัสดุ (IC Transfer) โดย Ref.PR Stock Center","» เงื่อนไขข้อ 2.2: ต้องมี PR For Stock ส่งมาก่อน / เกิดเมื่อหน่วยงานขอวัสดุจากโครงการสโตร์กลางเท่านั้น / ไม่ต้องทำใบเตรียมโอน (ข้อ 1)","3. หน่วยงานผู้ขอโอนบันทึกรายการรับโอน ระบุ Warehouse ทำการรับของ (IC Receive Transfer)","! Inventory Transfer เป็นการโอนให้โครงการ (มีการปรับปรุงต้นทุนระหว่างโครงการ) ส่วนบัญชีบันทึก GL ปรับต้นทุนเข้าโครงการ","! รับของต้องเท่ากับจำนวนที่โอน ไม่ให้แก้ไขจำนวนที่รับของ"]},{"id":"Billing-1.1","narrative":["1. ผู้รับเหมารับหนังสือสั่งจ้าง และทำเอกสารขอเบิกเงินล่วงหน้า","2. หน่วยงานทำบันทึกรับวางบิลตัดผลงานผู้รับเหมา เลือกประเภทการรับวางบิลเป็นเงินล่วงหน้า (Advance Payment)","» ระบบมีประเภทการรับวางบิล 3 ประเภท: ค่างวดงาน (Progress) / เงินล่วงหน้า (Advance) / เงินประกันผลงาน (Retention)","3. ผู้มีอำนาจในหน่วยงานอนุมัติเอกสารในระบบ ลงลายเซ็น และส่งเอกสารให้แผนกบัญชี","4. แผนกบัญชีดึงรายการไปตั้งหนี้ APS"]},{"id":"Billing-1.2","narrative":["1. ผู้รับเหมาส่งผลงาน โดยนำส่งเอกสารส่งผลงานแต่ละงวด / หรือตามมูลค่างาน","2. หน่วยงานทำบันทึกรับวางบิลตัดผลงานผู้รับเหมา และบันทึกรายการหักต่าง ๆ เช่น ค่าความเสียหาย ค่าเสื้อ","» ระบุประเภทการรับวางบิลเป็น ค่างวดงาน (Progress Payment)","» ระบุจำนวนเงินค่างวดงาน","» ระบุวันที่ส่งมอบงาน / วันที่วางบิล และวันที่ทำจ่าย","» ระบุหมายเหตุ และข้อมูลต่าง ๆ","3. ผู้มีอำนาจในหน่วยงานอนุมัติเอกสาร ลงลายเซ็น และส่งให้แผนกบัญชี","4. แผนกบัญชีดึงรายการไปตั้งหนี้ APS"]},{"id":"Billing-1.3","narrative":["1. หลังจากผู้รับเหมาดำเนินงานตามหนังสือสั่งจ้างเสร็จเรียบร้อย และครบกำหนดการรับประกันผลงานแล้ว ทำเอกสารขอเบิกเงินประกันผลงานคืน","2. หน่วยงานทำบันทึกรับวางบิลตัดผลงานผู้รับเหมา เลือกประเภทการรับวางบิลเป็นเงินประกันผลงาน (Retention Payment)","3. ผู้มีอำนาจในหน่วยงานอนุมัติเอกสาร ลงลายเซ็น และส่งให้แผนกบัญชี","4. แผนกบัญชีดึงรายการไปตั้งหนี้ APS"]},{"id":"OF-1.1","narrative":["1. หน่วยงานเปิดใบขอเบิกเงิน (OF) เป็นค่าใช้จ่ายต่าง ๆ ที่นำเงินสดย่อยไปจ่าย","» เลือก Type : Petty cash (ใบเบิกเงินสดย่อย)","» ระบุ Vendor Type เป็น Employee (ชื่อพนักงานผู้ถือเงินสดย่อย)","» เลือกโครงการ ระบบงาน หรือแผนก / ระบุหมายเหตุ","» เลือกเรื่องจ่าย (Expense Code) ตามค่าใช้จ่ายในใบเสร็จรับเงิน","» ระบุเลขที่เอกสาร / จำนวนเงิน / ภาษีมูลค่าเพิ่ม (ถ้ามี) / ภาษีหัก ณ ที่จ่าย (ถ้ามี)","2. ผู้มีอำนาจทำการอนุมัติเอกสาร OF","3. แผนกบัญชีตรวจสอบเอกสาร และดึงรายการไปบันทึกตั้งหนี้","» เอกสารประกอบการเบิกเงิน","» บิล / ใบเสร็จรับเงิน / ใบกำกับภาษี / ใบแจ้งหนี้"]},{"id":"OF-1.2","narrative":["1. หน่วยงานเปิดใบขอเบิกเงิน (OF) เป็นเงินทดรองจ่าย (Advance)","» เลือก Type : Advance (เงินทดรองจ่าย)","» ระบุ Vendor Type เป็น Employee (ชื่อพนักงานผู้ที่ต้องการใช้เงินทดรองจ่าย)","» เลือกโครงการ ระบบงาน หรือแผนก / ระบุหมายเหตุ","» เลือกเรื่องจ่าย (Expense Code) เป็นเงินทดรองจ่าย เช่น เงินทดรองจ่าย - พนักงาน","» ระบุจำนวนเงินที่ต้องการ","2. ผู้มีอำนาจทำการอนุมัติบนเอกสาร OF","3. แผนกบัญชีตรวจสอบเอกสาร และดึงรายการไปบันทึกตั้งหนี้","» เอกสารประกอบการเบิกเงิน","» บันทึกภายใน ขอเบิกเงินล่วงหน้า"]},{"id":"OF-1.3","narrative":["1. หน่วยงานเปิดใบขอเบิกเงิน (OF)","» เลือก Type : Clear advance (เคลียร์เงินทดรองจ่าย)","» ระบุ Vendor Type เป็น Employee (ชื่อพนักงานคนเดียวกับผู้ขอเบิกเงินทดรองจ่าย)","» เลือกโครงการ ระบบงาน หรือแผนก / ระบุหมายเหตุว่าเคลียร์เงินทดรองจ่าย","» เลือกเรื่องจ่าย (Expense Code) / ระบุเลขที่เอกสาร / จำนวนเงิน / VAT / WHT (ถ้ามี)","» กดปุ่ม Advance เลือกเอกสารชุดที่เบิกเงินทดรองจ่าย เพื่อเคลียร์ในชุดเดียวกันให้ถูกต้อง","» ถ้ามีเงินต้องคืน ให้เพิ่มบรรทัดเลือกเป็นธนาคารที่พนักงานโอนเข้า หรือเลือกเป็นเงินสด","2. ผู้มีอำนาจทำการอนุมัติบนเอกสาร OF","3. แผนกบัญชีตรวจสอบเอกสาร และดึงรายการไปบันทึกตั้งหนี้ — ถ้ามีส่วนเกิน บัญชีดึงไปทำจ่ายต่อ หากไม่มีส่วนเกิน จบที่ขั้นตั้งหนี้ APO"]},{"id":"OF-1.4","narrative":["1. หน่วยงานเปิดใบขอเบิกเงิน (OF) เป็นค่าใช้จ่ายต่าง ๆ ให้กับบุคคลภายนอก","» เลือก Type : Other (ใบเบิกบันทึกจ่ายอื่น ๆ)","» ระบุ Vendor Type เป็น External (ชื่อหน่วยงาน/บุคคลภายนอก)","» เลือกโครงการ ระบบงาน หรือแผนก / ระบุหมายเหตุ","» เลือกเรื่องจ่าย (Expense Code) / ระบุเลขที่เอกสาร / จำนวนเงิน / VAT / WHT (ถ้ามี)","2. ผู้มีอำนาจทำการอนุมัติบนเอกสาร OF","3. แผนกบัญชีตรวจสอบเอกสาร และดึงรายการไปบันทึกตั้งหนี้","» เอกสารประกอบการเบิกเงิน","» บิล / ใบเสร็จรับเงิน / ใบกำกับภาษี / ใบแจ้งหนี้"]},{"id":"AP-1.1","narrative":["การบันทึกตั้งหนี้ APV (Type Normal) — จัดซื้อ/หน่วยงาน/Admin Site บันทึกรับสินค้าตามใบสั่งซื้อ (PO) แล้วส่งเอกสารให้บัญชีตั้งเจ้าหนี้: ใบรับสินค้า (RC) / ใบส่งของ / ใบกำกับภาษี / เอกสารใบสั่งซื้อ (PO)","1. ฝ่ายบัญชี ดึงตั้งหนี้ ที่มาจากการรับของตามใบสั่งซื้อ (PO) ได้เอกสารตั้งเจ้าหนี้ APV","2. ฝ่ายบัญชีบันทึกอนุมัติจ่ายจากเอกสารตั้งเจ้าหนี้ APV (Pre-Payment APV)","3. ฝ่ายการเงินบันทึกการจ่ายชำระ โดยจัดทำเช็ค/โอนเงิน หรือเงินสด (Cheque/Bank Transfer/Cash) ได้ใบสำคัญจ่าย (F)","4. ฝ่ายการเงินบันทึกยืนยันการจ่าย ได้เอกสาร (PV)","5. ฝ่ายบัญชีบันทึกตัดเจ้าหนี้ (Clear AP)","! กรณีจ่ายด้วยเงินสด ต้องดึงเอกสาร PV ไปบันทึกตัดเจ้าหนี้ (Clear AP) ทุกครั้ง","! การแนบใบกำกับภาษีซื้อ ระบุได้ 2 ขั้นตอน: *1 = ขั้นตอนตั้งหนี้ / *2 = ขั้นตอนจ่ายชำระ"]},{"id":"AP-1.2","narrative":["การบันทึกตั้งหนี้ APS — หน่วยงาน/Admin Site บันทึกเบิกตามใบสั่งจ้าง (WO) แบ่งเป็น 3 ประเภทการรับวางบิล: Advance / Progress / Retention เมื่อบันทึกและส่งอนุมัติแล้ว ส่งเอกสารให้บัญชีตั้งเจ้าหนี้","1. ฝ่ายบัญชี ดึงตั้งหนี้โดยอ้างอิง Bill No. ที่มาจากการบันทึกเบิกผลงานผู้รับเหมา (Billing) ได้เอกสารตั้งเจ้าหนี้ APS","2. ฝ่ายบัญชีบันทึกอนุมัติจ่ายจากเอกสารตั้งเจ้าหนี้ APS (Pre-Payment APS)","3. ฝ่ายการเงินบันทึกการจ่ายชำระ โดยจัดทำเช็ค/โอนเงิน หรือเงินสด ได้ใบสำคัญจ่าย (F)","4. ฝ่ายการเงินบันทึกยืนยันการจ่าย ได้เอกสาร (PV)","5. ฝ่ายบัญชีบันทึกตัดเจ้าหนี้ (Clear AP)","! การแนบใบกำกับภาษีซื้อ ระบุได้ 2 ขั้นตอน: *1 = ขั้นตอนตั้งหนี้ / *2 = ขั้นตอนจ่ายชำระ"]},{"id":"AP-1.3","narrative":["1. ฝ่ายบัญชี ดึงตั้งหนี้ ที่มาจากเอกสารการเบิกอื่น ๆ (APO)","2. ฝ่ายบัญชีอนุมัติจ่ายจากเอกสารตั้งเจ้าหนี้ APO (Pre-Payment APO)","3. ฝ่ายการเงินบันทึกการจ่ายชำระ โดยจัดทำเช็ค/โอนเงิน หรือเงินสด ได้ใบสำคัญจ่าย (F)","4. ฝ่ายการเงินบันทึกยืนยันการจ่าย ได้เอกสาร (PV)","5. ฝ่ายบัญชีบันทึกตัดเจ้าหนี้ (Clear AP)","! กรณีจ่ายด้วยเงินสด ต้องดึงเอกสาร PV ไปบันทึกตัดเจ้าหนี้ (Clear AP) ทุกครั้ง","! *1 = ถ้า OF เป็น Type : Employee ได้ใบกำกับภาษีในขั้นตอนทำ OF / *2 = ถ้า OF เป็น Type : External ได้รับใบกำกับภาษีในขั้นตอนยืนยันการจ่าย"]},{"id":"AR-1.1","narrative":["1. บันทึกความคืบหน้าโครงการ (Project Progress) ใน Module OF","» เลือก/ระบุ Payment Type: Down (เงินล่วงหน้า) / Progress (เงินงวดงาน) / Retention (เงินประกันผลงาน)","» Save เพื่อบันทึก","2. ยืนยันการเบิกผลงาน / Submit Certificate","3. แผนกบัญชีเปิดใบแจ้งหนี้ โดยระบุประเภทการเบิก 3 ประเภท: Down / Progress / Retention","4. บันทึกตั้งลูกหนี้ รายได้","5. ออกใบเสร็จรับเงิน","6. บันทึกรับชำระเงินตามใบเสร็จรับเงิน","7. บันทึกตัดลูกหนี้"]},{"id":"AR-1.1b","narrative":["การบันทึก AR - Invoice Other","1. กำหนดข้อมูลประเภทรายได้อื่น ๆ ซึ่งเชื่อมโยงกับรหัสบัญชีที่ต้องการบันทึกรายได้อื่น ๆ (Master Type Of Income >> Revenue Other)","2. ฝ่ายบัญชีบันทึกใบแจ้งหนี้ประเภทอื่น ๆ","» เลือก Type : Trading หรือ Service","» ระบุรายการของใบแจ้งหนี้อื่น ๆ","» ระบุจำนวนหน่วย / ราคาต่อหน่วย / จำนวนเงินรวม","3. ฝ่ายบัญชีบันทึกตั้งลูกหนี้ รายได้","4. ฝ่ายการเงินออกใบเสร็จรับเงิน","5. ฝ่ายการเงินบันทึกรับชำระเงินตามใบเสร็จรับเงิน","6. ฝ่ายบัญชีบันทึกตัดลูกหนี้"]},{"id":"AR-1.2","narrative":["การบันทึกรับเงินลูกหนี้อื่น ๆ แบบไม่ออกใบแจ้งหนี้ — กรณีรับชำระเงินจากลูกหนี้โดยไม่ผ่านการบันทึกใบแจ้งหนี้ (Invoice)","1. ฝ่ายบัญชี/การเงิน บันทึกเอกสารโดยระบุข้อมูล","» เลือกโครงการ หรือแผนก","» ระบุ Option Type เลือกประเภทรายได้","» ระบุจำนวนเงิน / ระบุว่าเงินเข้าธนาคาร / ระบุเงื่อนไข / ระบุหมายเหตุ (Remark)","» เลือกรหัสบัญชี Dr. / Cr. ตามที่เกิดขึ้นจริง เช่น Dr. ธนาคาร / Cr. รายได้","2. ตรวจสอบความถูกต้องของการบันทึก จากนั้นบันทึกเอกสาร (RV)"]},{"id":"FA-1.1","narrative":["หน่วยงานผู้ดูแลทรัพย์สิน:","1. บันทึกทรัพย์สินในระบบ (Fix Asset)","2. ทุกสิ้นเดือน บันทึกตรวจนับทรัพย์สินที่อยู่แต่ละหน่วยงาน / โครงการ หรือแผนกต่าง ๆ","3. เมื่อถึงสิ้นเดือน บันทึกคำนวณค่าเสื่อมราคาที่ FA Depreciation","ฝ่ายบัญชี: บันทึกปรับปรุงค่าเสื่อมราคาทรัพย์สินที่ Module GL","! การบันทึกบัญชี: Dr. ค่าเสื่อมราคา - ทรัพย์สิน / Cr. ค่าเสื่อมราคาสะสม - ทรัพย์สิน"]},{"id":"FA-1.2","narrative":["หน่วยงานผู้ดูแลทรัพย์สิน:","1. บันทึกโอนย้ายทรัพย์สิน — ค่าเสื่อมราคาประจำเดือนจะถูกบันทึกที่หน่วยงานปลายทาง (กรณีโอนย้ายประเภท Transfer)","2. เมื่อถึงสิ้นเดือน บันทึกคำนวณค่าเสื่อมราคาที่ FA Depreciation","ฝ่ายบัญชี: บันทึกปรับปรุงค่าเสื่อมราคาทรัพย์สินที่ Module GL","! Dr. ค่าเสื่อมราคา - ทรัพย์สิน / Cr. ค่าเสื่อมราคาสะสม - ทรัพย์สิน"]},{"id":"FA-1.3","narrative":["1. ระบุทรัพย์สินที่จะตัดจ่าย ทรัพย์สินมี 3 ประเภท: 1.1 ขาย (Sale) / 1.2 หมดอายุ (Expired) / 1.3 สูญหาย (Loss)","2. บันทึกตัดจ่ายทรัพย์สินที่ Module FA","3. ณ สิ้นเดือน คำนวณค่าเสื่อมราคา และบันทึกบัญชีที่ Module GL","! 1.1 ขาย: Dr. ธนาคาร/เงินสด, ค่าเสื่อมราคาสะสม, ค่าเสื่อมราคา (ถึงวันขาย), กำไร(ขาดทุน)จากการขาย / Cr. ทรัพย์สิน, กำไร(ขาดทุน)จากการขาย — Book value = ราคาทรัพย์สิน หัก ค่าเสื่อมราคาสะสม","! 1.2 หมดอายุ: Dr. ค่าเสื่อมราคาสะสม / Cr. ทรัพย์สิน","! 1.3 สูญหาย: Dr. ค่าเสื่อมราคาสะสม, ขาดทุนจากทรัพย์สินสูญหาย / Cr. ทรัพย์สิน"]},{"id":"GL-1.1","narrative":["1. การบันทึกปรับปรุงรายการ (JV) เช่น สมุดรายวันซื้อ / ทั่วไป / จ่าย / รับ","» GL Module > บันทึกรายการ > บันทึกสมุดรายวัน > สร้างใบสำคัญ","2. การบันทึกบัญชีแบบอัตโนมัติ — ข้อมูลส่งมาจาก Module อื่น ๆ ดังนี้","» FA Depreciation (ค่าเสื่อมราคา) / FA Write off (ตัดจำหน่ายทรัพย์สิน) / IC (ตัดและโอนย้ายต้นทุนวัสดุ)","» Copy Voucher / Reverse Voucher (กลับรายการ) / Rental (ค่าเช่าทรัพย์สิน)","» Unbill progress submit / Retention Write off / PO Write off","» Cost Sheet (ต้นทุนอสังหาฯ) / Report GL (ปรับปรุงรายได้-ต้นทุน) / MA to GL (ค่าซ่อม) / RE WIP Out (ต้นทุนบ้านสร้างเสร็จ)"]},{"id":"GL-1.2","narrative":["1. การพิมพ์รายงานบัญชีแยกประเภท","» GL > Report > รายงานบัญชีแยกประเภท (General ledger)","» รายงานต่าง ๆ: 1) รายละเอียด (Detail) 2) Detail ตามโครงการ/แผนก 3) รายงานงบทดลอง 4) งบทดลองตามโครงการ/แผนก","» 5) บัญชีแยกประเภท (ก่อน/หลัง) 6) งบทดลอง 7) สถานะรายรับรายจ่ายแต่ละโครงการ 8) ทุก Module แต่ไม่มีรายละเอียดโครงการ","2. การพิมพ์รายงานงบทดลอง","» GL > Report > งบทดลอง","» เรียกรายงานตามประเภท: 1) Period 2) Year"]},{"id":"AP-Close","narrative":["การปิดงบการเงิน — โอนข้อมูลจาก AP ไปยังบัญชีแยกประเภท (ข้อมูลการตั้งหนี้/จ่ายชำระอยู่ในระบบ AP เท่านั้น ต้องโอนไป GL ก่อนจึงดูรายงานทางการเงินได้)","1.1 กระทบยอดให้ถูกต้อง ครบถ้วน และตรงกันระหว่างรายงานใน Module AP กับ Module GL เช่น","» รายงานภาษีหัก ณ ที่จ่าย ↔ บัญชีภาษีหัก ณ ที่จ่าย","» รายงานภาษีซื้อ ↔ บัญชีภาษีซื้อ","» รายงานเจ้าหนี้คงเหลือ ↔ บัญชีเจ้าหนี้","1.2 กระทบยอดการบันทึก Cost Code ให้ครบถ้วน (เทียบ Project status : GL = Project Cost control Report > Summary by Project : GL)","1.3 ส่งข้อมูลไประบบบัญชีแยกประเภท — ระบุ ปี/งวดบัญชี โอนทีละกลุ่มเอกสาร: APV (PO) / APS (Subcontractor) / APO (Other) / PL (ยกเลิกการโอนเพื่อแก้ไขได้)","1.4 แก้ไข Transaction — ตรวจสอบว่าบัญชี/รายงานใดผิดพลาด แล้วกลับไปแก้ที่ AP Module โดยถอยขั้นตอนทีละ Step จากขั้นตอนสุดท้ายไปถึงจุดที่ผิด"]},{"id":"AR-Close","narrative":["โอนข้อมูลจาก AR ไปยังบัญชีแยกประเภท (การรับรู้รายได้/รายได้รับล่วงหน้าอยู่ในระบบ AR เท่านั้น ต้องโอนไป GL ก่อน)","2.1 กระทบยอดให้ถูกต้อง ครบถ้วน และตรงกันระหว่างรายงานใน Module AR กับ Module GL เช่น","» รายงานภาษีถูกหัก ณ ที่จ่าย ↔ บัญชีภาษีถูกหัก ณ ที่จ่าย","» รายงานภาษีขาย ↔ บัญชีภาษีขาย","» รายงานลูกหนี้คงเหลือ ↔ บัญชีลูกหนี้","2.2 ส่งข้อมูลไประบบบัญชีแยกประเภท — ระบุ ปี/งวดบัญชี/Data Type/กลุ่มเอกสาร โอนทีละกลุ่ม: AR (Construction) / AR (Trading) / AR (Other) / AR (Real Estate) / RL-RV"]},{"id":"GL-Close","narrative":["3. ผ่านรายการไปยังบัญชีแยกประเภท (Posting) — หลังโอนข้อมูลจาก AP และ AR มาที่ GL ข้อมูลในสมุดรายวันจะมีสถานะ Not post (N) ต้องทำ Posting โดยระบุ GL Year และ GL Period (เลือก Post บางรายการได้ ระบุเลขที่/วันที่ Voucher; ยกเลิก Post เพื่อแก้ไขได้)","4. สร้างรายงานทางการเงิน (Custom Financial Report) — เช่น งบแสดงฐานะการเงิน / งบกำไรขาดทุน / งบกระแสเงินสด ผ่านข้อมูลที่ Posting แล้ว กำหนดช่วงเวลาได้ (รูปแบบรายงานสร้างครั้งเดียวใช้ได้ตลอด)","4.1 การพิมพ์รายงานทางการเงิน — พิมพ์ได้เมื่อทำขั้นตอนที่ 3 เรียบร้อยแล้ว","5. การปิดบัญชี (Close Year) — หลังสิ้นงวดและตรวจสอบโดยผู้สอบบัญชีแล้ว ปิดรายได้และค่าใช้จ่ายเพื่อเริ่มรอบใหม่ ระบุปีบัญชี และรหัสบัญชีกำไรขาดทุนสุทธิ/กำไรสะสมที่ยังไม่ได้จัดสรร"]}]}$sop$::jsonb as j;

delete from sop_scenario_attachments;
delete from sop_scenario_steps;
delete from sop_scenario_modules;
delete from sop_reports;
delete from sop_scenarios;

insert into sop_scenarios (no, module, display_no, sort_order, title_th, title_en, problem, ref, note, date_added)
select (s->>'no')::int, s->>'module', s->>'display_no', (s->>'sort_order')::int, s->>'title_th', s->>'title_en',
       coalesce(s->>'problem', ''), s->>'ref', s->>'note', s->>'date_added'
  from _sop_live2, jsonb_array_elements(j->'scenarios') s;

insert into sop_scenario_steps (scenario_no, step_order, is_substep, style, text)
select (s->>'no')::int, st.ord::int, (st.v->>'style') in ('sub','sub2'), st.v->>'style', st.v->>'text'
  from _sop_live2, jsonb_array_elements(j->'scenarios') s,
       jsonb_array_elements(s->'steps') with ordinality as st(v, ord);

insert into sop_scenario_modules (scenario_no, module)
select (s->>'no')::int, m.v
  from _sop_live2, jsonb_array_elements(j->'scenarios') s, jsonb_array_elements_text(s->'extra') as m(v)
on conflict do nothing;

insert into sop_scenario_attachments (scenario_no, sort, label, url)
select (s->>'no')::int, a.ord::int, a.v->>'label', a.v->>'url'
  from _sop_live2, jsonb_array_elements(j->'scenarios') s,
       jsonb_array_elements(s->'attachments') with ordinality as a(v, ord);

insert into sop_reports (case_no, scenario_text, report_path, sort_order)
select (r->>'case_no')::int, r->>'scenario_text', r->>'report_path', (r->>'sort_order')::int
  from _sop_live2, jsonb_array_elements(j->'reports') r;
select setval(pg_get_serial_sequence('sop_reports', 'id'),
              greatest(coalesce((select max(id) from sop_reports), 0), 1));

-- คำบรรยายขั้นตอนของผังกระบวนการ (ของเราว่างอยู่ทั้ง 33 ผัง)
update sop_flows f
   set narrative = array(select jsonb_array_elements_text(x.v->'narrative')), updated_at = now()
  from _sop_live2, jsonb_array_elements(j->'flows') as x(v)
 where f.id = x.v->>'id';

update sop_meta mt set title = x.j->'meta'->>'title', subtitle = x.j->'meta'->>'subtitle',
       manual = x.j->'meta'->>'manual', version = x.j->'meta'->>'version',
       effective = x.j->'meta'->>'effective', scope = x.j->'meta'->>'scope',
       purpose = x.j->'meta'->>'purpose',
       notes = array(select jsonb_array_elements_text(x.j->'meta'->'notes')),
       updated_at = now()
  from _sop_live2 x where mt.id = true;
